(window.GIM_TS=window.GIM_TS||{})["Pesachim.4"]={"from":96,"a":[["\u0003כאיסורו, מה איסורו\u0004 של חמץ ושל בשר קודש שנפסל שאסור באכילה שיעורו \u0003בכזית, אף חזרתו בכזית.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ובה דעה נוספת, \u0003ר' נתן אומר: זה וזה\u0004 שיעורו \u0003כשתי ביצים, ולא הודו לו חכמים.\u0004","כיון שדנו כאן בענין היציאה מירושלים למקומות הסמוכים לה, מביאים כמה דרשות בנושא קרוב. נאמר: \u0003\"והיה ביום ההוא לא יהיה אור יקרות וקפאון\"\u0004 (זכריה יד, ו), ותוהים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"יקרות וקפאון\"?\u0004 \u0003אמר ר' אלעזר: זה אור שיקר\u0004 (חשוב) \u0003בעולם הזה אור החמה, וקפוי\u0004 (קל ומזולזל) \u0003לעולם הבא,\u0004 שאז יהא אור הלבנה כאור החמה ואור החמה יהיה שבעתיים.","","ו\u0003ר' יוחנן אמר: אלו\u0004 הלכות \u0003נגעים ואהלות, שיקרים הם\u0004 ונחשבות מן ההלכות הקשות ביותר עתה \u0003בעולם הזה, וקפויין\u0004 (קלים) \u0003הן לעולם הבא,\u0004 שאנשים יחכימו הרבה.","\u0003ור' יהושע בן לוי אמר: אלו בני אדם שיקרים הן בעולם הזה, וקפויים הן\u0004 (אינם נחשבים) \u0003לעולם הבא. כי הא\u0004 \u0005[כמו זה]\u0006 המעשה שאירע ש\u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע בן לוי חלש ואיתנגיד\u0004 \u0005[חלה ו\u0006עמד \u0005לגווע],\u0006 \u0003כי הדר\u0004 \u0005[כאשר חזר\u0006 לבריאותו\u0005]\u0006 \u0003אמר ליה אבוה\u0004 \u0005[לו אביו]:\u0006 \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 בזמן שהיית קרוב לגסיסה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עולם הפוך ראיתי, עליונים\u0004 כלומר, אנשים שהם חשובים כאן, שם הם נמצאים \u0003למטה, ותחתונים למעלה. אמר לו: בני, עולם ברור ראית.\u0004 שהעולם שראית הוא הוא עולם האמת, ובו היחסים בין הבריות הם כראוי להם. ועוד שאל: \u0003ואנן היכי התם\u0004 \u0005[ואנחנו\u0006 תלמידי החכמים \u0005איך\u0006 אנו \u0005שם]?\u0006 ענה לו: \u0003כי היכי דאיתו אנן הכא, הכי איתינן התם\u0004 \u0005[כמו שאנו כאן, כך אנו שם].\u0006","ועוד סיפר לו: \u0003ושמעתי שהיו אומרים\u0004 באותו עולם: \u0003אשרי מי שבא לכאן ותלמודו בידו. ושמעתי\u0004 עוד \u0003שהיו אומרים\u0004 שם: \u0003הרוגי מלכות אין אדם יכול לעמוד במחיצתן\u0004 מפני קדושתם.","ושואלים: \u0003ומאן נינהו\u0004 \u0005[ומי הם]\u0006 הרוגי מלכות אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' עקיבא וחביריו\u0004 שנהרגו על קידוש השם — אין הדבר מסתבר, וכי מעלתם \u0003משום\u0004 שהם \u0003הרוגי מלכות ותו\u0004 \u0005[ויותר]\u0006 \u0003לא?!\u0004 והרי גדולים היו משאר אנשים בחסידות ובקדושה בחייהם! \u0003אלא:\u0004 אלה שני \u0003הרוגי לוד\u0004 פפוס ולוליינוס שמסרו את עצמם להריגה בשביל כלל ישראל, והודו בהריגת בת המלך, אף שלא הם הרגוה, כדי למנוע גזירה על הכלל. ואף שמקודם לא היו חשובים, כיון שמתו על קידוש ה', מעלתם יתרה מאד.","ועוד במדרשם של אותם פסוקי נבואה, שבספר זכריה נאמר \u0003\"ביום ההוא יהיה על מצלות הסוס קדש לה'\u0004 והיה הסירות בבית ה' כמזרקים לפני המזבח\u0003\"\u0004 (זכריה יד, כ). ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצלות הסוס\"?\u0004 \u0003אמר ר' יהושע בן לוי: עתיד הקדוש ברוך הוא להוסיף על ירושלים עד\u0004 כדי השיעור \u0003שהסוס רץ ומציל\u0004 (עושה צל), כלומר, כמשך מרוצת הסוס מן הבוקר עד מחצית היום, שבו כמעט נעלם הצל.","","\u0003ר' אלעזר אמר: כל מצילות\u0004 (פעמונים) \u0003שתולין לסוס בין עיניו\u0004 לנוי \u0003יהיה קדש לה',\u0004 שינדבו אותם ישראל למקדש.","\u0003ור' יוחנן אמר: כל ביזה שבוזזים ישראל\u0004 את העמים שיבואו עליהם למלחמה \u0003עד שעה שהסוס רץ ומציל כלומר, עד חצות היום — יהיה קדש לה'.\u0004","ושואלים: \u0003בשלמא למאן\u0004 \u0005[נניח למי]\u0006 ש\u0003אמר כל ביזה שבזזו ישראל — היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בסוף הכתוב: \u0003\"והיה הסירות בבית ה' כמזרקים לפני המזבח\",\u0004 שהפסוק מדבר בתוספת שפע וכסף שיהיה בבית המקדש. \u0003אלא למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר בהנך תרתי, מאי\u0004 \u0005[באותם השניים\u0006 האחרים, \u0005מה]\u0006 פירוש \u0003\"והיה הסירות בבית ה'\"?\u0004 ומשיבים: לדעתם, \u0003מילתא אחריתי קאמר\u0004 \u0005[דבר אחר אמר]\u0006 ובישר כי לעתיד יהיה \u0003דמתעתרי\u0004 \u0005[שיתעשרו]\u0006 \u0003ישראל ומתנדבי ומייתי\u0004 \u0005[ויתנדבו ויביאו]\u0006 למקדש. ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר\u0004 שמדובר כאן ב\u0003ביזה — היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ולא יהיה כנעני עוד בבית ה' צבאות\u0004 ביום ההוא\u0003\"\u0004 (זכריה יד, כא), שלא יהיו זקוקים עוד לו, \u0003אלא למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר הנך תרתי, מאי\u0004 \u0005[אלו השנים, מה\u0006 פירוש\u0005]\u0006 \u0003\"ולא יהיה כנעני\"? אמר ר' ירמיה:\u0004 \"כנעני\" לשון נוטריקון: \u0003אין כאן עני.\u0004 כלומר, לא יהיו עוד עניים, ולא יצטרכו עוד לסוחרים.","","\u0003וכנעני מנלן דאיקרי\u0004 \u0005[מנין לנו שהוא\u0006 השם \u0005שנקרא בו]\u0006 כל \u0003תגר?\u0004 שנאמר: \u0003\"וירא שם יהודה בת איש כנעני...\u0004 ויקחה ויבוא אליה\u0003\"\u0004 (בראשית לח, ב), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כנעני\"\u0004 בפסוק זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כנעני ממש, אפשר בא אברהם והזהיר את יצחק\u0004 שלא ישא מבנות הארץ, \u0003בא יצחק והזהיר\u0004 כן \u0003את יעקב, ויהודה אזיל ונסיב\u0004 \u0005[הולך נושא]\u0006 מבנות כנען?! \u0003אלא אמר ר' שמעון בן לקיש: בת גברא תגרא\u0004 \u0005[איש סוחר],\u0006 שנאמר: \u0003\"כנען בידו מאזני מרמה\u0004 לעשוק אהב\u0003\"\u0004 (הושע יב, ח). \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור מכאן\u0006 ממקרא זה\u0005]\u0006 שנאמר בצור: \u0003\"אשר סחריה שרים כנעניה נכבדי ארץ\"\u0004 (ישעיה כג, ח).","ועוד נאמר בנבואות שבסוף ספר זכריה: \u0003\"והיה ה' למלך על כל הארץ ביום ההוא יהיה ה' אחד ושמו אחד\"\u0004 (זכריה יד, ט). ושואלים: \u0003אטו האידנא לאו\u0004 \u0005[וכי עכשיו לא]\u0006 \u0003אחד הוא?\u0004 \u0003אמר ר' אחא בר חנינא: לא כעולם הזה העולם הבא, העולם הזה\u0004 נהוג בו כי \u0003על בשורות טובות אומר: \"ברוך הטוב והמטיב\", ועל בשורות רעות אומר: \"ברוך דיין האמת\". לעולם הבא, כולו \"הטוב והמטיב\".\u0004 שיקרא ה' באופן אחד של ברכה. עוד נאמר באותו פסוק \u0003\"ושמו אחד\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד\"? אטו האידנא לאו\u0004 \u0005[וכי עכשיו אין]\u0006 \u0003שמו אחד הוא?\u0004 \u0003אמר רב נחמן בר יצחק: לא כעולם הזה העולם הבא, העולם הזה\u0004 השם \u0003נכתב ביו\"ד ה\"י ונקרא באל\"ף דל\"ת,\u0004 שאין מבטאים את השם ככתבו. \u0003אבל לעולם הבא כולו אחד,\u0004 ויהא \u0003נקרא ביו\"ד ה\"י\u0004 כשם ש\u0003נכתב ביו\"ד ה\"י.\u0004","","","","\u0003סבר רבא למדרשה בפירקא\u0004 \u0005[לדורשה בדרשת הרגל]\u0006 את דרך קריאתו וניקודו של השם המפורש, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא סבא\u0004 \u0005[זקן אחד]:\u0006 \u0003\"לעלם\" כתיב\u0004 \u0005[נאמר]\u0006 שכן נאמר \"זה שמי לעלם\" ובמקרא נכתב הדבר חסר (לשון העלם), משמע צריך השם להיות נעלם.","\u0003ר' אבינא רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"זה שמי לעלם\"\u0004 שהוא לשון העלם, ונאמר \u0003\"וזה זכרי לדר דר\"\u0004 (שמות ג, טו), ו\"זכרי\" מורה על זכירה, והרי זו משמעות מנוגדת להעלמה. ויש איפוא לכאורה סתירה בין \"שמי לעלם\" ו\"זכרי\". אלא \u0003אמר הקדוש ברוך הוא: לא כשאני נכתב, אני נקרא. נכתב אני ביו\"ד ה\"א, ונקרא אני באל\"ף דל\"ת.\u0004","","\u0003מקום שנהגו לעשות מלאכה בערבי פסחים עד חצות\u0004 היום — \u0003עושין\u0004 בו מלאכה. \u0003מקום שנהגו שלא לעשות — אין עושין.\u0004 שאין בדבר זה איסור מן התורה, והדבר תלוי במנהג. אדם \u0003ההולך ממקום שעושין\u0004 מלאכה בערב פסח \u0003למקום שאין עושין, או ממקום שאין עושין למקום שעושין — נותנין עליו חומרי\u0004 (החומרות) של \u0003מקום שיצא משם וחומרי מקום שהלך לשם,\u0004 שבכל מקרה אל יעשה מלאכה."],["\u0003וכלל אמרו חכמים: אל ישנה אדם\u0004 ממנהג המקום \u0003מפני המחלוקת. כיוצא בו. המוליך פירות שביעית\u0004 (של שנת השמיטה) \u0003ממקום שכלו\u0004 לחיה מן השדה, שפירות שביעית מותרים לאכילה לבעלי בתים המחזיקים את הפירות בבתיהם — כל עוד אותם הפירות מצויים עדיין בשדה כהפקר לכל, ואם כלו מן השדה יש לבערם מן הבית. אם הוליך פירות כאלה ממקום שכבר כלו מן השדה \u0003למקום שלא כלו, או ממקום שלא כלו למקום שכלו\u0004 — הוא \u0003חייב לבער\u0004 כחומרי שני המקומות. \u0003ר' יהודה אומר\u0004 בכגון זה אינו צריך, ש\u0003אומר\u0004 לו לבן המקום: \u0003צא והבא לך אף אתה\u0004 ממקום שמצויים בו עדיין פירות אלה בשדה.","ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דוקא\u0005]\u0006 שנה איסור זה ב\u0003ערבי פסחים? אפילו ערבי שבתות וערבי ימים טובים נמי\u0004 \u0005[גם כן]\u0006 אסורים במלאכה! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה מלאכה בערבי שבתות וימים טובים מן\u0004 זמן \u0003המנחה ולמעלה\u0004 (והלאה) \u0003אינו רואה סימן ברכה לעולם!\u0004 ומשיבים, יש בכל זאת הבדל: \u0003התם\u0004 \u0005[שם]\u0006 בערב שבת או חג אחר \u0003מן המנחה ולמעלה — הוא\u0004 ש\u0003אסור,\u0004 ואילו \u0003סמוך למנחה — לא. הכא\u0004 \u0005[כאן]\u0006 בערב פסח האיסור הוא כבר \u0003מחצות\u0004 היום. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר להראות הבדל אחר, \u0003התם\u0004 \u0005[שם]\u0006 בערב שבת וחג \u0003סימן ברכה הוא דלא חזי\u0004 \u0005[שאינו רואה],\u0006 \u0003אבל שמותי לא משמתינן ליה\u0004 \u0005[לנדות אין מנדים אותו],\u0006 \u0003הכא שמותי נמי משמתינן ליה\u0004 \u0005[כאן\u0006 בערב פסח \u0005לנדות גם כן מנדים אותו]\u0006 כי בערב פסח יש איסור ממש בדבר.","\u0003גופא,\u0004 לגופה של אותה הלכה שהזכרנו מביאים אנו את המקור בשלמותו: \u0003העושה מלאכה בערבי שבתות וערבי ימים טובים מן המנחה ולמעלה,\u0004 וכן מקדים לעשות \u0003במוצאי שבת ובמוצאי יום טוב ובמוצאי יום הכפורים, ובכל מקום שיש שם נידנוד עבירה\u0004 שאם מקדים או מאחר יכול להיכשל בעשיית מלאכה ביום האסור. ומעירים: \u0003לאתויי\u0004 \u0005[להביא\u0006 להוסיף\u0005]\u0006 \u0003תענית ציבור\u0004 מאותן תעניות (כתשעה באב ותעניות על הגשמים) שיש בהן איסור מלאכה, \u0003אינו רואה סימן ברכה לעולם\u0004 במלאכתו שעושה, מפני שהוא קרוב לעבור עבירה.","כהמשך להלכות אלה מביאים מן התוספתא מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש\u0004 פעמים שאדם הוא \u0003זריז ונשכר\u0004 בזריזותו, \u0003ויש זריז ונפסד, יש שפל\u0004 (עצלן) \u0003ונשכר, ויש שפל ונפסד.\u0004 כיצד? \u0003זריז ונשכר\u0004 — \u0003דעביד כולי שבתא\u0004 \u0005[שעובד כל השבוע],\u0006 \u0003ולא עביד במעלי שבתא\u0004 \u0005[עובד בערב שבת].\u0006 \u0003זריז ונפסד — דעביד כולי שבתא, ועביד במעלי שבתא\u0004 \u0005[שעובד כל השבוע, ועובד גם בערב שבת].\u0006 \u0003שפל ונשכר\u0004 כיצד? — זה ש\u0003לא עביד כולי שבתא\u0004 \u0005[עובד כל השבוע],\u0006 \u0003ולא עביד במעלי שבתא\u0004 \u0005[עובד בערב שבת],\u0006 \u0003שפל ונפסד — זה\u0004 ש\u0003לא עביד כולי שבתא\u0004 \u0005[עובד כל השבוע],\u0006 \u0003ועביד במעלי שבתא\u0004 \u0005[ועובד בערב שבת]\u0006 להשלים מה שהחסיר. \u0003אמר רבא: הני נשי\u0004 \u0005[אותן נשים]\u0006 של העיר \u0003מחוזא, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא עבדן עבידתא במעלי שבתא\u0004 \u0005[עושות מלאכה בערב שבת]\u0006 רק \u0003משום מפנקותא\u0004 \u0005[פינוק]\u0006 \u0003הוא, דהא\u0004 \u0005[שהרי]\u0006 \u0003כל יומא נמי\u0004 \u0005[יום גם כן]\u0006 \u0003לא קא עבדן\u0004 \u0005[עושות הן],\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 שאין הדבר נובע מתוך זהירות במצוה אלא מתוך עצלות — בכל זאת \u0003שפל ונשכר קרינן להו\u0004 \u0005[קוראים אנו להן]\u0006 שיש בכך צד מעולה.","במאמר זה נפגשנו במושג של אדם המקבל שכר על מצוה שעשה שלא לשמה, ובאותו ענין \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"כי גדל עד שמים חסדך\u0004 ועד שחקים אמיתך\u0003\"\u0004 (תהלים נז, יא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"כי גדל מעל שמים חסדך\u0004 ועד שחקים אמיתך\u0003\"\u0004 (תהלים קח, ה), \u0003הא כיצד?\u0004 ומסביר: \u0003כאן\u0004 שגדול מעל שמים \u0003בעושין\u0004 את המצוה \u0003לשמה, וכאן\u0004 (עד שמים) \u0003בעושין שלא לשמה\u0004 שאף להם יש שכר. \u0003וכ\u0004פי שאמר בענין זה \u0003רב יהודה דאמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ומצות אף על פי שלא לשמה, שמתוך שלא לשמה\u0004 בסופו של דבר יבין יותר והוא \u0003בא\u0004 לקיום \u0003לשמה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המצפה לשכר אשתו\u0004 העובדת או לשכר \u0003ריחים — אינו רואה סימן ברכה לעולם.\u0004 ומסבירים: \u0003שכר אשתו\u0004 הכוונה היא ל\u0003מתקולתא,\u0004 שהיא עצמה טווה חוטים לאחרים לפי משקל (ר\"ח) ששכרה מועט ובזיונה ברחוב מרובה. ו\u0003ריחייא\u0004 הכוונה היא \u0003אגרתא\u0004 \u0005[דמי שכירות]\u0006 שהוא נוטל שכר מאלה הטוחנים בריחיים של יד שלו. \u0003אבל\u0004 אם האשה \u0003עבדה ומזבנה\u0004 \u0005[עושה\u0006 מלאכת כפיים \u0005ומוכרת]\u0006 \u0003אישתבוחי משתבח בה קרא\u0004 \u0005[משתבח בה הכתוב]\u0006 ומפאר את מעלותיה, שהרי נאמר באשת החיל \u0003\"סדין עשתה ותמכר\u0004 וחגור נתנה לכנעני\" (משלי לא, כד).","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין סימן ברכה: \u0003המשתכר בקנים\u0004 או \u0003בקנקנים\u0004 שהוא מוכר — \u0003אינו רואה סימן ברכה לעולם. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003כיון דנפיש אפחזייהו שלטא בהו עינא\u0004 \u0005[שמרובה נפחם שולטת בהם עין\u0006 הרע\u0005],\u0006 שהכל סבורים שהוא מוכר הרבה בעוד שאין הדבר כן. וכיוצא בכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תגרי סימטא\u0004 המוכרים סחורתם בסימטות הסמוכות לרשות הרבים והכל רואים אותם, \u0003ומגדלי בהמה דקה\u0004 שכרגיל גורמים נזק לשדות אחרים, \u0003וקוצצי אילנות טובות\u0004 העושים פרי, אפילו עשו כן בהיתר, וכן \u0003נותנין עיניהן בחלק יפה,\u0004 אנשים שכאשר הם מתחלקים בדברים הריהם מקפידים לקבל את החלק הטוב יותר, כל אחד מאלו \u0003אינו רואה סימן ברכה לעולם, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דתהו ביה אינשי\u0004 \u0005[שאנשים תוהים עליו]\u0006 ושמים לב למעשיהם ולכן אינם מתברכים בהם.","ועוד כיוצא בדבר זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003ארבע פרוטות אין בהן סימן ברכה לעולם: שכר כותבין\u0004 של ספרי קודש, \u0003ושכר מתורגמנין\u0004 שמסבירים ומתרגמים את דברי החכם הדורש לציבור בשבת, \u0003ושכר יתומים\u0004 שמקבל אדם כשעושה שותפות עם אפוטרופוס של יתומים, \u0003ומעות הבאות ממדינת הים.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שכר מתורגמנין\u0004 אינם מצליחים בו \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כשכר שבת,\u0004 שהם מקבלים שכר עבור עבודתם בשבת, ואף שאין בכך עבירה אינו נראה יפה. \u0003מעות יתומים נמי לאו בני מחילה נינהו\u0004 \u0005[גם כן אינם בני מחילה]\u0006 שהרי קטנים הם ואין בכוחם למחול על הפסדם, ואם נטל משהו מחלקם שלא כדין, כיון שאינם יכולים למחול לו כשאר שותפים המוחלים על הפסד זעיר — הרי הוא כגזלן. \u0003מעות הבאות ממדינת הים — משום דלאו כל יומא מתרחש ניסא\u0004 \u0005[שלא בכל יום מתרחש נס],\u0006 שהסיכון בסחורה המובאת ממרחקים הוא גדול מאד, ואם זכה והרויח הרי הוא מנכה לעצמו מזכויותיו.","אולם \u0003שכר כותבין מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינם מצליחים בו? \u0003אמר ר' יהושע בן לוי: עשרים וארבע תעניות\u0004 (כנגד משמרות כהונה. מהרש\"א) \u0003ישבו אנשי כנסת הגדולה על כותבי ספרים\u0004 של תורה \u0003תפלין ומזוזות שלא יתעשרו\u0004 במלאכתם, \u0003שאילמלי מתעשרים — אין כותבים\u0004 עוד. וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כותבי ספרים ותפילין ומזוזות, הן ותגריהם\u0004 כלומר, הסוחרים הקונים מהם \u0003ותגרי תגריהם, וכל העוסקים במלאכת שמים\u0004 ומתפרנסים ממנה, \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003מוכרי תכלת\u0004 לציצית שגם הם בכלל זה — \u0003אינן רואים סימן ברכה לעולם. ואם עוסקים לשמה\u0004 להוסיף שיהיו חפצי קדושה ומצוה מצויים לאחרים — \u0003רואים.\u0004","במשנתנו דובר בשמירתם של מנהגי המקום, ובקשר לכך מסופר: \u0003בני ביישן נהוג\u0004 \u0005[בית שאן היו נוהגים]\u0006 ש\u0003לא הוו אזלי\u0004 \u0005[היו הולכים]\u0006 \u0003מצור לצידון במעלי שבתא\u0004 \u0005[בערב שבת]\u0006 ליום השוק שהיה שם בערבי שבת. שהחמירו על עצמם שלא להתבטל מצורכי השבת, אף בנסיעה קצרה זו, מפני כבוד השבת. \u0003אתו בנייהו קמיה\u0004 \u0005[באו בניהם לפני]\u0006 \u0003ר' יוחנן\u0004 לבקש שיתיר להם מנהג זה. \u0003אמרו לו: אבהתין\u0004 \u0005[אבותינו]\u0006 \u0003אפשר\u0004 היה \u0003להו\u0004 \u0005[להם]\u0006 מחמת עושרם להתפרנס בלא יום שוק זה, \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003לא אפשר לן\u0004 \u0005[לנו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כבר קיבלו אבותיכם עליהם\u0004 מנהג טוב זה והוא מחייב אף אתכם, \u0003שנאמר: \"שמע בני מוסר אביך ואל תטש תורת אמך\"\u0004 (משלי א, ח). ואנו למדים מכאן שחייב אדם לשמור לא רק הלכות אלא אף מנהגי בית אבותיו.","ועוד מסופר בענין מנהגים: \u0003בני\u0004 העיר \u0003חוזאי נהגי דמפרשי\u0004 \u0005[היו נוהגים שהיו מפרישים]\u0006 \u0003חלה\u0004 גם \u0003מ\u0004עיסה של \u0003ארוזא\u0004 \u0005[אורז],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב יוסף\u0004 על מנהגם זה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ניכלה\u0004 \u0005[שיאכל אותה]\u0006 את החלה הזו \u0003זר\u0004 מי שאינו כהן \u0003באפייהו\u0004 \u0005[בפניהם],\u0006 להראות להם במפגיע שאין מנהגם זה מנהג. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003דברים המותרים\u0004 מצד הדין \u0003ואחרים נהגו בהן איסור\u0004"],["\u0003אי אתה רשאי להתירן בפניהם\u0004 שלא יבואו לזלזל בשאר איסורים, שיאמרו: אם דבר זה הותר לנו אף איסורים אחרים אינם חמורים. וכיצד התיר להם רב יוסף? \u0003אמר לו: ולאו מי איתמר עלה\u0004 \u0005[והאם לא נאמר על\u0006 הלכה \u0005זו]\u0006 \u0003אמר רב חסדא:\u0004 דברים אלה נאמרו \u0003בכותאי\u0004 \u0005[בשומרונים]\u0006 ולא באחרים! ודוחים: \u0003כותאי מאי טעמא — משום דמסרכי מילתא\u0004 \u0005[השומרונים מה הטעם\u0006 אסור \u0005משום שמושכים את הדבר]\u0006 ומצרפים אליו הקלות יתרות שלא כדין, \u0003הנך אינשי נמי סרכי מילתא\u0004 \u0005[אותם אנשים גם כן ימשכו\u0006 את ההיתר\u0005]\u0006 ויתירו דברים אחרים, שהרי הם עמי הארץ.","\u0003אלא אמר רב אשי: חזינן\u0004 \u0005[רואים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003רובן\u0004 של אנשי אותו מקום \u0003אורז אכלי\u0004 \u0005[אוכלים] —\u0006 \u0003לא ניכליה\u0004 \u0005[יאכלנה]\u0006 \u0003זר\u0004 את החלה \u0003באפייהו\u0004 \u0005[בפניהם],\u0006 \u0003דילמא משתכחא\u0004 \u0005[שמא תשכח]\u0006 \u0003תורת\u0004 הפרשת \u0003חלה מינייהו\u0004 \u0005[מהם],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003רובן דגן אכלי\u0004 \u0005[אוכלים] —\u0006 \u0003ניכלה\u0004 \u0005[יאכלנה]\u0006 \u0003זר באפייהו\u0004 \u0005[בפניהם],\u0006 שאז חשוב לעשות זאת, \u0003דילמא אתי לאפרושי\u0004 \u0005[שמא יבואו להפריש]\u0006 \u0003מן החיוב על הפטור.\u0004 שאם יחשבו שמפרישים חלה מאורז, אף יפרישו חלה מדגן עבור האורז, או \u0003מן הפטור על החיוב\u0004 מן האורז על הדגן, ולא יצאו ידי חובתם.","כיון שהוזכרו הלכות בענין מנהגים והיתרם, דנים בו \u0003גופא\u0004 \u0005[עצמו],\u0006 אמרנו כי \u0003דברים המותרים ואחרים נהגו בהן איסור — אי אתה רשאי להתירם בפניהם. אמר רב חסדא: בכותאי עסקינן\u0004 \u0005[בכותים,\u0006 שומרונים \u0005עוסקים אנו]\u0006 ולא בישראל. ותוהים: \u0003וכולי עלמא\u0004 \u0005[וכל העולם\u0006 שאר אנשים\u0005]\u0006 \u0003לא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רוחצים שני אחים כאחד\u0004 ואין חוששים לחוסר צניעות והרהור עבירה, \u0003ואין רוחצים שני אחים\u0004 בעיירה \u0003כבול\u0004 ששם נהגו להחמיר בכך. \u0003ומעשה ביהודה והלל בניו של רבן גמליאל שרחצו שניהם כאחד בכבול, ולעזה\u0004 (שוחחה, התרגשה) \u0003עליהם כל המדינה\u0004 (העיר, המקום), \u0003אמרו: מימינו לא ראינו כך\u0004 שירחצו שני אחים כאחד. \u0003ונשמט הלל ויצא לבית החיצון ולא רצה לומר להם: מותרים אתם,\u0004 שהעדיף להישמע לדבריהם ולא להתיר בפניהם.","וכן \u0003יוצאים בקורדקיסון\u0004 (נעלים רחבות כעין נעלי בית) \u0003בשבת ואין יוצאים בקורדקיסון בשבת\u0004 בעיירה \u0003בירי. ומעשה ביהודה והלל בניו של רבן גמליאל שיצאו בקורדקיסון בשבת בבירי, ולעזה עליהם כל המדינה. ואמרו: מימינו לא ראינו כך, ושמטום ונתנום לעבדיהם\u0004 הגוים \u0003ולא רצו לומר להן מותרים אתם.\u0004","וכן \u0003יושבים על ספסלי גוים\u0004 המיועדים בדרך כלל להניח עליהם סחורה למכירה \u0003בשבת\u0004 ואין חושדים בהם. \u0003ואינן יושבין על ספסלי גוים בשבת בעכו, ומעשה ברבן שמעון בן גמליאל שישב על ספסלי גוים בשבת\u0004 בעיר \u0003עכו, ולעזה עליו כל המדינה, אמרו: מימינו לא ראינו כך, נשמט על גבי קרקע ולא רצה לומר להם מותרים אתם.\u0004 ומשיבים: \u0003בני מדינת הים נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון דלא שכיחי רבנן גבייהו\u0004 \u0005[שאין מצויים חכמים אצלם]\u0006 \u0003ככותים דמו\u0004 \u0005[כשומרונים הם נחשבים]\u0006 ואסור להתיר להם.","כיון שהוזכרו הדברים דנים בענין מה היה הטעם לעיקר החומרה באותם מקומות; \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאסרו באותם \u0003ספסלי גוים\u0004 — \u0003משום דמחזי\u0004 \u0005[שנראה]\u0006 \u0003כמקח וממכר\u0004 בשבת. \u0003בקורדקיסון נמי\u0004 \u0005[גם כן],\u0006 \u0003דילמא משתלפין ואתי לאיתויינהו\u0004 \u0005[שמא ישלפו\u0006 מרגליו \u0005ויבוא להוליכם\u0006 בידו\u0005]\u0006 \u0003ארבע אמות ברשות הרבים\u0004 ונמצא עובר על דברי תורה.","\u0003אלא רוחצין מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא?\u0004 ומשיבים שיסוד ההלכה הזו מובן על פי מה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003עם הכל אדם רוחץ חוץ מאביו וחמיו ובעל אמו ובעל אחותו\u0004 משום קירבתם המשפחתית, שמתוך שהוא מהרהר בלבו על דרך קירבת המשפחה ביניהם שמא יבוא לידי הרהור עבירה בנשים ובגברים. \u0003ור' יהודה מתיר באביו מפני כבוד אביו,\u0004 שאם יהא עמו יוכל לסייע לו ברחיצה. \u0003והוא הדין לבעל אמו.\u0004","\u0003ואתו אינהו\u0004 \u0005[ובאו הם\u0006 אנשי כבול\u0005]\u0006 \u0003וגזור\u0004 \u0005[וגזרו]\u0006 איסור \u0003בשני אחין משום בעל אחותו\u0004 שנראה להם שבכך יש חשש והחמירו על עצמם. \u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003תלמיד לא ירחץ עם רבו\u0004 מפני שאין זה כבוד לרב שתלמידו רואהו ערום, \u0003ואם רבו צריך לו\u0004 שיסייענו בשעת רחיצה — \u0003מותר.\u0004","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבה בר בר חנה\u0004 מארץ ישראל לבבל \u0003אכל\u0004 מן החלב המצוי \u0003דאייתרא\u0004 \u0005[על היתר\u0006 שבקיבה\u0005],\u0006 שהחלב שעל הקיבה יש בו חלק פנימי הנקרא חלק היתר וחלק חיצון הנקרא חלק הקשת, ובחלב ה\"יתר\" יש חילוק מנהגים. שבני ארץ ישראל נהגו בו היתר ובני בבל אוסרים אותו. \u0003עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב עוירא סבא\u0004 \u0005[הזקן]\u0006 \u0003ורבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא, כיון דחזינהו כסייה מינייהו\u0004 \u0005[שראה אותם\u0006 באים \u0005כיסה מהם]\u0006 מה שאכל. \u0003אתו ואמרו ליה\u0004 \u0005[באו ואמרו לו]\u0006 \u0003לאביי\u0004 את המעשה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שווינכו ככותאי\u0004 \u0005[עשה אתכם כשומרונים]\u0006 שהרי יכול היה לומר במפורש \"מותרים אתם\" ולא עשה כן.","ושואלים: \u0003ורבה בר בר חנה\u0004 שנהג היתר בדבר האסור שם \u0003לית ליה הא דתנן\u0004 \u0005[האם אינו מקבל מה ששנינו\u0006 במשנתנו\u0005]\u0006 שמי שהלך ממקום למקום \u0003נותנים עליו חומרי המקום שיצא משם וחומרי המקום שהלך לשם? אמר אביי: הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כשהולך \u0003מבבל לבבל\u0004 ממקום למקום, \u0003או מארץ ישראל לארץ ישראל, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003מבבל לארץ ישראל, אבל מארץ ישראל לבבל\u0004 — אין סומכים על כלל זה. כי \u0003כיון דאנן כייפינן להו עבדינן כוותייהו\u0004 \u0005[שאנו\u0006 בני בבל \u0005כפופים להם\u0006 מבחינת ההלכה \u0005עושים אנו כמותם]\u0006 ואין איש ארץ ישראל צריך לנהוג כמנהג בבל.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שגם \u0003מארץ ישראל לבבל\u0004 צריך להחמיר כמנהג המקום שבא אליו, אולם \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום]\u0006 ש\u0003אין דעתו לחזור,\u0004 אלא להשתקע במקום החדש, ואילו \u0003רבה בר בר חנה דעתו לחזור הוה\u0004 \u0005[היתה]\u0006 ולכן היה מותר בכך כמנהג ארץ ישראל ממנה הוא בא ואליה הוא חוזר. מספרים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר בר חנה לבריה\u0004 \u0005[לבנו]:\u0006 \u0003בני,\u0004 אתה שהנך חי בבבל \u0003לא תאכל\u0004 את החלב \u0003לא בפני ולא שלא בפני. אני שראיתי את ר' יוחנן שאכל\u0004 — יכול אני לומר ש\u0003כדי\u0004 (כדאי) \u0003הוא ר' יוחנן לסמוך עליו\u0004 גם \u0003בפניו\u0004 וגם \u0003שלא בפניו. אתה לא ראית אותו לא תאכל בין בפני בין שלא בפני,\u0004 שאינך כדאי שתסמוך רק עלי בהיתר זה.","ומעירים: \u0003ופליגא דידיה אדידיה\u0004 \u0005[וחלוקה\u0006 שיטתו \u0005שלו על\u0006 דבריו \u0005שלו]\u0006 ש\u0003אמר רבה בר בר חנה: סח לי ר' יוחנן בן אלעזר: פעם אחת נכנסתי אחר ר' שמעון בן ר' יוסי בן לקוניא לגינה\u0004 שליד ביתו"],["\u0003ונטל ספיחי כרוב\u0004 שצמחו שם בלא שנזרעו והיה הדבר בשנת השמיטה, \u0003ואכל ונתן לי, ואמר לי: בני, בפני — אכול, שלא בפני — לא תאכל\u0004 ספיחי כרוב. וטעמו: \u0003אני שראיתי את ר' שמעון בן יוחי שאכל — כדי\u0004 (כדאי) \u0003הוא ר' שמעון בן יוחי לסמוך עליו בפניו ושלא בפניו. אתה\u0004 שלא ראית אותו אוכל — \u0003בפני אכול\u0004 שיכול אתה לסמוך על מה שראיתי, אבל \u0003שלא בפני לא תאכל\u0004 ואל תסמוך על עדותי זו. הרי שבמקרה זה סבר רבה בר בר חנה, שלא רק הרואה את החכם המתיר אלא אף תלמידיו יכולים לסמוך עליו לפחות בפניו.","ושואלים: \u0003מאי\u0004 \u0005[מה הם]\u0006 דברים אלה של \u0003ר' שמעון? דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: כל הספיחים אסורין,\u0004 שכל ספיחי הירקות הצומחים מעצמם בשנה השביעית אסורים באכילה \u0003חוץ מספיחי כרוב, שאין כיוצא בהם בירק השדה\u0004 ולא גזרו עליהם גזירה זו משום שאינם דומים לשאר ירקות, ומותר לאכלם כפירות האילן שצמחו מעצמם בשביעית. \u0003וחכמים אומרים: כל הספיחין אסורים\u0004 ובכללם אף ספיחי הכרוב.","\u0003ומעירים: ותרוייהו\u0004 \u0005[ושניהם]\u0006 גם ר' שמעון וחכמים החולקים עליו כאן הם \u0003אליבא\u0004 \u0005[על פי]\u0006 שיטת \u0003ר' עקיבא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 במדרש הכתוב: \u0003\"\u0004וכי תאמרו מה נאכל בשנה השביעית \u0003הן לא נזרע ולא נאסף את תבואתנו\"\u0004 (ויקרא כה, כ), \u0003אמר ר' עקיבא: וכי מאחר שאין זורעין מהיכא\u0004 \u0005[מהיכן]\u0006 \u0003אוספין?\u0004 ולשם מה יש להזכיר בכתוב את האסיף? אלא \u0003מכאן לספיחין\u0004 שלא זרעום וצמחו מעצמם \u0003שהם אסורין\u0004 אפילו באסיפה בלבד. ועל סמך שיטה זו נחלקו.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[באיזה\u0006 עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003רבנן סברי\u0004 \u0005[חכמים\u0006 האוסרים \u0005סוברים]\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003על ספיחי כרוב אטו\u0004 \u0005[משום]\u0006 \u0003שאר ספיחי דעלמא\u0004 \u0005[הספיחים בכלל],\u0006 \u0003ור' שמעון סבר: לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 \u0003ספיחי כרוב אטו ספיחי דעלמא\u0004 \u0005[משום ספיחים בכלל].\u0006","שנינו במשנה בענין שביתה ממלאכה בערב פסח: \u0003ההולך ממקום\u0004 שאין נוהגים לעשות מלאכה בערב פסח למקום שנוהגים ולהיפך — ינהג כמנהג המחמיר. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ההולך ממקום שעושין למקום שאין עושין — נותנים עליו חומרי מקום שהלך לשם, ואל ישנה אדם מפני המחלוקת ולא ליעביד\u0004 \u0005[יעשה]\u0006 מלאכה.","\u0003אלא\u0004 אם הלך \u0003ממקום שאין עושין\u0004 בו מלאכה \u0003למקום שעושין,\u0004 אף שם \u0003אל ישנה אדם מפני המחלוקת ונעביד\u0004 \u0005[ויעשה]\u0006 מלאכה, וזה אי אפשר לומר \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת \"נותנין עליו חומרי מקום שהלך לשם וחומרי מקום שיצא משם\"\u0004 שלא לעשות מלאכה!","\u0003אמר אביי:\u0004 שההלכה שלא ישנה מפני המחלוקת נאמרה \u0003ארישא\u0004 \u0005[על ההתחלה]\u0006 לענין הבא למקום שאין עושים, שצריך להחמיר כמנהגם. \u0003רבא אמר: לעולם\u0004 יכול אתה לפרש שגם \u0003אסיפא\u0004 \u0005[על סוף\u0006 המשנה\u0005]\u0006 מדובר, \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 \u0003אין בזו\u0004 במניעה ממלאכה \u0003מפני שינוי המחלוקת, מאי קא אמרת\u0004 \u0005[מה אומר אתה]\u0006 \u0003הרואה\u0004 שהוא בטל \u0003אומר\u0004 ש\u0003מלאכה אסורה\u0004 שלא כמנהג המקום? אין הדבר כן, שהרואה אדם שאינו עושה מלאכה אינו סבור בהכרח שעושה זאת מחמת איסור שבדבר אלא מטעם אחר, \u0003מימר אמרי\u0004 \u0005[אומרים]\u0006 הם לעצמם: \u0003כמה בטלני הוי בשוקא\u0004 \u0005[בטלנים יש בשוק]\u0006 שכל יום אינם עושים מלאכה, ואדם זה מן הסתם לא נזדמנה לו מלאכה היום.","כיון שדובר בענין חומרות הבאות מתוך שמירת מנהגים, מנסים לברר מקצת מאיסורי יום טוב שני של גלויות, שאף הם תלויים במנהג הגולה שמחזיקה בשמירת שני ימים אלה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לר' אבא: כגון אנן דידעינן בקביעא דירחא\u0004 \u0005[אנו היודעים\u0006 כבר \u0005את קביעות החודש\u0006 לפי החשבונות\u0005]\u0006 ואין לחשוש לנו שמא נטעה ולא נעשה את החג בזמנו,"],["ברור כי \u0003ביישוב לא עבידנא\u0004 \u0005[אין אנו עושים]\u0006 מלאכה ביום טוב שני \u0003מפני שינוי המחלוקת,\u0004 שהרי שאר אנשים בגולה נוהגים בו איסור. אולם \u0003במדבר מאי\u0004 \u0005[מה הדין]?\u0006 אם נמצא אדם שלא במקום ישוב ויודע את קביעות החודש כיצד ינהג? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב אמי: ביישוב — אסור, במדבר — מותר.\u0004","ובדרך אגב מספרים כי \u0003רב נתן בר אסיא אזל\u0004 \u0005[הלך]\u0006 \u0003מבי\u0004 \u0005[מבית\u0006 המדרש\u0005]\u0006 של \u0003רב לפומבדיתא ביום טוב שני של עצרת,\u0004 שסמך על מה שידע בקביעות החודש, וחילל יום טוב שני על ידי יציאה מחוץ לתחום. \u0003שמתיה\u0004 \u0005[נידהו]\u0006 \u0003רב יוסף\u0004 כעונש על כך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולנגדיה מר נגידי\u0004 \u0005[ושידונו אדוני במלקות]\u0006 על עבירה חמורה זו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עדיפא עבדי ליה\u0004 \u0005[\u0006דבר \u0005עדיף,\u0006 חמור יותר, \u0005עשיתי לו]\u0006 \u0003דבמערבא מימנו אנגידא דבר בי רב ולא מימנו אשמתא\u0004 \u0005[שבארץ ישראל היו נמנים על מלקות לתלמיד חכם\u0006 שחטא \u0005ולא היו נמנים לנדותו]\u0006 מפני כבוד התורה, ואם כן משמע שנידוי חמור יותר ממלקות.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003נגדיה\u0004 \u0005[ציוה]\u0006 \u0003רב יוסף\u0004 שילקוהו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: נשמתיה מר\u0004 \u0005[שינדהו אדוני]\u0006 שהרי \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003מנדים על שני ימים טובים של גליות\u0004 אם חיללם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי — איניש דעלמא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בסתם\u0006 אדם\u0005]\u0006 \u0003הכא צורבא מדרבנן\u0004 \u0005[כאן תלמיד חכם]\u0006 \u0003הוא, דטבא ליה עבדי\u0004 \u0005[מה שטוב יותר עבורו עשיתי],\u0006 \u0003דבמערבא מימנו אנגדתא דבר בי רב ולא מימנו אשמתא\u0004 \u0005[שבארץ ישראל נמנים להלקות תלמיד חכם ואין נמנים לנדותו]\u0006 ולא רצה להחמיר כל כך בדינו.","במשנה שנינו: \u0003\"כיוצא בו המוליך פירות שביעית\"\u0004 ממקום למקום שצריך להחמיר כמנהג מקומו וכמקום שהלך אליו, ור' יהודה סובר שיכול הוא לומר לך אף אתה לאותו מקום שממנו הבאתי. ושואלים: \u0003ולית ליה לר' יהודה\u0004 \u0005[ואין לו\u0006 אין הוא מקבל\u0005]\u0006 \u0003הא דתנן\u0004 \u0005[זה ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נותנין עליו חומרי המקום שיצא משם וחומרי המקום שהלך לשם?!\u0004","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מילתא אחריתי קאמר\u0004 \u0005[דבר אחר אמר]\u0006 \u0003ר' יהודה, והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך התכוון\u0005]:\u0006 \u0003או\u0004 הלך אדם \u0003ממקום שלא כלו\u0004 הפירות \u0003למקום שלא כלו ושמע שכלו במקומו — חייב לבער, ר' יהודה אומר:\u0004 אינו חייב לבער ויכול לומר \u0003צא והבא לך אף אתה מהיכא דאייתינהו\u0004 \u0005[מהיכן שהבאתים],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא כלו להו\u0004 \u0005[להם]\u0006 עדיין ומותר לי להמשיך לאכול מהם.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יהודה לקולא\u0004 \u0005[להקל]\u0006 חולק על חכמים שבמשנה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: לא אמר ר' יהודה אלא לחומרא! אלא איפוך\u0004 \u0005[הפוך]\u0006 נוסח המשנה, שלפיו יובן שהבא ממקום שלא כלו למקום שלא כלו ושמע שכלו במקומו — \u0003אינו חייב לבער,\u0004 ו\u0003ר' יהודה אומר: צא והבא לך אף אתה מהיכא דאייתינהו\u0004 \u0005[מהיכן שהבאתים אני]\u0006 \u0003והא כלו להו\u0004 \u0005[והרי כלו להם]\u0006 ולכן חייב לבער.","\u0003אביי אמר: לעולם כדקתני\u0004 \u0005[לעולם\u0006 ניישב את המשנה \u0005כפי ששנינו]\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003או\u0004 שהביאום \u0003ממקום שלא כלו למקום שכלו והחזירן למקומן ועדיין לא כלו — אינו חייב לבער,\u0004 ו\u0003ר' יהודה אומר: צא והבא לך אף אתה מהיכא דאייתינהו\u0004 \u0005[מהיכן שהבאתי אותם]\u0006 \u0003והא כלו להו\u0004 \u0005[והרי כלו להם]\u0006 כי כשהביאם בחזרתו הביאם ממקום שכלו, וחייב לבערם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 ולשיטת \u0003ר' יהודה אטו אגבא דחמרא קלטינהו\u0004 \u0005[על גב החמור קלט אותם]?!\u0006 כלומר: וכי משום שרק העביר את הפירות על גב החמור דרך מקום שכלו בו פירות ולקחם משם, ולא גדל שם ואינו אוכלם שם, יחול עליהם איסור?! \u0003אלא אמר רב אשי:\u0004 מחלוקת ר' יהודה וחכמים קשורה \u0003בפלוגתא דהני תנאי דתנן\u0004 \u0005[כפי מחלוקתם של תנאים אלה ששנינו]\u0006 במשנה: \u0003הכובש שלשה כבשין\u0004 משלושה מיני ירקות \u0003בחבית אחת\u0004 בשביעית, \u0003ר' אליעזר אומר: אוכלין על הראשון\u0004 כלומר, מותר לאכול מכל הכבשים רק כל זמן שהמין הראשון מצוי עדיין בשדה, וכשנגמר — צריך לבער הכל, כי יש כאן תערובת של המותר והאסור.","\u0003ר' יהושע אומר: אוכלים\u0004 את כולם \u0003אף על האחרון\u0004 אף עד שיכלה מין זה מן השדה, ו\u0003רבן גמליאל אומר: כל\u0004 מין \u0003שכלה מינו מן השדה — יפריד אותו מן השאר ואחר כך יבער מינו מן החבית, והלכה כדבריו.\u0004 והקשר עם מחלוקת ר' יהודה וחכמים הוא מעין זה: סתם משנתינו סבורה כר' יהושע, שכל עוד יש צד היתר — יש להתיר הכל, ור' יהודה סבור כר' אליעזר (ר\"ח), שאם יש צד להחמיר — מחמירים.","\u0003רבינא אמר:\u0004 מחלוקתם של ר' יהודה וחכמים קשורה \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה]\u0006 \u0003דתנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אוכלין בתמרין\u0004 בכל ארץ יהודה \u0003עד שיכלה\u0004 הדקל \u0003האחרון שבצוער\u0004 שהיא בגבול יהודה ובה התמרים האפילים ביותר. \u0003רבן שמעון בן גמליאל אומר:\u0004"],["\u0003אוכלין על של בין הכיפין\u0004 כל זמן שיש תמרים שנפלו מן העץ והם תקועים בין ענפי הדקל. \u0003ואין אוכלים על\u0004 סמך התמרים שנפלו \u0003בין השיצין\u0004 (בין קוצי הדקל), שאין החיות יכולות להגיע וליטלם משם. ואם כן נלמד מכאן שלדעת תנא קמא של ר' שמעון בן גמליאל אם יש רק אפשרות כלשהי לחיה להגיע לתמרים — מותרים עדיין הכל באכילתם, וכשיטת תנא קמא לענין ביעור. ושיטת רבן שמעון בן גמליאל היא כשיטת ר' יהודה — שאם אין הכל יכולים לבוא ולקחת מאותו מקום חייבים לבער.","כיון שהובאו דברים בענין ביעור פירות שביעית ממקום למקום, מביאים מדברי המשנה בשביעית העוסקת בנושא קרוב. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003שלש ארצות לביעור,\u0004 שלגבי דיני ביעור רואים את ארץ ישראל מחולקת לשלושה חלקים, ואלו הן: \u0003יהודה, ועבר הירדן, וגליל. ושלש ארצות בכל אחת ואחת;\u0004 עמק, הר ושפלה שדיניהם שונים לענין הביעור. \u0003ולמה אמרו שלש ארצות לביעור אם הן עצמן מחולקות לשלוש — שיהיו אוכלים בכל אחת ואחת\u0004 מהן \u0003עד שיכלה האחרון שבה,\u0004 שגם אם כלו הפירות ממקום אחד מתוך השלוש שבאותה ארץ עדיין מותר לאכול כל עוד מצויים פירות אלה במקום אחר מאותם שלוש.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים הללו]\u0006 להתיר את פירות חלק ארץ אחד כשכלו מן האחר, ואילו כשכלו מארץ אחת שוב אין אוכלים בה אף שעדיין לא כלו מן האחרת? \u0003אמר רב חמא בר עוקבא אמר ר' יוסי בר חנינא: אמר קרא\u0004 \u0005[הכתוב]\u0006 שבשנת השמיטה \u0003\"ולבהמתך ולחיה אשר בארצך\u0004 תהיה כל תבואתה לאכול\u0003\"\u0004 (ויקרא כה, ז), ולמדים מכאן: \u0003כל זמן שחיה אוכלת מן השדה\u0004 שהפירות עדיין מצויים וגדלים בחוץ — \u0003האכל לבהמה שבבית\u0004 מותר לכל ליהנות מפירות אלה, ואם כבר \u0003כלה לחיה אשר בשדה\u0004 — \u0003כלה לבהמתך מן הבית.\u0004","\u0003וגמירי\u0004 \u0005[ולומדים]\u0006 אנו במסורת: ש\u0003אין חיה שביהודה גדילה על פירות שבגליל, ואין חיה שבגליל גדילה על פירות שביהודה,\u0004 שבכל איזור יש תנאים מיוחדים המתאימים לבעלי חיים מיוחדים (שפת אמת) והחיות עוברות מאיזור לאיזור בארץ יהודה לחפש לעצמן אוכל, אבל אינן יוצאות לחלק ארץ אחר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פירות\u0004 שביעית \u0003שיצאו מארץ ישראל לחוצה לארץ — מתבערין בכל מקום שהן. ר' שמעון בן אלעזר אומר:\u0004 לא כן, אלא \u0003יחזרו\u0004 הפירות \u0003למקומן\u0004 בארץ ישראל \u0003ויתבערו\u0004 שם, ואין להם תקנה בחוץ לארץ \u0003משום שנאמר \"בארצך\"\u0004 — משמע שחובה זו היא בארץ ישראל בלבד. ושואלים: \u0003הא אפיקתיה\u0004 \u0005[הרי הוצאת אותו]\u0006 ללמד שאין סומכין בני יהודה אלא על ארצם ולא על של גליל?","\u0003קרי ביה בארץ בארצך\u0004 שהיה יכול לכתוב \"בארץ\", ממה שכתוב \"בארצך\" הוי כאילו כתוב \"בארץ בארצך\", ויש בה משמעות כפולה, הן של הארץ בכלל והן של המקום המיוחד בה, ולמדים ממנה שני דברים, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נלמד \u0003מ\"אשר בארצך\"\u0004 שביטוי זה במקום לומר רק \"בארצך\" בא ללמד דבר נוסף.","מסופר: \u0003רב ספרא נפק\u0004 \u0005[יצא]\u0006 \u0003מארץ ישראל לחוצה לארץ, הוה בהדיה גרבא דחמרא\u0004 \u0005[היה עמו קנקן יין]\u0006 של \u0003שביעית, לוו בהדיה\u0004 \u0005[נתלוו אתו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא ורב כהנא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכא דשמיע ליה מיניה\u0004 \u0005[האם יש מי ששמע ממנו]\u0006 מ\u0003ר' אבהו\u0004 האם \u0003הלכה כר' שמעון בן אלעזר או לא?\u0004 ולפי זה חייבים להחזיר את קנקן היין לארץ! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אבהו: הלכה כר' שמעון בן אלעזר\u0004 וחייב אתה לחזור ולבערו בארץ ישראל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004 לא כן אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אבהו: אין הלכה כר' שמעון בן אלעזר\u0004 ויכול אתה לבערו בכל מקום.","\u0003אמר רב ספרא: נקוט הא כללא\u0004 \u0005[החזק כלל זה]\u0006 של \u0003רב הונא בידך\u0004 שעליו אפשר לסמוך יותר, \u0003דדייק וגמר שמעתתא מפומיה דרביה\u0004 \u0005[שהוא מדייק ולומד הלכה מפי רבו]\u0006 באותו דיוק \u0003כרחבה דפומבדיתא\u0004 (מפומבדיתא) שהיה מפורסם בדיוק שמועותיו. כפי הדוגמה המפורשת ש\u0003אמר רחבה אמר רב יהודה: הר הבית סטיו\u0004 (שורת איצטבאות) \u0003כפול היה\u0004 בבית המקדש \u0003סטיו לפנים מסטיו,\u0004 שמדייק רחבה למסור את הדברים בדיוק בלשון רבו בלא כל שינוי. על אותו מעשה שרב ספרא סמך לבסוף על דברי רב הונא המיקל \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רב יוסף\u0004 בהיתול את הפסוק: \u0003\"עמי בעצו ישאל ומקלו יגיד לו\"\u0004 (הושע ד, יב), ודרש: \u0003כל המיקל לו — מגיד לו\u0004 שהוא מקשיב רק לדעת החכם המיקל, והוא זה המגיד לו הלכה.","ועוד בדיני שביעית מסופר: \u0003ר' אילעאי קץ כפנייתא\u0004 \u0005[קצץ\u0006 דקל שהיו בו \u0005תמרי בוסר]\u0006 של השנה ה\u0003שביעית.\u0004 ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כן]?!\u0006 והלוא נאמר \"והיתה שבת הארץ לכם לאכלה\" (ויקרא כה, ו), \u0003\"לאכלה\" אמר רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003ולא להפסד,\u0004 שאיסור הוא להפסיד פירות שביעית ואין היתר להשתמש בהם אלא בדרך אכילה בלבד. \u0003וכי תימא: הני מילי היכא דנחית לפירא\u0004 \u0005[ואם תאמר: דברים אלה\u0006 אמורים \u0005כאשר הגיע\u0006 הדבר \u0005ל\u0006דרגת \u0005פרי],\u0006 \u0003אבל היכא דלא נחית לפירא\u0004 \u0005[\u0006ב\u0005מקום שלא הגיע\u0006 לדרגת \u0005פרי] —\u0006 \u0003לא.\u0004 והרי \u0003אמר רב נחמן אמר רבה בר אבוה: הני מתחלי\u0004 \u0005[אותם עטיפי\u0006 פירות הדקל\u0005]\u0006 של \u0003ערלה — אסירי\u0004 [\u0005אסורים]\u0006 באכילה כשאר פירות הערלה, ואינם נידונים כעץ סתם המותר באכילה בשנות ערלה. כי אף שאינם ראויים לאכילה כשלעצמם, \u0003הואיל ונעשו שומר לפירי\u0004 \u0005[לפירות]\u0006 בזמן גידולו הריהם נידונים כפירות עצמם.","ונדקדק: \u0003ושומר לפירי אימת הוה\u0004 \u0005[לפירות מתי הם]\u0006 \u0003בכופרי\u0004 \u0005[\u0006כשהתמרים עדיין \u0005בוסר]\u0006 ובכל זאת \u0003וקא קרי להו פירי\u0004 \u0005[קורא להם\u0006 כבר \u0005פירות],\u0006 משמע שתמרים אף בעודם קטנים ביותר קרויים כבר פרי, ולכן כשם שחל עליהם איסור ערלה כך גם אסור להפסידם בשביעית! ומשיבים: \u0003רב נחמן\u0004 ש\u0003אמר\u0004 דעתו בזה לא כדברי הכל היא אלא כשיטת יחיד של \u0003ר' יוסי\u0004 שאין הלכה כמותו. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר: סמדר\u0004 שהוא פרי הבוסר הקטן שבגפנים \u0003אסור\u0004 בארץ משום ערלה, \u0003מפני שהוא פירי,\u0004 אולם \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 שלדעתם פרי הוא רק מה שהגיע לדרגה ידועה של הבשלה, ולא קודם לכן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שימי מנהרדעא: ומי פליגי רבנן עליה\u0004 \u0005[והאם חלוקים חכמים עליו]\u0006 על \u0003ר' יוסי\u0004 אף \u0003בשאר אילנות\u0004 שלא נחלקו על ר' יוסי בגפנים בלבד. \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאימתי אין קוצצים את האילנות בשביעי\u0004 (בשנה השביעית) ולא יבואו לידי הפסד? \u0003בית שמאי אומרים: כל האילנות משיוציאו\u0004 פרי כל שהוא, \u0003ובית הלל אומרים:\u0004 יש לחלק: \u0003החרובין\u0004 זמנן \u0003משישרשרו\u0004 משנראות בפרי החרוב בליטות קטנות כעין שרשרת, \u0003והגפנים\u0004"],["\u0003משיגריעו\u0004 שיגדלו מעט, \u0003והזיתים משיניצו\u0004 ותיראה מקצת דמות הפרי מהם, \u0003ושאר כל האילנות משיוציאו\u0004 תחילת פרי. \u0003ואמר רב אסי: הוא\u0004 שיעור \u0003בוסר, הוא גירוע, הוא פול הלבן,\u0004 ותחילה תוהים על הלשון: \u0003פול הלבן סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 וכי מה לפול הלבן על הגפנים?! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 ותקן\u0005]:\u0006 \u0003שיעורו כפול הלבן.\u0004","\u0003ומאן שמעת ליה\u0004 \u0005[ומי שמעת אותו]\u0006 ש\u0003אמר בוסר — אין\u0004 \u0005[כן]\u0006 נחשב כפרי, \u0003סמדר — לא,\u0004 הלוא הם \u0003רבנן\u0004 \u0005[חכמים]\u0006 ולא ר' יוסי, \u0003וקתני\u0004 \u0005[ושנו]\u0006 אף הם \u0003שאר כל האילנות משיוציאו.\u0004 משמע שבדקלים גם תמרי הבוסר דקלים הם! \u0003אלא\u0004 חוזרים אנו מהתירוץ הקודם ואומרים כי \u0003ר' אילעאי בדניסחני קץ\u0004 \u0005[בתמרים גרועים קצץ],\u0006 שתמרים אלה לעולם אינם מתבשלים על העץ ואין להם תקנה אלא בהבחלה בקרקע בלבד, ומשום כך אינו עובר כשקוצצם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אוכלין בענבים\u0004 בשביעית \u0003עד שיכלו דליות\u0004 (ענפי) הגפנים \u0003של\u0004 המקום \u0003אוכל.\u0004 ו\u0003אם יש מאוחרות מהן — אוכלים עליהם,\u0004 שלא נאמר שם מקום זה אלא מתוך ההנחה שהוא האחרון, אבל לא לקבוע הלכה באופן זה דוקא.","וכן \u0003אוכלים בזיתים עד שיכלה\u0004 זית \u0003אחרון שבתקוע,\u0004 ואילו \u0003ר' אליעזר אומר: עד שיכלה אחרון של גוש חלב.\u0004 ומה משמעו שיכלה — \u0003כדי שיהא עני יוצא\u0004 לחפש \u0003ואינו מוצא לא בנופו\u0004 (בענפיו) \u0003ולא בעיקרו\u0004 (בגזעו) מן הזיתים שנפלו כדי שיעור \u0003רובע\u0004 הקב. \u0003אוכלין בגרוגרות\u0004 (תאנים יבשות) \u0003עד שיכלו פגי בית היני.\u0004","\u0003אמר ר' יהודה: לא הוזכרו פגי בית היני\u0004 לשם ענין זה \u0003אלא\u0004 שכבר נחשבים הם כפירות \u0003לענין מעשר. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פגי בית היני ואהיני דטובינא\u0004 (ותמרי טובינא) שאינם מגיעים לבישול גמור — בכל זאת טובים הם למדי, וחשובים עד שהם \u0003חייבים במעשר.\u0004","שנינו כי \u0003אוכלים בתמרים עד שיכלה האחרון שבצוער. רבן שמעון בן גמליאל אומר: אוכלין\u0004 תמרים \u0003על של בין הכיפין\u0004 שנמצאים עדיין בין ענפי הדקל \u0003ואין אוכלין על של בין השיצין\u0004 (הקוצים).","\u0003ורמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003אוכלין בענבים עד הפסח, בזיתים עד העצרת\u0004 (שבועות), \u0003בגרוגרות עד החנוכה,\u0004 ו\u0003בתמרים עד הפורים, ואמר רב ביבי: ר' יוחנן תרתי בתרייתא\u0004 \u0005[שתים אחרונות]\u0006 — \u0003מחליף.\u0004 כלומר, שהיה גורס בגרוגרות עד הפורים, ובתמרים עד החנוכה, ושיעור זה נבדל ממה שאמרנו שמותר לאכול תמרים עד שיכלה האחרון בצוער. ומשיבים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא,\u0004 אלא שהחכם הראשון קבע לפי המקומות בהם גדלים תמרים והאחר לפי סדר הזמנים. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא קתני בהדיא\u0004 \u0005[הרי שנינו במפורש]\u0006 \u0003אם יש מאוחרות מהן — אוכלים עליהן,\u0004 משמע שלא נקבעו המקומות אלא לסימן והכל נקבע למעשה לפי המציאות, וכן גם לענין קביעות הזמנים.","\u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]\u0006 כהמשך לדברים שהובאו קודם משם \u0003רבן שמעון בן גמליאל אומר: סימן להרים\u0004 שצומחים בהם \u0003עצי מילין\u0004 (עפצים המשמשים להכנת דיו), \u0003סימן לעמקים — דקלים, סימן לנחלים — קנים, סימן לשפלה — שקמה. ואף על פי שאין ראיה לדבר\u0004 שזהו הסימן, מכל מקום יש \u0003זכר לדבר\u0004 ורמז לו בכתוב \u0003שנאמר: \"ויתן המלך את הכסף בירושלים כאבנים ואת הארזים נתן כשקמים אשר בשפלה לרב\"\u0004 (מלכים א י, כז).","ומבארים את פרטי תוספתא זו: \u0003\"סימן להרים מילין סימן לעמקים דקלים\".\u0004 לשם מה זקוקים לסימנים אלה? \u0003נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 שינוי הלכה למעשה לענין \u0003בכורים. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מביאים בכורים אלא משבעת המינים\u0004 ודווקא מן המשובחים שביניהם, ולכן \u0003לא\u0004 מביאים \u0003מדקלים שבהרים\u0004 שכיון שאינם המקום הראוי לדקלים אין פירותיהם משובחים, ואף \u0003לא מפירות שבעמקים\u0004 שאין פירות ההר גדלים שם כראוי.","\u0003\"סימן לנחלים קנים\" נפקא מינה\u0004 \u0005[יוצא מזה\u0006 הבדל למעשה\u0005]\u0006 לענין \u0003נחל איתן\u0004 האמור בתורה, שיש לערוף בו את העגלה שמביאים על רצח שלא נודע רוצחו אל הנחל וסימנו של נחל — מקום גידול קנים. \u0003\"סימן לשפלה שקמה\"\u0004 מסבירים \u0003נפקא מינה\u0004 \u0005[יוצא מזה\u0006 להלכה\u0005]\u0006 לענין \u0003מקח וממכר,\u0004 שאם היתנה אדם שהוא קונה אדמה בשפלה הגדרת הדבר היא למקום המגדל שיקמים. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 להסביר שהדבר נוגע להגדרת טיב הקרקעות ולמקח וממכר \u0003כולהו נמי\u0004 \u0005[כולם גם כן]\u0006 שאר הסימנים יפים \u0003למקח וממכר,\u0004 לדעת מה נקרא איזור הרים ומה נקרא מקום עמקים.","כיון שדובר במשנה הראשונה בדבר מקומות שנהגו בהם מנהגים שונים, מביאים עוד הלכות שונות הקשורות בחילוקי מנהגי המקומות. \u0003מקום שנהגו למכור בהמה דקה לגוים — מוכרין, מקום שלא נהגו למכור\u0004 מפני כמה חששות וגזרות שיש בדבר — \u0003אין מוכרין.\u0004 אבל \u0003בכל מקום אין מוכרין להם בהמה גסה\u0004 כפרות וגמלים וגם לא \u0003עגלים וסייחים,\u0004 בין שהיו בעלי החיים \u0003שלמים\u0004 בין שהיו \u0003שבורים\u0004 (בעלי מומים). משום שאסרו חכמים מכירה זו שמא יקרה שלא תגמר המכירה או יתחרט אחד הצדדים, ונמצא למפרע שעבדו בבהמתו של ישראל בשבת בניגוד לאמור במפורש בתורה. \u0003ר' יהודה מתיר בשבורה\u0004 שהרי אינה בת מלאכה. \u0003בן בתירא מתיר בסוס\u0004 רכיבה, כי רכיבה על סוס אינה מלאכה שנאסרה מן התורה.","ועוד מנהג הקשור בדיני פסח. \u0003מקום שנהגו לאכול צלי בלילי פסחים\u0004 אף מחוץ למקדש ולאחר חורבנו — \u0003אוכלין, מקום שנהגו שלא לאכול\u0004 שמא ייראה כאוכל קרבן פסח בחוץ — \u0003אין אוכלין.\u0004","\u0003אמר רב יהודה אמר רב: אסור לו לאדם\u0004 בזמן הזה \u0003שיאמר \"בשר זה לפסח הוא\" מפני שנראה כמקדיש בהמתו\u0004 לקרבן פסח ולבסוף \u0003אוכל קדשים בחוץ. אמר רב פפא:\u0004 האיסור לומר \"דבר זה לפסח\" — הכוונה היא \u0003דוקא\u0004 למיני \u0003בשר,\u0004 שהם דומים לקדשים, \u0003אבל חיטי\u0004 \u0005[חיטים]\u0006 — \u0003לא,\u0004 כי כאן אין טועים, ויודעים כי \u0003דמינטר לפסחא קאמר\u0004 \u0005[שנשמר\u0006 הקמח \u0005לפסח אמר,\u0006 התכוון\u0005].\u0006","ושואלים: \u0003ובשר לא?\u0004 וכי באמת אסור לומר על בשר שהוא לצורך פסח? \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 \u0003אמר ר' יוסי: תודוס איש רומי הנהיג את בני רומי,\u0004 בני קהילתו, \u0003לאכול גדיים מקולסים\u0004 (צלויים בשלמותם) \u0003בלילי פסחים\u0004 כעין צליית הפסח במקדש. \u0003שלחו לו\u0004 חכמי ישראל: \u0003אילמלא תודוס אתה\u0004 שאתה אדם חשוב \u0003גזרנו עליך נדוי שאתה מאכיל את ישראל קדשים בחוץ.\u0004 ותוהים על הלשון: \u0003\"קדשים\" סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 הרי ודאי שלא היו אלה קדשים! \u0003אלא אימא\u0004 \u0005[אמור\u0006 תקן\u0005]\u0006"],["\u0003קרוב להאכיל את ישראל קדשים בחוץ\u0004 שנראה צלי זה כפסח ממש ושמא יבואו אנשים לטעות. ונדייק: גדי \u0003מקולס\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הוא שנאמר בו איסור זה, גדי \u0003שאין מקולס\u0004 — \u0003לא!\u0004 וקשה לרב האוסר אף בבשר סתם. \u0003אמרי\u0004 \u0005[אומרים]\u0006 כך יש להבין: גדי \u0003מקולס, לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003אמר\u0004 שהוא לפסח, \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003לא אמר\u0004 שהוא לפסח, כיון שנראה כעשוי לשם קרבן — אסור. גדי \u0003שאינו מקולס,\u0004 אם \u0003פירש\u0004 שהוא לפסח — \u0003אין\u0004 \u0005[כן],\u0006 יש לחשוש שמא נראה כמקדישו לקרבן, \u0003לא פירש — לא.\u0004","\u0003רב אחא מתני לה להא מתניתא\u0004 \u0005[היה שונה את הברייתא הזו\u0006 של תודוס\u0005]\u0006 \u0003כר' שמעון\u0004. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב ששת: בשלמא למאן דתני לה\u0004 \u0005[נניח למי ששונה אותה]\u0006 \u0003כר' יוסי — ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 \u0003אלא למאן דמתני\u0004 \u0005[למי ששונה\u0006 אותה\u0005]\u0006 \u0003כר' שמעון מי ניחא\u0004 \u0005[האם נוח]?\u0006","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שנחלקו חכמים באדם המקדיש דבר שאינו ראוי להקדש ידוע, כגון מי שרצה להביא מנחה מן השעורים (ואין מנחה אלא משל חיטים), שחכמים אומרים שהוא חייב להביא מנחה, שהרי בכל אופן בתחילת דבריו נדר להביא מנחה — אבל אינו מביא אלא מנחת חיטים. ו\u0003ר' שמעון פוטר\u0004 משום שלדעתו אותו אדם \u0003לא התנדב כדרך המתנדבים,\u0004 שהוא סבור שיש לראות את המשפט בשלמותו: \"מנחה מן השעורים\", ומנחת שעורים אינה קיימת כלל. ואף כאן לענין הפסח, כיון שאין אדם מקדיש לקרבן הפסח אלא בהמה חיה ואינו מקדיש בשר, וכיון שאומר \"בשר זה לפסח\" שוב אינו דומה להקדש, ואין שם הקדש חל עליו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ומאן דמתני לה\u0004 \u0005[ומי ששונה אותה]\u0006 \u0003כר' יוסי מי ניחא\u0004 \u0005[האם נוח]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: ר' שמעון\u0004 בענין מנחת שעורין \u0003בשיטת ר' יוסי אמרה,\u0004 ש\u0003אמר: אף בגמר דבריו אדם נתפס.\u0004 שנחלקו חכמים בדיני הקדשות, כאשר מקדיש אדם בהמה לשתי מטרות כאחת, כגון שאומר עליה שהיא עולה ושלמים, שלדעת ר' מאיר \"אדם נתפס בתחילת דבריו\", וכיון שהוציא מפיו בתחילה שם עולה — ממילא הוקדשה הבהמה לעולה. ואילו ר' יוסי אומר שאדם נתפס בכל דבריו, ובמקרה זה יש לדון באותה בהמה כמוקדשת לשני דברים, ולאחר שיפול בה מום יפדוה ויקנו בדמיה עולה ושלמים. ור' שמעון סבור כר' יוסי בענין מנחה מן השעורים, שלדעתו אין לקבל רק את המלה הראשונה \"מנחה\" שהזכיר אלא גם מה שהוסיף \"מן השעורים\" ועל ידי כך ביטל למעשה את דבריו הראשונים.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003מדר' שמעון סבר לה\u0004 \u0005[כיון שר' שמעון סבור]\u0006 כשיטת \u0003ר' יוסי,\u0004 אף \u0003ר' יוסי נמי סבר לה\u0004 \u0005[גם כן סבור]\u0006 \u0003כר' שמעון\u0004 שמי שמתנדב שלא כדרך המתנדבים לא אמר כלום, ואם כן הקשה לר' שמעון — קשה אף לר' יוסי! ודוחים: \u0003לא,\u0004 אמנם \u0003ר' שמעון סבר לה כר' יוסי,\u0004 אבל \u0003לא ר' יוסי סבר לה כר' שמעון\u0004 ולא קיבל את שיטתו שמי שהתנדב שלא כדרך המתנדבים אין בדבריו ממש.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בעיה בסיפור זה שהזכרנו, אותו \u0003תודוס איש רומי, גברא רבה הוה\u0004 \u0005[אדם גדול היה]\u0006 בתורה, ומפני חשש לכבוד התורה לא נידוהו, \u0003או בעל אגרופים הוה\u0004 איש תקיף במקומו שקשה להטיל עליו עונש.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ששנינו: \u0003עוד זו דרש תודוס איש רומי: מה ראו חנניה מישאל ועזריה שמסרו עצמם על קדושת השם לכבשן האש\u0004 בימי נבוכדנצר ולא עבדו עבודה זרה מפני היראה?","\u0003נשאו קל וחומר בעצמן מצפרדעים\u0004 במכות מצרים. \u0003ומה צפרדעים שאין מצווים על קדושת השם, כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 \u0003\"\u0004ושרץ היאר צפרדעים ועלו \u0003ובאו בביתך\u0004 ובחדר משכבך ועל מטתך ובבית עבדיך ובעמך \u0003ובתנוריך ובמשארותיך\"\u0004 (שמות ז, כח), \u0003אימתי משארות מצויות אצל תנור — הוי אומר בשעה שהתנור חם,\u0004 ובכלל זאת כיון שנצטוו מה' להציק למצרים באו ונכנסו לתוך התנורים הלוהטים. \u0003אנו שמצווים על קדושת השם — על אחת כמה וכמה\u0004 שצריכים למסור נפשנו על כך ולהכנס לשם כך אף לכבשן האש. ולפי דרכנו למדנו שתודוס דרש בדברי תורה ברבים ומכאן שאדם גדול היה.","\u0003ר' יוסי בר' אבין אמר:\u0004 חשיבותו של תודוס היתה ש\u0003מטיל מלאי לכיס של תלמידי חכמים היה\u0004 שהיה מלוה כסף לתלמידי חכמים ומשתתף עמם כדי שיוכלו לפתוח עסקים ובזה כחו. ש\u0003אמר ר' יוחנן: כל המטיל מלאי לכיס של תלמידי חכמים זוכה ויושב בישיבה של מעלה שנאמר \"כי בצל החכמה בצל הכסף\"\u0004 (קהלת ז, יב), שמתפרש שנותן הכסף לחכמים זוכה להיות עמם בשל כך \"בצל החכמה\".","ועוד ממשיכים להביא דברים על הבדלי מנהגים בין מקומות שונים. \u0003מקום שנהגו להדליק את הנר\u0004 בבית \u0003בלילי יום הכפורים — מדליקין\u0004 אותו. \u0003מקום שנהגו שלא להדליק — אין מדליקין, ומדליקין\u0004 במקום שלא נהגו להדליק בבית \u0003בבתי כנסיות ובבתי מדרשות\u0004 מפני כבוד המקום. \u0003ובמבואות האפלים\u0004 שלא ינזקו הבריות שם, \u0003ועל גבי\u0004 (ליד) \u0003החולים.\u0004","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 \u0003בין\u0004 במקום \u0003שאמרו להדליק ובין\u0004 במקום \u0003שאמרו שלא להדליק — שניהן לדבר אחד נתכוונו\u0004 — להרחיק את האדם מן העבירה. שכן יום הכיפורים אסור בתשמיש, ואלה שאמרו להדליק סברו כי בודאי לא ישמש אדם מיטתו לאור הנר ונמצא האור מסייע להפרישם. והאחרים סברו להיפך שאם איננו רואה את אשתו לא יבוא לחשוב על עניני תשמיש עמה ולכן לא ידליק ביום הכיפורים. ומכל מקום — לאותה מטרה עצמה נתכוונו. \u0003אמר רב יהושע דרש רבא: \"ועמך כלם צדיקים לעולם יירשו ארץ\u0004 נצר מטעי מעשה ידי להתפאר\u0003\"\u0004 (ישעיה ס, כא), \u0003בין שאמרו להדליק ובין שאמרו שלא להדליק — שניהם לא נתכוונו אלא לדבר אחד\u0004 ולשם מצוה. נמצא שכל ישראל מתכוונים אף בשעת שינוי המנהגים לאותן כוונות שבקדושה.","מענין לענין בדיני הדלקת הנר, וכפי שלהלן יבואר שהענין קשור בדיני יום הכיפורים, מביאים מה ש \u0003אמר רב יהודה אמר שמואל: אין מברכין על הנר\u0004 (ברכת \"בורא מאורי האש\") \u0003אלא במוצאי שבת, הואיל ותחלת ברייתו הוא\u0004 שהאש הראשונה נבראה ונוצרה במוצאי שבת. \u0003אמר ליה ההוא סבא\u0004 \u0005[אמר לו זקן אחד]\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה בר בר חנה: ישר\u0004 (נכון), \u0003וכן אמר ר' יוחנן.\u0004 מסופר: \u0003עולא הוה רכיב חמרא ואזיל והוה שקיל ואזיל\u0004 \u0005[היה רוכב על החמור והולך והיה מהלך]\u0006 \u0003ר' אבא מימיניה\u0004 \u0005[מימינו]\u0006 \u0003ורבה בר בר חנה משמאליה\u0004 \u0005[משמאלו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לעולא:\u0004 האם \u0003ודאי\u0004 (נכון ומדוייק) הוא מה \u0003דאמריתו\u0004 \u0005[שאמרתם,\u0006 מה שמוסרים בשמך\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: אין מברכין על האור אלא במוצאי שבת, הואיל ותחלת ברייתו הוא\u0004 למעט מוצאי יום הכיפורים, שאין לברך על הנר במוצאי יום הכיפורים.","וכיון שעולא מעולם לא מסר שמועה זו, הבין עולא שמן הסתם נתגלגלה שמועה זו על ידי רבה בר בר חנה שהביא מארץ ישראל דבר זה, מסופר: \u0003הדר\u0004 \u0005[החזיר]\u0006 \u0003עולא\u0004 פניו, \u0003חזא ביה\u0004 \u0005[וראה את]\u0006 \u0003רבה בר בר חנה בישות\u0004 \u0005[בעין זעומה]\u0006 שכעס עליו על שאמר דבר שלא אמרו ר' יוחנן, אבל לא אמר דבר. אבל רבה בר בר חנה הבין מה כוונתו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא לאו אהא אמרי אלא אהא אמרי\u0004 \u0005[אני לא על\u0006 דבר \u0005זה אמרתי אלא על זה\u0006 דבר אחר \u0005אמרתי]\u0006 שהיה מעשה כי \u0003תני תנא קמיה\u0004 \u0005[שנה התנא\u0006 חוזר המשניות \u0005לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו, \u0003ר' שמעון בן אלעזר אומר: יום הכפורים שחל להיות בשבת אף במקום שאמרו שלא להדליק\u0004 ביום הכיפורים \u0003מדליקין\u0004 בו נר \u0003מפני כבוד השבת. ועני\u0004 \u0005[וענה]\u0006 \u0003ר' יוחנן בתריה\u0004 \u0005[אחריו]\u0006 להשלים דבריו: \u0003וחכמים אוסרים\u0004 אפילו כשחל בשבת. \u0003אמר\u0004 לו: \u0003עדא תהא\u0004 \u0005[זו תהא]\u0006 כך מתקבל ומסתבר שזה היה הדבר שאמר ר' יוחנן.","\u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רב יוסף\u0004 על מאורע זה את הפסוק \u0003\"מים עמקים עצה בלב איש\u0004"],["\u0003ואיש תבונה ידלנה\"\u0004 (משלי כ, ה); \u0003\"מים עמקים עצה בלב איש\" — זה עולא\u0004 שחשב דבר בלבבו אבל לא אמרו, \u0003\"ואיש תבונה ידלנה\" — זה רבה בר בר חנה\u0004 שהבין ברמז אף שלא נאמר לו במפורש. ושואלים: \u0003ואינהו\u0004 \u0005[והם]\u0006 עולא ורבה בר בר חנא שלא הודו לדברי ר' אבא \u0003כמאן סברוה\u0004 \u0005[כפי מי סברו]?\u0006 ומשיבים: \u0003כי הא\u0004 \u0005[כפי זו]\u0006 ש\u0003אמר ר' בנימין בר יפת, אמר ר' יוחנן: מברכין על האור, בין במוצאי שבת בין במוצאי יום הכפורים. וכן עמא דבר\u0004 \u0005[העם נוהג].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003אין מברכין על האור אלא במוצאי שבת, הואיל ותחלת ברייתו הוא\u0004 שבמוצאי שבת נבראה אש ראשונה. \u0003וכיון שרואה\u0004 אותו — \u0003מברך מיד.\u0004 ואילו \u0003ר' יהודה אומר\u0004 אינו מברך מיד אלא ממתין, ו\u0003סודרן\u0004 את ברכת האש וברכת הבשמים \u0003על הכוס\u0004 של הבדלה. \u0003ואמר ר' יוחנן: הלכה כר' יהודה,\u0004 ואם כן מדוע מברכים גם במוצאי יום הכיפורים!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003כאן\u0004 שמברכים אף במוצאי יום הכיפורים מדובר \u0003באור ששבת, וכאן\u0004 שאין מברכים עליו במוצאי יום הכיפורים מדובר \u0003באור היוצא מן העצים והאבנים\u0004 שיצרוהו במוצאי שבת, שאור כזה ראוי לברך עליו רק במוצאי שבת לפי שאז היתה תחילת ברייתו.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אור היוצא מן העצים ומן האבנים מברכין עליו, ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אין מברכין עליו.\u0004 ויש ליישב כי \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 שאמרו שמברכים עליו — הרי זה \u0003במוצאי שבת, כאן\u0004 שאסרו לברך עליו מדובר \u0003במוצאי יום הכפורים.\u0004","מסופר, כי \u0003רבי\u0004 היה \u0003מפזרן,\u0004 שהיה אומר את הברכות על האש והבשמים כל אחת כפי שנזדמנה לו. ו\u0003ר' חייא\u0004 היה \u0003מכנסן,\u0004 שהיה אומרן יחד בהבדלה. \u0003אמר ר' יצחק בר אבדימי: אף על פי שרבי מפזרן\u0004 ומברך מיד ויוצא ידי חובתו — \u0003חוזר וסודרן על הכוס, כדי להוציא בניו ובני ביתו.\u0004","הוזכר קודם שהאש נבראה במוצאי שבת. ושואלים: \u0003ואור\u0004 (אש) \u0003במוצאי שבת איברי\u0004 \u0005[נברא]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשרה דברים נבראו בערב שבת בין השמשות\u0004 שבכל אחד מהם יש צד של נס ופלא, ו\u0003אלו הן: באר\u0004 של מרים, \u0003והמן\u0004 שירד במדבר, \u0003וקשת, כתב\u0004 של הלוחות, \u0003ומכתב\u0004 בו נחקק כתב הלוחות, \u0003והלוחות\u0004 עצמן, \u0003וקברו של משה, ומערה שעמד בו משה ואליהו, פתיחת פי האתון ופתיחת פי הארץ לבלוע את הרשעים\u0004 בזמן קורח.","\u0003ר' נחמיה אומר משום אביו: אף האור\u0004 (האש) \u0003והפרד\u0004 שהוא כלאים, נברא אז. \u0003ר' יאשיה אומר משום אביו: אף האיל\u0004 ששחט אברהם אבינו במקום יצחק, ותולעת \u0003השמיר\u0004 שחתכו בו את אבני המזבח. \u0003ר' יהודה אומר: אף הצבת. הוא היה אומר: צבתא בצבתא מתעבדא, וצבתא קמייתא מאן עבד\u0004 \u0005[צבת בצבת עשויה, וצבת ראשונה מי עשה]?\u0006 שהרי ליצירת צבת אחת חייבים להיעזר בצבת אחת! \u0003הא לאי\u0004 \u0005[הרי מכאן]\u0006 כי צבת ראשונה \u0003בריה בידי שמים היא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפשר יעשנה\u0004 תבנית צבת \u0003בדפוס ויקבענה כיון\u0004 (ישר) ביציקה בלבד ואין צורך לעשותה דווקא על ידי צבת אחרת. \u0003הא לאי\u0004 \u0005[הרי מכאן]\u0006 ש\u0003בריה בידי אדם היא.\u0004 על כל פנים שנינו שם שהאש נבראה בערב שבת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003באור\u0004 (אש) \u0003דידן\u0004 \u0005[שלנו],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003באור\u0004 של \u0003גיהנם.\u0004 ומסבירים: \u0003אור דידן\u0004 \u0005[שלנו]\u0006 \u0003במוצאי שבת\u0004 נברא, \u0003אור\u0004 של \u0003גיהנם בערב שבת\u0004 נברא. ושואלים עוד: \u0003ואור\u0004 של \u0003גיהנם בערב שבת איברי\u0004 \u0005[נברא],\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שבעה דברים נבראו קודם שנברא העולם ואלו הן: תורה, ותשובה, וגן עדן, וגיהנם, וכסא הכבוד, ובית המקדש, ושמו של משיח.\u0004","וראיה לכל דבר: \u0003תורה, דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"ה' קנני ראשית דרכו\u0004 קדם מפעליו מאז\u0003\"\u0004 (משלי ח, כב), שלפני שנבראו שאר דברים נבראה התורה וכן מפורש בהמשכם של אותם כתובים. \u0003תשובה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בטרם הרים ילדו\u0004 ותחולל ארץ ותבל ומעולם עד עולם אתה אל \u0003\", וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"תשב אנוש עד דכא ותאמר שובו בני אדם\"\u0004 (תהילים צ, ב-ג).","\u0003גן עדן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויטע ה' אלהים גן בעדן מקדם\"\u0004 (בראשית ב, ח), ומתפרש מקדם במשמעות מקודם, כלומר קודם שנברא העולם. \u0003גיהנם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ערוך מאתמול תפתה\"\u0004 (ישעיהו ל, לג), כלומר עוד קודם מאתמול של העולם כבר היה ערוך הגיהנום.","\u0003כסא הכבוד ובית המקדש, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כסא כבוד מרום מראשון מקום מקדשנו\"\u0004 (ירמיהו יז יב), כלומר כסא הכבוד ומקום מקדשנו עוד קודם ראשית העולם נבראו. \u0003שמו של משיח, דכתיב\u0004 \u0005[שנאמר]\u0006 בפרק המדבר במלך המשיח: \u0003\"יהי שמו לעולם לפני שמש ינון שמו\"\u0004 (תהילים עב, יז), כלומר לפני שנברא העולם (ובכללו השמש) כבר היה קיים שמו של משיח. ומכל מקום נאמר כאן שגיהנום נברא עוד לפני העולם!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003חללה\u0004 של גיהנום \u0003הוא\u0004 ש\u0003נברא קודם שנברא העולם, ואור דידיה\u0004 \u0005[והאש שלו]\u0006 \u0003בערב שבת איברי\u0004 \u0005[נבראה].\u0006","ועוד שואלים \u0003ואור\u0004 (אש) \u0003דידיה\u0004 \u0005[שלו]\u0006 \u0003בערב שבת איברי\u0004 \u0005[נברא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: אור שברא הקדוש ברוך הוא בשני בשבת — אין לו כבייה לעולם, שנאמר: \"ויצאו וראו בפגרי האנשים הפשעים בי כי תולעתם לא תמות ואשם לא תכבה\u0004 והיו דראון לכל בשר\u0003\"\u0004 (ישעיה סו, כד). \u0003ואמר ר' בנאה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' עולא: מפני מה לא נאמר \"כי טוב\"\u0004 בסוף מעשה היצירה של יום ה\u0003שני בשבת\u0004 כמו בשאר הימים — \u0003מפני שנברא בו אור של גיהנם. ואמר ר' אלעזר: אף על פי שלא נאמר בו \"כי טוב\" — חזר וכללו\u0004 ביום ה\u0003ששי שנאמר: \"וירא אלהים את כל אשר עשה והנה טוב מאד\"\u0004 (בראשית א, לא).","\u0003אלא\u0004 כך יש לומר: \u0003חללה\u0004 של גיהנום \u0003קודם שנברא העולם ואור דידיה\u0004 \u0005[והאש שלו]\u0006 \u0003בשני בשבת\u0004 נברא \u0003ואור דידן\u0004 \u0005[והאש שלנו]\u0006 \u0003במחשבה עלה ליבראות בערב שבת, ולא נברא\u0004 בפועל \u0003עד מוצאי שבת.\u0004 וראיה לדבר \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: שני דברים עלו במחשבה ליבראות בערב שבת, ולא נבראו\u0004 בפועל \u0003עד מוצאי שבת, ובמוצאי שבת נתן הקדוש ברוך הוא דיעה באדם הראשון מעין דוגמא של מעלה\u0004 שיש בה כוח בריאה ויצירה, \u0003והביא שני אבנים וטחנן זו בזו\u0004 כלומר, שפשף אותן זו בזו עד ש\u0003יצא מהן אור\u0004 (אש) ראשונה, \u0003והביא שתי בהמות\u0004 סוס וחמור \u0003והרכיב זו בזו ויצא מהן פרד. רבן שמעון בן גמליאל אומר: פרד\u0004 ראשון \u0003בימי ענה היה, שנאמר:\u0004 \"ואלה בני צבעון ואיה וענה \u0003הוא ענה אשר מצא את הימם במדבר\u0004 ברעותו את החמרים לצבעון אביו\" (בראשית לו, כד),","\u0003דורשי חמורות\u0004 שהיו דורשים דברים סתומים בצורה מיוחדת, \u0003היו אומרים: ענה פסול היה, לפיכך\u0004 אף הוא \u0003הביא פסול לעולם, שנאמר: \"אלה בני שעיר החרי\u0004 יושבי הארץ לוטן ושובל וצבעון וענה\u0003\"\u0004 (בראשית לו, כ), \u0003וכתיב\u0004 \u0005[ו\u0006עוד \u0005נאמר]\u0006 \u0003\"ואלה בני צבעון ואיה וענה\"\u0004 (בראשית לו, כד), נמצא איפוא שענה וצבעון היו בניו של שעיר, ובפסוק אחר נאמר שענה היה בנו של צבעון! \u0003אלא מלמד שבא צבעון על אמו\u0004 אשת שעיר \u0003והוליד ממנה ענה,\u0004 ואם כן באמת הוא בן צבעון, והוא קרוי בנו של שעיר.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003תרי ענה הוו\u0004 \u0005[שני ענה היו]?!\u0006 אחד בן צבעון ואחד בן שעיר! \u0003אמר רבא: אמינא מילתא\u0004 \u0005[אומר אני דבר]\u0006 שאפילו \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003לא אמרה\u0004 \u0005[אמרו],\u0006 והכוונה ודאי אינה לשבור מלך פרס אלא הוא כינוי, \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003שמואל,\u0004 שדעתו בדינים נתקבלה להלכה וחשובים היו כדבריו של המלך לנתיניו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בגרסה אחרת: \u0003אמר רב פפא: אמינא מילתא\u0004 \u0005[אומר אני דבר]\u0006 ש\u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003לא אמרה\u0004 \u0005[אמרו]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 הרי זה כינוי ל\u0003רבא, אמר קרא \"הוא ענה\u0004 אשר מצא את הימים \u0003\"\u0004— \u0003הוא ענה דמעיקרא\u0004 \u0005[שמתחילה]\u0006 המוזכר בפרשה זו קודם לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשרה דברים נבראו בערב שבת בין השמשות, ואלו הן: באר, ומן, וקשת, הכתב, והמכתב, והלוחות, קברו של משה, ומערה שעמד בה משה ואליהו, פתיחת פי האתון, ופתיחת פי הארץ לבלוע את הרשעים. ויש אומרים: אף מקלו של אהרן שקדיה ופרחיה\u0004 נבראו בערב שבת בין השמשות, \u0003ויש אומרים: אף המזיקים, ויש אומרים:\u0004 אף"],["\u0003בגדו של אדם הראשון,\u0004 שנאמר: \"ויעש ה' אלהים לאדם ולאשתו כתנות עור וילבישם\" (בראשית ג, כא).","אגב עניינים שהבאנו קודם מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבעה דברים מכוסים\u0004 (נעלמים) \u0003מבני אדם, אלו הן: יום המיתה\u0004 מתי יהא, \u0003ויום הנחמה\u0004 שבו יתנחם מצרותיו, \u0003ועומק הדין\u0004 לדעת מהי האמת בסכסוך מסויים, \u0003ואין אדם יודע מה בלבו של חבירו, ואין אדם יודע במה משתכר\u0004 כלומר, באיזה דבר ירויח ובאיזה יפסיד, \u0003ומלכות בית דוד מתי תחזור\u0004 לישראל, \u0003ומלכות\u0004 רומי \u0003חייבת\u0004 (הרשעה) \u0003מתי תכלה.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדומה לכך: \u0003שלושה דברים עלו במחשבה ליבראות, ואם לא עלו — דין\u0004 (ראוי) \u0003הוא שיעלו,\u0004 כי הם חלק מבניינו של עולם: \u0003על המת שיסריח\u0004 שיצטרכו לקוברו, ולא יראוהו קרוביו תמיד ויצטערו. \u0003ועל המת שישתכח מן הלב. ועל התבואה שתרקב,\u0004 ואי אפשר לאצור אותה לעולם, ולכן חייבים למוכרה לאחרים. \u0003ויש אומרים: על המטבע שיצא,\u0004 כלומר, שיקבלו אנשים את הכסף כאמצעי תשלום.","ועוד בחילוק מנהגים: \u0003מקום שנהגו לעשות מלאכה בתשעה באב — עושין, מקום שנהגו שלא לעשות מלאכה\u0004 — \u0003אין עושין, ובכל מקום תלמידי חכמים בטלים\u0004 ממלאכה בתשעה באב מפני אבל החורבן. \u0003רבן שמעון בן גמליאל אומר: לעולם יעשה אדם עצמו תלמיד חכם\u0004 לענין זה, ויבטל ממלאכה ואין בכך משום גאוה יתירה.","\u0003אמר שמואל: אין תענית ציבור בבבל\u0004 בכל החומרות הנוהגות בתענית ציבור יותר מבתענית יחיד \u0003אלא תשעה באב בלבד.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[האם תאמר]\u0006 ש\u0003סבר שמואל\u0004 משום השוואת תשעה באב לתענית ציבור, ש\u0003תשעה באב בין השמשות שלו אסור\u0004 בכל העינויים שנאמרו בו, משום שהחמירו בו חומרה יתירה? והרי \u0003אמר שמואל: תשעה באב בין השמשות שלו מותר\u0004 שלא גזרו חכמים בו איסור. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003קסבר שמואל: כל תענית ציבור בין השמשות שלו מותר, והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 בענין תענית צבור: \u0003\"אוכלין ושותין מבעוד יום\".\u0004 ומדייקים: \"מבעוד יום\" \u0003למעוטי מאי\u0004 \u0005[למעט מה\u0006 נאמר הדבר\u0005],\u0006 \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 \u0003בין השמשות\u0004 של תענית ציבור, שאסור? ודוחים: \u0003לא, למעוטי\u0004 \u0005[למעט]\u0006 \u0003משחשיכה\u0004 שאז ודאי אסור.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003אין בין תשעה באב ליום הכפורים\u0004 מלכתחילה, \u0003אלא\u0004 ש\u0003זה\u0004 יום הכיפורים \u0003ספיקו אסור\u0004 כיון שהוא מן התורה, \u0003וזה\u0004 תשעה באב \u0003ספיקו מותר.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ספיקו מותר — לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003בין השמשות\u0004 שהוא ספק יום ספק לילה? ודוחים: \u0003לא\u0004 הכוונה \u0003כ\u0004פי ש\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 לענין \u0003קביעא דירחא\u0004 \u0005[קביעות החודש],\u0006 אם אנו חוששים שמא איננו יודעים מתי נקבע ראש החודש ונצטרך לעשות יומיים מספק. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה שאין חוששים לספק בתשעה באב — הרי זה לענין \u0003קביעא דירחא.\u0004","\u0003דרש רבא: עוברות\u0004 (נשים הרות) \u0003ומניקות — מתענות ומשלימות\u0004 (צמות עד סוף היום) \u0003בו\u0004 בתשעה באב, \u0003כדרך שמתענות ומשלימות ביום הכיפורים, ובין השמשות שלו אסור. וכן אמרו משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן.\u0004 ושואלים: \u0003ומי אמר\u0004 \u0005[והאם אמר]\u0006 \u0003ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 והרי \u0003אמר ר' יוחנן: תשעה באב אינו כתענית ציבור. מאי לאו\u0004 \u0005[האם לא]\u0006 כוונתו לענין \u0003בין השמשות?\u0004 ומשיבים \u0003לא,\u0004 אלא לענין \u0003מלאכה\u0004 בתשעה באב שונה דינו משאר תעניות ציבור.","ותוהים: \u0003מלאכה?\u0004 הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר במפורש במשנה: \u0003מקום שנהגו לעשות מלאכה בתשעה באב — עושין, ובמקום שנהגו שלא לעשות — אין עושין,\u0004 משמע שבתשעה באב אין איסור מלאכה אלא רק מנהג מקומות מסויימים שלא לעשות מלאכה. \u0003ואפילו רבן שמעון בן גמליאל לא אמר אלא\u0004 כהמלצה שיעשה אדם עצמו כתלמיד חכם לענין זה, \u0003דכי יתיב\u0004 \u0005[שאם יושב]\u0006 \u0003ולא עביד\u0004 \u0005[עושה]\u0006 מלאכה, \u0003לא מיחזי כיוהרא\u0004 \u0005[נראה כגאוה]\u0006 שמתגאה ועושה עצמו כחכם, \u0003אבל מיסר\u0004 \u0005[לאסור]\u0006 את המלאכה \u0005—\u0006 \u0003לא אסר.\u0004","\u0003אלא\u0004 יש לחזור מפירוש זה ולומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אינו כתענית ציבור\u0004 — לענין \u0003תפלת נעילה.\u0004 שבתענית ציבור וביום הכיפורים מתפללים חמש תפילות (ערבית, שחרית, מוסף, מנחה, ונעילה), ואילו בתשעה באב אין מתפללין אלא שלוש, כביום חול אחר. ואולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוחנן: ולואי שיתפלל אדם והולך כל היום כולו,\u0004 משמע שאם מוסיף אדם תפילה, לדעת ר' יוחנן הרשות בידו!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בתענית ציבור \u0003חובה\u0004 היא להתפלל חמש תפילות, \u0003הכא\u0004 \u0005[כאן]\u0006 בתשעה באב אמר ר' יוחנן ש\u0003רשות\u0004 היא בלבד, ואם רצונו להוסיף — יוסיף. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אינו כתענית ציבור\u0004 לענין \u0003עשרים וארבע\u0004 ברכות שהיו נאמרות בתענית ציבור, שהוסיפו שש ברכות על שמונה עשרה שבכל יום, ובתשעה באב אין אומרים אלא שמונה עשרה ברכות בלבד.","\u0003רב פפא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו כתענית ציבור\"\u0004 הכוונה היא להחמיר, שתעניות הציבור שעל הגשם היו בהן הבדלים, שלוש תעניות ראשונות היו קלות יותר, שלוש נוספות חמורות מהן ושבע נוספות חמורות יותר, שתשעה באב \u0003אינו\u0004 דינו כתעניות ציבור \u0003ראשונות\u0004 בהן הקלו בכמה דברים כגון שאין מקפידים על שעת בין השמשות, \u0003אלא כאחרונות\u0004 ובאחרונות \u0003אסורה\u0004 אף בבין השמשות.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 הלוא כבר שנינו ש\u0003אין בין תשעה באב ליום הכיפורים אלא שזה ספיקו אסור וזה ספיקו מותר, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ספיקו מותר — לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003בין השמשות שלו\u0004 שהוא מותר, ובניגוד לדברי רב פפא! \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: לא,\u0004 הכוונה היא \u0003לקביעא דירחא\u0004 \u0005[לקביעות החודש],\u0006 שאין אנו עושים יום שני של תשעה באב בגלויות ואין חוששים לטעות. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכל\u0004 שאר \u0003דברים זה וזה שוין.\u0004","ומעירים: \u0003מסייע\u0004 הדבר לשיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: אסור לו לאדם שיושיט אצבעו במים בתשעה באב, כדרך שאסור להושיט אצבעו ביום הכיפורים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003אין בין תשעה באב לתענית ציבור אלא שזה אסור בעשיית מלאכה וזה מותר בעשיית מלאכה במקום שנהגו\u0004 לעשות. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכל דבריהם\u0004 האחרים — \u0003זה וזה שוין. ואילו גבי תענית ציבור תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשאמרו\u0004 בתענית ציבור \u0003אסור ברחיצה — לא אמרו אלא כל גופו\u0004 אסור ברחיצה, \u0003אבל פניו ידיו ורגליו — לא,\u0004 ומותר לרחוץ אותם אף בתענית ציבור, הרי שהחמיר בתשעה באב יותר מבתענית ציבור!","\u0003אמר רב פפא:\u0004"],["\u0003תנא קולי קולי קתני\u0004 \u0005[קולות קולות הוא שונה]\u0006 כלומר, התנא שנה רק אותם דברים שבהם תשעה באב קל מתענית ציבור, אבל לא שנה דברים שבהם חמור הוא יותר, ולא מיצה את כל ההבדלים.","שנינו במשנה: \u0003ובכל מקום תלמידי חכמים\u0004 אינם עושים מלאכה בתשעה באב, ולדעת רבן שמעון בן גמליאל הכל צריכין לעשות עצמם לענין זה כתלמידי חכמים. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003רבן שמעון בן גמליאל סבר\u0004 כי \u0003לא חיישינן ליוהרא\u0004 \u0005[חוששים אנו לגאוה]\u0006 שנוהג אדם מנהג גדולים כשאינו ראוי לכך. \u0003ורבנן סברי: חיישינן ליוהרא\u0004 \u0005[וחכמים סבורים: חוששים אנו לגאוה].\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך שמענו אותם\u0006 אומרים\u0005]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חתן\u0004 פטור מלקרות קריאת שמע בלילה הראשון של חתונתו מפני שטרוד במחשבה על ביאת מצוה. ו\u0003אם ירצה\u0004 להחמיר על עצמו \u0003לקרות קריאת שמע לילה הראשון — קורא. רבן שמעון בן גמליאל אמר: לא כל הרוצה ליטול את השם\u0004 שהוא ירא שמים מופלג \u0003יטול.\u0004 הפך שיטותיהם כאן!","\u0003אמר ר' יוחנן: מוחלפת השיטה,\u0004 כלומר, יש להחליף את הדעות באחד המקורות. \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: לא תיפוך\u0004 \u0005[אל תהפוך],\u0006 ויש דרך ליישב את הסתירה: \u0003דרבנן אדרבנן\u0004 \u0005[\u0006שיטת \u0005חכמים על\u0006 שיטת \u0005חכמים]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דכולי עלמא עבדי\u0004 \u0005[שכל העולם עושים]\u0006 \u0003מלאכה, ואיהו\u0004 \u0005[והוא]\u0006 \u0003לא עביד\u0004 \u0005[עושה] —\u0006 \u0003מיחזי כיוהרא\u0004 \u0005[נראה\u0006 הדבר \u0005כגאוה]\u0006 שהינו יוצא דופן במקומו, \u0003אבל התם\u0004 \u0005[שם]\u0006 בחתונה, \u0003כיון דכולי עלמא קרי ואיהו נמי קרי\u0004 \u0005[שכל העולם קוראים\u0006 קריאת שמע \u0005והוא גם כן קורא\u0006 עמם\u0005] —\u0006 \u0003לא מיחזי כיוהרא\u0004 \u0005[נראה כגאוה]\u0006 שאינו יוצא דופן בציבור שלו.","ש\u0003רבן שמעון בן גמליאל\u0004 על שיטת \u0003רבן שמעון בן גמליאל\u0004 גם כן \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 בקריאת שמע \u0003דבעינן\u0004 \u0005[שצריכים]\u0006 \u0003כוונה, ואנן סהדי\u0004 \u0005[ואנו עדים]\u0006 כלומר, הכל יודעים ש\u0003לא מצי כווני דעתיה\u0004 \u0005[יכול לכוון דעתו],\u0006 \u0003מיחזי כיוהרא\u0004 \u0005[נראה כגאוה]\u0006 שהרי הוא כמכריז: אני אוכל לכוון דעתי שלא כאחרים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בבטלה ממלאכה בתשעה באב \u0003לא מיחזי כיוהרא\u0004 \u0005[אינו נראה כיוהרה],\u0006 \u0003אמרי\u0004 \u0005[אומרים\u0006 הבריות\u0005]:\u0006 \u0003מלאכה הוא דלית ליה\u0004 \u0005[שאין לו],\u0006 \u0003פוק חזי\u0004 \u0005[צא ראה]\u0006 \u0003כמה בטלני איכא בשוקא\u0004 \u0005[בטלנים יש בשוק]\u0006 בכל יום שאינם עושים מלאכה.","בפרק זה הובאו אגב חילוקי המנהגים בענין עשיית מלאכה בערב הפסח כמה חילוקי מנהגים אחרים, ומעתה שבים לענין ראשון, כהמשך ישיר לאמור שם. \u0003וחכמים אומרים: ביהודה היו עושין מלאכה בערבי פסחים עד חצות, ובגליל לא היו עושין\u0004 מלאכה בערב פסח \u0003כל עיקר. הלילה\u0004 כלומר, אור לארבעה עשר בניסן, \u0003בית שמאי אוסרים\u0004 במלאכה, \u0003ובית הלל מתירין עד הנץ החמה.\u0004","על גוף המשנה תוהים: \u0003מעיקרא תנא מנהגא\u0004 \u0005[מתחילה\u0006 בתחילת הפרק \u0005שנה מנהג]\u0006 לומר שיש מקומות שנהגו שלא לעשות מלאכה, \u0003ולבסוף\u0004 במשנה שלפנינו \u0003תנא איסורא\u0004 \u0005[שנה איסור]\u0006 שבית שמאי אוסרים — משמע שאין הדבר תלוי במנהג אלא אסור מן הדין!","\u0003אמר ר' יוחנן: לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 המשנה הראשונה בפרק — כשיטת \u0003ר' מאיר, הא\u0004 \u0005[זו]\u0006 משנתנו — כשיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: ביהודה היו עושין מלאכה בערבי פסחים עד חצות, ובגליל אינן עושין כל עיקר. אמר לו ר' מאיר: מה ראייה יהודה וגליל לכאן\u0004 כלומר, מה מקום יש לדבר על חילוקי דין בין יהודה וגליל? \u0003אלא, מקום שנהגו לעשות מלאכה — עושין, ומקום שנהגו שלא לעשות — אין עושין.\u0004 ומדייקים: \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003ר' מאיר\u0004 שהדבר הוא \u0003מנהגא\u0004 \u0005[מנהג]\u0006 \u0003מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003ר' יהודה\u0004 התכוון לומר ש\u0003איסורא קאמר\u0004 \u0005[איסור יש]\u0006 בעשיית מלאכה בגליל.","ומקשים: \u0003וסבר ר' יהודה ארבעה עשר מותר בעשיית מלאכה\u0004 בכל מקום פרט לגליל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: המנכש\u0004 את השדה ביום \u0003שלשה עשר\u0004 בניסן \u0003ונעקרה\u0004 השבולת \u0003בידו — שותלה במקום הטיט\u0004 שתיקלט ותשריש עוד לפני הבאת העומר בששה עשר בניסן, ועל ידי כך תותר באכילה בשנה זו, \u0003ואין שותלה במקום הגריד\u0004 (היבש) שמן הסתם לא תיקלט שם מיד, ואם תיקלט אותה נטיעה ותחל לצמוח לאחר העומר, אסור יהיה לאכול פירותיה עד הבאת העומר בשנה הבאה.","ומלשונו של ר' יהודה נדייק: אם אותו אדם היה מנכש \u0003בשלשה עשר — אין\u0004 \u0005[כן]\u0006 הדין, אבל \u0003בארבעה עשר — לא,\u0004 אין אפשרות לעשות זאת, \u0003מכדי שמעינן ליה\u0004 \u0005[הלוא שמענו אותו]\u0006 את \u0003ר' יהודה\u0004 ש\u0003אמר: כל הרכבה שאינה קולטת לשלשה ימים — שוב אינה קולטת, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003ארבעה עשר מותר בעשיית מלאכה — למה לי\u0004 לשנות שהיה מעשה ביום \u0003שלשה עשר?\u0004 הרי אפשר לחדש יותר ולומר שהיה הדבר בארבעה עשר, ועדיין יש שלושה ימים לקליטה! כיצד, \u0003האיכא ארביסר, וחמיסר ומקצת שיתסר\u0004 \u0005[הרי יש\u0006 יום \u0005ארבעה עשר וחמשה עשר\u0006 בניסן, \u0005ומקצת ששה עשר]\u0006 ואלה שלושה ימים של קליטה! \u0003אמר רבא: בגליל שנו\u0004 הלכה זו, וכבר אמר ר' יהודה שבגליל אין עושים מלאכה כל היום.","ושואלים: אף שם \u0003והאיכא ליליא\u0004 \u0005[והרי יש לילה]\u0006 אור לארבעה עשר שגם בגליל (לדעת בית הלל שהלכה כמותם) מותר לעשות מלאכה ויכול איפוא לשנות שניכש בליל ארבעה עשר! \u0003אמר רב ששת: כבית שמאי\u0004 אמר ר' יהודה דברים אלה. \u0003רב אשי אמר:\u0004 אין צורך להידחק בתירוץ זה אלא \u0003לעולם\u0004 סבר \u0003כבית הלל,\u0004 ומדוע לא שנה ליל ארבעה עשר — \u0003לפי שאין דרכן של בני אדם לנכש בלילה,\u0004 שהרי הניכוש נועד להוציא עשבים רעים ואין עושים זאת בחשיכה.","\u0003רבינא אמר: לעולם\u0004 יכול אתה לפרש שמדובר אפילו \u0003ביהודה,\u0004 אולם לענין \u0003השרשה חד\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003\"מקצת היום ככולו\" אמרינן\u0004 \u0005[אומרים אנו],\u0006 לענין יום ששה עשר \u0003תרי\u0004 \u0005[שתי\u0006 פעמים\u0005]\u0006 \u0003\"מקצת היום ככולו\" — לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 גם מקצת יום ארבעה עשר וגם מקצת יום ששה עשר, שלצורך ההשרשה דרוש זמן קצוב ואין ללכת כאן על פי העקרון הפורמאלי הקבוע בהלכה שמקצת היום נידון כיום שלם.","\u0003ר' מאיר אומר: כל מלאכה שהתחיל בה קודם לארבעה עשר בניסן — גומרה בארבעה עשר, אבל לא יתחיל בה בתחלה\u0004 (מלכתחילה) \u0003בארבעה עשר, אף על פי שיכול לגומרה. וחכמים אומרים:\u0004 רק \u0003שלש אומניות עושין מלאכה,\u0004 ומתחילים בה בכל מקום אף \u0003בערבי פסחים עד חצות, ואלו הן: החייטין, והספרים, והכובסין,\u0004 שמלאכתם נחוצה לצורך המועד. \u0003ר' יוסי בר' יהודה אומר: אף רצענין\u0004 (סנדלרים) מותרים במלאכתם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 השאלה\u0005]\u0006 האם מה שהתיר ר' מאיר לגמור בארבעה עשר \u0003לצורך המועד תנן\u0004 \u0005[שנינו],\u0006 \u0003אבל שלא לצורך המועד אפילו מיגמר נמי\u0004 \u0005[לגמור גם כן]\u0006 \u0003לא, או דילמא\u0004 \u0005[שמא]\u0006 \u0003שלא לצורך המועד תנן\u0004 \u0005[שנינו],\u0006 \u0003אבל לצורך\u0004 המועד — \u0003אתחולי מתחלינן\u0004 \u0005[\u0006אפילו \u0005להתחיל מתחילין],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 כך נאמר: \u0003בין לצורך המועד בין שלא לצורך, מיגמר\u0004 \u0005[לגמור] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אתחולי\u0004 \u0005[להתחיל] —\u0006 \u0003לא.\u0004","כדי לפתור את הבעיה מביאים ראיה ממקום אחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003אבל לא יתחיל בתחלה בארבעה עשר אפילו צלצול\u0004 (שרוך) \u0003קטן\u0004 וכן \u0003אפילו שבכה\u0004 (רשת על הראש) \u0003קטנה. מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"אפילו\"\u0004 האמורה כאן? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אפילו הני\u0004 \u0005[אלה]\u0006 ש\u0003לצורך המועד\u0004 הם \u0003מיגמר\u0004 \u0005[לגמור] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אתחולי\u0004 \u0005[להתחיל] —\u0006 \u0003לא, מכלל\u0004 \u0005[מכאן]\u0006 שאם עושה הוא מלאכה \u0003שלא לצורך\u0004 המועד — \u0003מיגמר נמי לא גמרינן\u0004 \u0005[לגמור גם כן איננו גומרים]!\u0006","ודוחים: \u0003לא, לעולם\u0004 הכוונה היא שדבר שהוא \u0003שלא לצורך\u0004 המועד — \u0003מיגמר נמי גמרינן\u0004 \u0005[לגמור גם כן גומרים],\u0006 \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003אפילו — אפילו הני נמי, דזוטרי נינהו\u0004 \u0005[אלו גם כן, שקטנים הם],\u0006 \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 שמפני שהם קטנים \u0003התחלתן זו היא גמר מלאכתם,\u0004 אם כן \u0003נתחיל בהו נמי\u0004 \u0005[שיתחיל בהם גם כן]\u0006 \u0003לכתחילה. קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאסור להתחיל אף במלאכה כזו, ואם כן אין למצוא בברייתא זו פתרון חד משמעי לשאלתנו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לכך ממקום אחר, שנינו: \u0003ר' מאיר אומר: כל מלאכה שהיא לצורך המועד\u0004 —"],["\u0003גומרה בארבעה עשר, אימתי? בזמן שהתחיל בה קודם ארבעה עשר, אבל לא התחיל בה קודם ארבעה עשר לא יתחיל בה בארבעה עשר אפילו\u0004 היה זה \u0003צילצול\u0004 (שרוך) \u0003קטן אפילו שבכה\u0004 (רשת על הראש) \u0003קטנה.\u0004 ונדייק: \u0003לצורך המועד — אין\u0004 \u0005[כן],\u0006 \u0003שלא לצורך המועד — לא.\u0004 את הדיוק הזה דוחים: \u0003הוא הדין\u0004 ש\u0003אפילו שלא לצורך\u0004 המועד \u0003נמי גמרינן\u0004 \u0005[גם כן אנו גומרים],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003אפילו לצורך המועד מיגמר\u0004 \u0005[לגמור] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אתחולי\u0004 \u0005[להתחיל] —\u0006 \u0003לא,\u0004 ומקצת שאלתנו נפתרה, אבל לא כולה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: שנינו, \u0003ר' מאיר אומר: כל מלאכה שהיא לצורך המועד — גומרה בארבעה עשר, ושאינה לצורך המועד — אסור, ועושין מלאכה בערבי פסחים עד חצות במקום שנהגו.\u0004 ונדייק: \u0003מקום שנהגו — אין\u0004 \u0005[כן],\u0006 \u0003לא נהגו — לא! ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כמו שאמרנו: \u0003לצורך המועד — אין\u0004 \u0005[כן],\u0006 \u0003שלא לצורך המועד — לא.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","במשנה שנינו כי \u0003חכמים אומרים שלש אומניות\u0004 יכולות להתחיל וממשיכות לעבוד ביום ארבעה עשר בניסן עד חצות. \u0003תנא\u0004 \u0005[שנו]\u0006 בדרך ביאור: \u0003החייטים\u0004 מותרים לעשות מלאכה בערב פסח, \u0003שכן\u0004 אף \u0003הדיוט\u0004 (מי שאינו אומן) מותר לו להיות \u0003תופר כדרכו בחולו של מועד,\u0004 וכיון שמצאנו היתר מסוים למלאכה זו בחול המועד שאיסורו חמור יותר, למדנו מכאן להקל במלאכה זו בערב הפסח. וכן \u0003הספרים והכובסים, שכן הבא ממדינת הים\u0004 ולא הספיק להסתפר ולכבס קודם החג או \u0003היוצא מבית האסורים מספרים ומכבסים בחולו של מועד. ר' יוסי בר' יהודה אומר: אף הרצענין שכן עולי רגלים מתקנים נעליהם בחולו של מועד,\u0004 ואם כן אף לסנדלרים יש מקצת היתר.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יוסי בר' יהודה\u0005]\u0006 \u0003סבר: למידין תחילת מלאכה מסוף מלאכה\u0004 ואם התירו תיקון מנעלים אף התירו לעשותן לכתחילה בערב הפסח, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: אין למידין תחילת מלאכה מסוף מלאכה\u0004 ותיקון מותר, אך עשיית מנעל מלכתחילה אסורה.","ועוד מדיני ערב הפסח. \u0003מושיבים שובכים לתרנגולים\u0004 ביום \u0003ארבעה עשר\u0004 בניסן. כלומר, מותר להושיב יונים ותרנגולים לדגור על הביצים בערב הפסח, \u0003ותרנגולת שברחה\u0004 מלדגור — \u0003מחזירין אותה למקומה, ואם מתה\u0004 הדוגרת — \u0003מושיבים אחרת תחתיה.\u0004 וכן \u0003גורפין\u0004 את הזבל \u0003מתחת רגלי בהמה\u0004 ביום \u0003ארבעה עשר ובמועד\u0004 (חול המועד) \u0003מסלקין\u0004 אותו \u0003לצדדין.\u0004 וכן \u0003מוליכין כלים\u0004 (בגדים גמורים) \u0003ומביאין מבית האומן\u0004 אחרים לתיקון \u0003אף על פי שאינם לצורך המועד.\u0004","על מה ששנינו כאן לגבי התרנגולת תוהים: \u0003השתא\u0004 \u0005[\u0006הרי \u0005עכשיו]\u0006 למדנו \u0003אותובי מותבינן\u0004 \u0005[להושיב\u0006 את התרנגולת מלכתחילה \u0005מושיבים]\u0006 \u0003אהדורי\u0004 \u0005[להחזיר]\u0006 אותה למקום הדגירה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006 \u0003אמר אביי: סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה \u0005הגענו]\u0006 \u0003לחולו של מועד,\u0004 שמה שהותר להחזיר תרנגולת שברחה הוא אפילו בחולו של מועד שיש הפסד אם לא יעשה כן, וביום ארבעה עשר אף מושיבים אותה מלכתחילה.","\u0003אמר רב הונא: לא שנו\u0004 היתר זה \u0003אלא תוך שלשה\u0004 ימים \u0003למרדה\u0004 לבריחתה מן הדגירה. \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא פרח צימרא מינה\u0004 \u0005[נסתלק החום ממנה]\u0006 והתרנגולת יכולה עדיין לדגור, וכן אם היה הדבר ל\u0003אחר שלשה\u0004 ימים \u0003לישיבתה כבר — דפסדא לה ביעי\u0004 \u0005[שמפסידה את הביצים]\u0006 \u0003לגמרי, אבל לאחר שלשה\u0004 ימים \u0003למרדה דפרח לה צימרא מינה\u0004 \u0005[שנסתלק החום ממנה],\u0006 \u0003ותוך שלשה\u0004 ימים \u0003לישיבתה, דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא פסידי ביעי\u0004 \u0005[נפסדו הביצים]\u0006 \u0003לגמרי\u0004 — \u0003לא מהדרינן\u0004 \u0005[מחזירים אנו]\u0006 \u0003ר' אמי אמר: אפילו תוך שלשה\u0004 ימים \u0003לישיבתה מהדרינן\u0004 \u0005[מחזירים אנו].\u0006","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003מר\u0004 \u0005[חכם זה,\u0006 רב הונא\u0005]\u0006 \u0003סבר: להפסד מרובה\u0004 של הביצים \u0003חששו, להפסד מועט\u0004 שברחה בתוך שלושה ימים ואפשר למצוא בדוחק מי שירצה לקנות ביצים אלה בזול — \u0003לא חששו\u0004 ולא התירו, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אמי\u0005]\u0006 \u0003סבר: להפסד מועט נמי\u0004 \u0005[גם כן]\u0006 \u0003חששו,\u0004 ולכן התירו טירחה זו בחול המועד.","שנינו במשנה: \u0003גורפין\u0004 את הזבל ביום ארבעה עשר \u0003מתחת\u0004 רגלי הבהמה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא בהרחבה: \u0003הזבל שבחצר מסלקין אותו לצדדין, שברפת ושבחצר מוציאים אותו לאשפה\u0004 מחוץ לבית.","ושואלים: \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה],\u0006 \u0003אמרת\u0004 מצד אחד ש\u0003זבל שבחצר מסלקין אותו לצדדין\u0004 ולא לאשפה, \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 \u0003שברפת ושבחצר מוציאים אותו לאשפה! אמר אביי: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 שהתירו להוציאו לאשפה מדובר ביום \u0003ארבעה עשר\u0004 בניסן, \u0003כאן\u0004 הסילוק לצדדים הוא \u0003בחולו של מועד. רבא אמר: הא והא\u0004 \u0005[זו וזו]\u0006 \u0003בחולו של מועד, והכי קאמר\u0004 \u0005[וכך אמר]\u0006 סתם חצר רק מסלקים את הזבל לצדדים, אבל \u0003אם נעשה חצר\u0004 מלוכלכת \u0003כרפת\u0004 — אף \u0003מוציאים אותו לאשפה.\u0004","שנינו במשנה: \u0003מוליכין כלים ומביאין\u0004 אותם \u0003מבית האומן. אמר ר' פפא: בדיק לן\u0004 \u0005[בחן אותנו]\u0006 \u0003רבא\u0004 בשאלה. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מוליכין ומביאין כלים מבית האומן, אף על פי שאינן לצורך המועד. ורמינהו\u0004 \u0005[ומשליכים,\u0006 ומראים סתירה ממקום אחר\u0005],\u0006 ששנינו: \u0003אין מביאין כלים מבית האומן, ואם חושש להן שמא יגנבו — מפנן לחצר אחרת\u0004 של האומן, אבל לא לביתו!","\u0003ומשנינן\u0004 \u0005[ותירצנו]\u0006 לו: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שמביאין כלים מבית האומן — מדובר ביום \u0003ארבעה עשר, כאן\u0004 שאין מביאין — מדובר \u0003בחולו של מועד. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 מדובר אפילו \u0003בחולו של מועד, ולא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן\u0004 שאינו מביא לביתו — מדובר \u0003במאמינו\u0004 (כשמאמין לאומן) שלא יעכב את החפץ בידו ולא ירצה למוסרו, \u0003כאן\u0004 שהתירו להביא לביתו — מדובר \u0003בשאינו מאמינו.\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מביאים כלים מבית האומן כגון הכד מבית הכדר והכוס מבית הזגג, אבל לא צמר מבית הצבע ולא כלים\u0004 אחרים \u0003מבית האומן\u0004 שאינם נחוצים למועד, \u0003ואם אין לו\u0004 לאומן \u0003מה יאכל — נותן לו\u0004 לאומן \u0003שכרו ומניחו אצלו\u0004 (אצל האומן). \u0003ואם אינו מאמינו\u0004 שיתן לו את החפץ אחרי שקיבל שכרו — \u0003מניחן בבית הסמוך לו. ואם חושש שמא יגנבו\u0004 משם — \u0003מביאן בצינעה בתוך ביתו.\u0004","ומעירים: \u0003תרצת\u0004 על ידי כך \u0003מביאין\u0004 אולם \u0003מוליכין\u0004 מביתו לבית האומן \u0003קשיא\u0004 \u0005[קשה],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003אין מביאין וכל שכן\u0004 ש\u0003אין מוליכין\u0004 לתיקון! \u0003אלא מחורתא כדשנינן מעיקרא\u0004 \u0005[מחוור כפי שתירצנו קודם]\u0006 שהברייתא מדברת בחולו של מועד, ומשנתנו בערב פסח.","ועוד בדיני ערב הפסח, ואגב כך במנהגי מקום: \u0003ששה דברים עשו אנשי יריחו\u0004 הישראלים שלא כמנהג כל ישראל, \u0003על שלשה מיחו\u0004 חכמים \u0003בידם ועל שלשה לא מיחו בידם. ואלו הן שלא מיחו בידם: מרכיבין דקלים כל היום\u0004 של ארבעה עשר בניסן, \u0003וכורכין את שמע\u0004 (כפי שיבואר בגמרא), \u0003וקוצרין וגודשין\u0004 את התבואה עוד \u0003לפני\u0004 הקרבת \u0003העומר. ואלו שמיחו בידם:\u0004 היו \u0003מתירין\u0004 להשתמש ב\u0003גמזיות\u0004 (ענפים שצמחו מעצי חרוב ושקמה) \u0003של הקדש,\u0004 שהקדישו את העצים לבדק הבית לאחר שנקצצו ולא היו בהם ענפים ולאחר שהוקדשו הצמיחו ענפים חדשים."],["\u0003ואוכלין מתחת הנשרים\u0004 (דקלים המשירים פירותיהם) \u0003בשבת,\u0004 שהיו אוכלים מן הפירות הנושרים מן העץ בשבת, \u0003ונותנין פאה\u0004 מן ה\u0003ירק\u0004 שפטור מפאה אפילו מדברי חכמים. \u0003ומיחו בידם חכמים\u0004 באלה, שאין עושין כהוגן.","אגב המדובר בדברים שמיחו ושלא מיחו בהם חכמים מביאים ברייתא דומה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006: \u0003ששה דברים עשה חזקיה המלך, על שלשה הודו לו\u0004 חכמים בדורו, \u0003ועל שלשה לא הודו לו: גירר עצמות אביו\u0004 אחז לאחר מותו \u0003על מטה של חבלים,\u0004 ולא קברו בכבוד כשאר מלכים, מפני רשעותו — \u0003והודו לו\u0004 חכמי דורו. \u0003כיתת נחש הנחשת\u0004 שעשה משה לנס, משום שעשאוהו ישראל עבודה זרה — \u0003והודו לו\u0004 חכמי דורו. \u0003גנז ספר רפואות — והודו לו.\u0004","\u0003ועל שלשה\u0004 דברים שעשה \u0003לא הודו לו: קיצץ דלתות של היכל ושגרן למלך אשור\u0004 — \u0003ולא הודו לו,\u0004 שביזה את הקודש ללא צורך. \u0003סתם מי גיחון העליון\u0004 כדי להכניס את המים לעיר במחילה מתחת לקרקע — \u0003ולא הודו לו,\u0004 שהזיק לבני הסביבה והיה לו להישען על ה' (מאירי). \u0003עיבר ניסן בניסן\u0004 כמבואר שביום א' בניסן נמלך והוסיף חודש נוסף, וקבע שאותו יום הוא ל' באדר ראשון (ראה דברי הימים ב, ל) — \u0003ולא הודו לו.\u0004","מעתה באים לפירוש המשנה. שנינו שהיו \u0003מרכיבין דקלים\u0004 ביום ארבעה עשר בניסן \u0003כל היום.\u0004 ושואלים: \u0003היכי עבדי\u0004 \u0005[כיצד עושים]\u0006 הרכבה כזו? \u0003אמר ר' יהודה: מייתי אסא דרא ושיכרא דדפנא וקימחא דשערי דרמי במנא דלא חלפי עליה ארבעין יומין\u0004 \u0005[מביאים הדס לח ושיכר של דפנה, וקמח שעורים המונח בכלי שלא עברו עליו\u0006 משעת טחינתו \u0005ארבעים יום],\u0006 \u0003ומרתחי להו, ושדו להו לדיקלא בליביה\u0004 \u0005[ומרתיחים אותם, ומכניסים אותם לדקל לתוך ליבתו],\u0006 \u0003וכל\u0004 עץ \u0003דקאי\u0004 \u0005[שעומד]\u0006 \u0003בארבע אמות דידיה\u0004 \u0005[שלו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא עבדי ליה הכי\u0004 \u0005[עושים לו\u0006 גם כן \u0005כך],\u0006 \u0003צאוי לאלתר\u0004 \u0005[מתיבש מיד].\u0006 משום שהעץ שטיפלו בו באופן זה גדל במהירות רבה על חשבון האחרים. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אמר: מנחי כופרא דיכרא לנוקבתא\u0004 \u0005[מניחים ענף דקל זכר לנקבה]\u0006 ועל ידי כך דקל הנקיבה עושה פירות.","ועוד שנינו שאנשי יריחו היו \u0003כורכין את שמע.\u0004 ושואלים: \u0003היכי עבדי\u0004 \u0005[כיצד היו עושים],\u0006 כלומר, מהי כריכת שמע זו? \u0003אמר ר' יהודה:\u0004 היו \u0003אומרים \"שמע ישראל ה' אלהינו ה' אחד\", ולא היו מפסיקין\u0004 בין המילים. \u0003רבא אמר: מפסיקין היו, אלא שהיו אומרים \"היום על לבבך\",\u0004 ש\u0003משמע: היום על לבבך, ולא מחר על לבבך.\u0004 ואילו את הפסוק יש לקרוא \"אשר אנכי מצוך היום — על לבבך\". \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד היו כורכין את שמע? אומרים \"שמע ישראל ה' אלהינו ה' אחד\", ולא היו מפסיקין,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: מפסיקין היו, אלא שלא היו אומרים \"ברוך שם כבוד מלכותו לעולם ועד\".\u0004","ושואלים: \u0003ואנן, מאי טעמא אמרינן ליה\u0004 \u0005[ואנו, מה טעם אומרים אנו אותו],\u0006 אף כי לא נאמר בתורה? ומשיבים: \u0003כדרריש\u0004 \u0005[כפי שדרש]\u0006 \u0003ר' שמעון בן לקיש.\u0004","ש\u0003אמר ר' שמעון בן לקיש:\u0004 נאמר \u0003\"ויקרא יעקב אל בניו ויאמר האספו ואגידה לכם\u0004 את אשר יקרא אתכם באחרית הימים\u0003\"\u0004 (בראשית מט, א), \u0003ביקש יעקב לגלות לבניו קץ הימין\u0004 (הימים) מתי תבוא הגאולה השלימה (ראה דניאל יב, יג), \u0003ונסתלקה ממנו שכינה\u0004 ולא יכול היה לנבא. \u0003אמר: שמא חס ושלום יש במטתי\u0004 (בין יוצאי חלצי) \u0003פסול, כ\u0004סבי \u0003אברהם שיצא ממנו ישמעאל, ו\u0004כ\u0003אבי יצחק שיצא ממנו עשו,\u0004 ומשום כך נסתלקה שכינה? \u0003אמרו לו בניו: \"שמע ישראל\u0004 אבינו, \u0003ה' אלהינו ה' אחד\".\u0004 וכך \u0003אמרו: כשם שאין בלבך אלא\u0004 ה' \u0003אחד, כך אין בלבנו אלא אחד. באותה שעה פתח יעקב אבינו ואמר\u0004 ושיבח: \u0003\"ברוך שם כבוד מלכותו לעולם ועד\",\u0004 שכל בניו כשרים.","\u0003אמרי רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003היכי נעביד\u0004 \u0005[איך נעשה]\u0006 בענין זה? \u0003נאמרוהו\u0004 את המשפט הזה, הרי \u0003לא אמרו משה רבינו\u0004 בקריאת שמע. \u0003לא נאמרוהו,\u0004 הלוא \u0003אמרו יעקב. התקינו שיהו אומרים אותו בחשאי\u0004 (בלחישה). \u0003אמר ר' יצחק, אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי: משל לבת מלך שהריחה ציקי קדירה,\u0004 כלומר, מן התבלין המיובש שבשולי הקדירה, והתאוותה לאוכלם. מה תעשה, \u0003אם תאמר\u0004 לעבדיה שיתנו לה — \u0003יש לה גנאי,\u0004 שהוא מאכל בזוי. ואולם אם \u0003לא תאמר — יש לה צער. התחילו עבדיה להביא\u0004 לה \u0003בחשאי.\u0004","וכן עושים בדבר שיש ספק כיצד לנהוג בו, \u0003אמר ר' אבהו: התקינו שיהו אומרים אותו בקול רם, מפני תרעומת המינין.\u0004 שלא יהיו המינים אומרים: דבר שאינו הגון אומרים שם היהודים בחשאי. ומוסיפים: \u0003בנהרדעא, דליכא\u0004 \u0005[שאין]\u0006 בה \u0003מינין, עד השתא אמרי לה\u0004 \u0005[עכשיו אומרים אותה]\u0006 \u0003בחשאי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים בתוספתא\u0006\u0005]\u0006 באותו ענין: \u0003ששה דברים עשו אנשי יריחו, שלשה ברצון חכמים ושלשה שלא ברצון חכמים, ואלו\u0004 שעשו \u0003ברצון חכמים: מרכיבים\u0004 היו \u0003דקלים\u0004 ביום ארבעה עשר בניסן \u0003כל היום, וכורכין את שמע, וקוצרין\u0004 את התבואה \u0003לפני\u0004 הקרבת \u0003העומר. ואלו\u0004 שעשו \u0003שלא ברצון חכמים: גודשין\u0004 את הקציר \u0003לפני העומר, ופורצים פרצות בגנותיהן ובפרדסותיהן להאכיל נשר\u0004 (מה שנשר מן העצים) \u0003לעניים בשני בצורת בשבתות וימים טובים,\u0004 כדי שיוכלו העניים לקחת מן הפירות הנושרים. \u0003ומתירין\u0004 שימוש ב\u0003גמזיות\u0004 (ענפים) \u0003של הקדש של חרוב ושל שקמה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר לו ר' יהודה:\u0004 אין נכון לומר בלשון זו, כי \u0003אם ברצון חכמים היו עושין, יהו\u0004 (יהיו) \u0003כל בני אדם עושין כן\u0004 ולא רק אנשי יריחו. \u0003אלא\u0004 כך יש לומר: \u0003אלו ואלו שלא ברצון חכמים היו עושין,\u0004 אלא \u0003על שלשה\u0004 מהם שהם העלולים לגרום לאיסור חמור \u0003מיחו בידם, ועל שלשה לא מיחו בידם,\u0004 משום שיש בהם צד להקל ולא רצו חכמים למחות, כיון שעברו כבר — עברו.","\u0003ואלו שלא מיחו בידם: מרכיבין דקלים כל היום, וכורכין את שמע, וקוצרין וגודשין לפני העומר. ואלו שמיחו בידם: מתירין גמזיות של הקדש של חרוב ושל שקמה, ופורצין פרצות בגנותיהן ופרדסיהן להאכיל נשר לעניים בשבתות וימים טובים בשני בצורת, נותנין פיאה לירק,\u0004 ועל אלה \u0003מיחו בידם חכמים.\u0004","ושואלים: \u0003ו\u0004כי \u0003סבר ר' יהודה\u0004 כי \u0003קצירה\u0004 זו שקצרו אנשי יריחו \u0003שלא ברצון חכמים היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אנשי יריחו\u0004 היו \u0003קוצרין לפני העומר ברצון חכמים, וגודשין לפני העומר שלא ברצון חכמים, ולא מיחו בידם חכמים.\u0004"],["\u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר,\u0004 משתמש בענין זה בביטויים \u0003\"מיחו, ולא מיחו\" — ר' יהודה\u0004 הוא, שהרי ר' מאיר אומר \"ברצון, ושלא ברצון\". \u0003וקתני\u0004 \u0005[ושנינו]\u0006 \u0003קוצרין ברצון חכמים!\u0004 ודוחים: \u0003וליטעמיך, הני\u0004 \u0005[ולשיטתך, אלה]\u0006 שלא מיחו \u0003ארבעה הוה\u0004 \u0005[הם]:\u0006 מרכיבים, כורכים, קוצרים וגודשים, ולא שלושה כאמור, \u0003אלא: סמי מיכן\u0004 \u0005[מחוק מכאן]\u0006 \u0003קצירה,\u0004 שקצירה כלל אינה נכנסת בתוך רשימת דברים אלה, וממילא אין ללמוד ממנה לשאר דברים שמיחו חכמים בידי אנשי יריחו.","שנינו במשנתנו ובברייתא: \u0003\"ומתירין גמזיות\u0004 (ענפים רכים) \u0003של הקדש של חרוב ושל שקמה\".\u0004 ומסבירים מה טעמם, \u0003אמרו: אבותינו לא הקדישו אלא קורות\u0004 (גזע העצים) בלבד, \u0003ואנו נתיר גמזיות של הקדש של\u0004 עצי \u0003חרוב ושל שקמה\u0004 שמתוך ענפיהם הן צמחו. \u0003ו\u0004מסבירים כי \u0003בגידולין הבאים לאחר מכאן עסקינן\u0004 \u0005[עוסקים אנו]\u0006 פה, \u0003וסברי לה\u0004 \u0005[וסוברים הם]\u0006 שזה \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר: אין מעילה בגידולין.\u0004 שהמקדיש דבר, לא חלה הקדושה על מה שיגדל או יוולד ממנו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סוברים]:\u0006 \u0003נהי\u0004 \u0005[אם כי]\u0006 ש\u0003מעילה ליכא\u0004 \u0005[אין\u0006 כאן\u0005],\u0006 אבל \u0003איסורא מיהא איכא\u0004 \u0005[איסור מכל מקום יש\u0006 כאן\u0005].\u0006","שנינו בברייתא שהיו אנשי יריחו \u0003פורצין פרצות,\u0004 שיוכלו עניים לקחת מן הפירות הנושרים בשבתות וימים טובים בשני בצורת. \u0003אמר עולא אמר ר' שמעון בן לקיש: מחלוקת\u0004 זו שבין אנשי יריחו וחכמים היא \u0003בשל מכבדות\u0004 (כפות תמרים שבראש הדקל המשמשות ככלי קיבול לתמרים אלו), כלומר, שנשרו ואינם מחוברים עוד לעץ, אבל נשארו בתוך המכבדות, \u0003דרבנן סברי\u0004 \u0005[שחכמים סוברים]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003שמא יעלה\u0004 על הדקל \u0003ויתלוש\u0004 מאלה שהן מחוברות עוד, \u0003ואנשי יריחו סברי\u0004 \u0005[סוברים]:\u0006 \u0003לא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003שמא יעלה ויתלוש. אבל בשל בין הכיפין\u0004 שנפלו בין ענפי הדקל למטה ששוב אין בכך חשש תלישה — \u0003דברי הכל מותר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003מוקצות נינהו\u0004 \u0005[הן]\u0006 שאינן מוכנות מבעוד יום למאכל, שלא נשרו לפני השבת, ודבר שאסור בין השמשות, נאסר לכל השבת אף שהשתנה מצבו בשבת. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הואיל דחזי\u0004 \u0005[שראוי]\u0006 \u0003לעורבין,\u0004 שהעורבים שמגדלים בבית יכולים לעוף ללקט את התמרים הללו אפילו כשהן עדיין מחוברות, ונמצא שהתמרים מוכנים עבורם. הרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 יודעים אנו כי \u0003מוכן לאדם לא הוי\u0004 \u0005[אינו]\u0006 נחשב \u0003מוכן לכלבים. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה אומר: אם לא היתה\u0004 מתה הבהמה ונעשית \u0003נבילה מערב שבת — אסורה\u0004 להיאכל בשבת לכלבים \u0003לפי שאינה מן המוכן,\u0004 הרי בהמה זו בעוד שהיא חיה היתה מוכנה לאכילת אדם, בכל זאת אומרים כי הכנה זו אינה מספקת כדי להחשיבה מוכנה גם לאכילת הכלבים לכשתתנבל. \u0003מוכן לעורבים הוי\u0004 \u0005[הינו]\u0006 \u0003מוכן לאדם?!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הוא, \u0003מוכן לאדם — אכן לא הוי\u0004 \u0005[אינו]\u0006 \u0003מוכן לכלבים,\u0004 שכן \u0003כל מידי דחזי לאיניש\u0004 \u0005[דבר שראוי\u0006 לו \u0005לאדם]\u0006 לשימושו, הוא \u0003לא מקצה ליה מדעתיה\u0004 \u0005[אותו מדעתו]\u0006 ונשאר רק בגדר זה, ואילו \u0003מוכן לעורבים — הוי\u0004 \u0005[הריהו]\u0006 \u0003מוכן לאדם,\u0004 ש\u0003כל מידי דחזי לאיניש\u0004 \u0005[דבר שראוי\u0006 לו \u0005לאדם],\u0006 \u0003דעתיה עלויה\u0004 \u0005[דעתו עליו],\u0006 וגם אם מוכן מתחילה לעורבים מוכן אדם לאכול ממה שאפשר לו לאכול. עד כאן דברי עולא בשם ר' שמעון בן לקיש.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 גירסה אחרת בשם \u0003ר' שמעון בן לקיש: מחלוקת בשל בין כיפין, דרבנן סברי\u0004 \u0005[שחכמים סוברים]\u0006 כי \u0003מוכן לעורבים לא הוי\u0004 \u0005[אינו]\u0006 \u0003מוכן לאדם, ואנשי יריחו סברי\u0004 \u0005[סוברים]\u0006 כי \u0003מוכן לעורבים הוי\u0004 \u0005[הריהו]\u0006 \u0003מוכן לאדם, אבל בשל מכבדות — דברי הכל אסור, גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003שמא יעלה ויתלוש.\u0004","שנינו במשנה כי אנשי יריחו היו \u0003נותנין פיאה לירק.\u0004 ושואלים: \u0003ו\u0004כי \u0003לית להו\u0004 \u0005[ואין להם]\u0006 \u0003לאנשי יריחו,\u0004 אין הם מקבלים \u0003הא דתנן\u0004 \u0005[\u0006דבר \u0005זה ששנינו\u0006 במשנה\u0005],\u0006 \u0003כלל אמרו בפיאה: כל שהוא אוכל\u0004 (דבר מאכל), \u0003ונשמר\u0004 בידי הבריות, \u0003וגידולו מן הארץ, ולקיטתו\u0004 בשעת הבשלתו \u0003כאחת\u0004 (בפעם אחת), \u0003ומכניסו לקיום\u0004 שמאחסנו להשתמש בו במשך תקופה ארוכה — \u0003חייב בפיאה.\u0004","ומפרטים: \u0003\"כל שהוא אוכל\" — פרט לספיחי\u0004 הצמחים \u0003סטיס וקוצה\u0004 הנועדים בעיקר לייצור צבע ולא לאכילה. \u0003\"ונשמר\" — פרט ל\u0004צמח \u0003הפקר. \"וגידולו מן הארץ\" — פרט לכמהין ופטריות\u0004 שאינם יונקים מן האדמה כשאר צמחים אלא מן הרקבובית. \u0003ולקיטתן כאחת — פרט לתאנים\u0004 שאינן מתבשלות בבת אחת, ונלקטות מעט מעט בכל פעם. \u0003\"ומכניסו לקיום\" — פרט לירק\u0004 שאי אפשר להשאירו זמן מרובה וצריכים לאכול אותו מיד.","\u0003אמר רב יהודה אמר רב: הכא\u0004 \u0005[כאן]\u0006 \u0003בראשי\u0004 (פקעות) של \u0003לפתות עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שאותן אפשר להשהות זמן ממושך, ובענין \u0003מכניסו לקיום על ידי דבר אחר קמיפלגי\u0004 \u0005[נחלקו],\u0006 שהרי את הלפת אין שומרים כמות שהיא אלא כובשים אותה בחומץ וכיוצא בו (ר\"ח). \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 אנשי יריחו, \u0005סברו]:\u0006 \u0003מכניסו לקיום על ידי דבר אחר\u0004 (חומץ וכדומה) — \u0003שמיה\u0004 \u0005[שמו,\u0006 נקרא\u0005]\u0006 \u0003קיום, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סברו]:\u0006 \u0003לא\u0004 נקרא \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003קיום,\u0004 ולכן אין להפריש ממנו פיאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו נותנים פיאה ללפת ולכרוב, ר' יוסי אומר: אף לקפלוט\u0004 (כרתי, מין בצל). \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003היו נותנין פיאה ללפת ולקפלוט, ר' שמעון אומר: אף לכרוב\u0004 היו נותנים פאה."],["\u0003נימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003תלתא תנאי הוו\u0004 \u0005[שלושה תנאים הם]\u0006 שנחלקו בענין, שתי הדעות הסתמיות המנוגדות ודעתם השווה של ר' יוסי ור' שמעון? ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003תרי תנאי הוו\u0004 \u0005[שני תנאים הם]\u0006 בלבד, \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 שלפני \u0003ר' שמעון — היינו\u0004 \u0005[זהו]\u0006 \u0003ר' יוסי, ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 לפני \u0003ר' יוסי היינו\u0004 \u0005[זהו]\u0006 \u0003ר' שמעון. ומאי\u0004 \u0005[ומה\u0006 הוא\u0005]\u0006 לשון \u0003\"אף\"\u0004 שאמרו שניהם? שלפי שיטה זו לכאורה מסכימים כולם לדבר אחד, יש לומר כי כוונתם \u0003אקמייתא\u0004 \u0005[על הראשונה]\u0006 כלומר, שלא חלקו על הפרט השני שהוזכר והוסיפו רק על הראשון.","בענין פיאה מירק מביאים מעשה הנזכר בתוספתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בן\u0004 לאיש הקרוי \u0003בוהיין נתן\u0004 לעניים \u0003פיאה לירק, ובא אביו\u0004 בוהיין \u0003ומצאן לעניים שהיו טעונים ירק ועומדין על פתח הגינה\u0004 לצאת. \u0003אמר להם: בני, השליכו מעליכם\u0004 את הירקות שלקטתם \u0003ואני נותן לכם כפליים\u0004 מהם \u0003במעושר\u0004 כלומר, חולין מעושרים, ולא יפסידו, כי כשם שפיאה אין צריך לעשר, כך לא יצטרכו להפריש עוד ממה שיתן להם. \u0003לא מפני שעיני צרה\u0004 במה שקבלתם, \u0003אלא מפני שאמרו חכמים: אין נותנים פיאה לירק\u0004 משום שמפקיעם ממעשר.","ושואלים: \u0003למה ליה למימרא להו\u0004 \u0005[לו לומר להם]\u0006 \u0003\"לא מפני שעיני צרה\"?\u0004 דיו להוכיח זאת במה שאמר להם שיתן להם מן המעושר, ומשיבים שאמר זאת \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לימרו: דחויי קא מדחי לן\u0004 \u0005[יאמרו: לדחות אותנו הוא דוחה],\u0006 שקודם כל נטל מהם מה שלקחו, ולאחר מכן לא יקיים הבטחתו כלל.","אגב המעשה באנשי יריחו שהיו בעלי זרוע גוזלים את עציהם \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו מניחין\u0004 הכהנים \u0003עורות\u0004 קדשי \u0003קדשים\u0004 שנפשטו ושייכים לכהנים \u0003בלשכת בית הפרוה, לערב היו מחלקין אותן לאנשי בית אב\u0004 אותה משפחה של כהנים ששימשו באותו יום. \u0003והיו בעלי זרועות\u0004 (אלימים) שביניהם \u0003נוטלין אותן בזרוע\u0004 ואינם מחלקים בצדק. \u0003התקינו שהיו מחלקין אותן מערב שבת לערב שבת,\u0004 ומדוע עשו זאת? כי \u0003אתיין כולהו\u0004 \u0005[שבאות כל]\u0006 ה\u0003משמרות,\u0004 שכל בתי אב מן המשמר הנכנס והיוצא מצויים אז יחד \u0003ושקלן בהדדי\u0004 \u0005[ולוקחים יחד],\u0006 ואז לא יוכלו בעלי זרועות לקחת יותר מחלקם.","\u0003ועדיין היו גדולי כהונה\u0004 (החשובים והמיוחסים בין הכהנים) \u0003נוטלין אותן בזרוע,\u0004 ואלה, מפני חשיבותם אף המשמר כולו לא יכול להתנגד להם. כיון שראו שאין סדר בדברים, \u0003עמדו בעלים\u0004 של הקרבנות (מאירי) \u0003והקדישום לשמים,\u0004 שהתנו בשעת הפרשת הקרבן שעורו יהא הקדש ולא יהא לכהנים.","\u0003אמרו: לא היו ימים מועטים עד\u0004 שבמחיריהם של עורות אלה \u0003חיפו את ההיכל בטבלאות של זהב, שהם\u0004 אורך \u0003אמה על אמה כעובי דינר זהב,\u0004 ובזמן העליה ל\u0003רגל היו מקפלין אותן\u0004 ומסירים ממקומם \u0003ומניחין אותן על גב מעלה\u0004 (מדרגה) \u0003בהר הבית, כדי שיהו עולי רגלים רואין שמלאכתם\u0004 של הטבלאות \u0003נאה ואין בה דלם\u0004 (פגם, דופי), ובסוף הרגל היו מחזירים אותן להיכל.","ועוד \u0003תנא\u0004 \u0005[שנינו]\u0006 בדומה לזה, \u0003אבא שאול אומר: קורות\u0004 (גזעים) \u0003של שקמה היו ביריחו, והיו בעלי זרועות נוטלין אותן בזרוע\u0004 מידי בעליהן, \u0003עמדו בעלים והקדישום לשמים.\u0004 והן הקורות שביחס לגידוליהן עשו אנשי יריחו שלא כדעת חכמים.","על אותם גדולי כהונה שהוזכרו קודם \u0003ועל כיוצא בהם אמר אבא שאול בן בטנית משום\u0004 (משם) \u0003אבא יוסף בן חנין: אוי לי מבית בייתוס\u0004 (משפחת כהנים היתה) \u0003אוי לי מאלתן\u0004 (מקלם), \u0003אוי לי מבית חנין אוי לי מלחישתן\u0004 שהיו מוציאים לעז ומלשינים, \u0003אוי לי מבית קתרוס אוי לי מקולמוסן\u0004 שהם כותבים דברי שקר, \u0003אוי לי\u0004 מעבדי \u0003בית ישמעאל בן פיאכי אוי לי מאגרופן.\u0004 ותוקפם של בתים אלו נובע משום \u0003שהם\u0004 (ראשי המשפחה) \u0003כהנים גדולים ובניהם גיזברין\u0004 של המקדש \u0003וחתניהם אמרכלין\u0004 (ממונים כלליים), ולכן \u0003עבדיהם חובטין את העם במקלות\u0004 ועושים דברים שלא כדין.","אגב גנות זו שנאמרה בכמה גדולי כהונה מסופר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבע צווחות צוחה עזרה\u0004 הנמצאים בעזרה הסכימו כולם על דבר זה (פרדס רמונים). \u0003ראשונה\u0004 בהן היתה: \u0003צאו מכאן בני עלי שטימאו היכל ה'\u0004 (כאמור בספר שמואל א' ב, כב) ועברה הכהונה לבית צדוק. \u0003ועוד צווחה: צא מיכן\u0004 \u0005[מכאן]\u0006 \u0003יששכר איש כפר ברקאי שמכבד את עצמו ומחלל קדשי שמים.\u0004 ומסבירים שמתוך איסטניסות יתירה וחוסר יחס לעבודת הקודש היה \u0003כורך\u0004 את ידיו \u0003בשיראי\u0004 \u0005[במשי]\u0006 \u0003ועביד\u0004 \u0005[ועושה]\u0006 \u0003עבודה,\u0004 שפוסל את העבודה במקדש משום חציצה בינו ובין כלי הקודש, ואף בזיון יש בכך שמראה שאין כדאי ללכלך ידיו באלה.","\u0003ועוד צווחה העזרה: שאו שערים ראשיכם ויכנס ישמעאל בן פיאכי תלמידו של פנחס\u0004 בן אלעזר הכהן, שהיה צדיק, \u0003וישמש בכהונה גדולה\u0004 אף שהיו אנשי ביתו אלימים. \u0003ועוד צווחה העזרה: שאו שערים ראשיכם ויכנס יוחנן בן נרבאי תלמידו של פנקאי\u0004 (פנחס) \u0003וימלא כריסו מקדשי שמים\u0004 שכן ראוי הוא לאכול הקרבנות.","\u0003אמרו עליו על יוחנן בן נרבאי שהיה אוכל\u0004 הוא והסמוכים על שולחנו, שהיו רבים, \u0003שלש מאות עגלים ושותה שלש מאות גרבי יין ואוכל ארבעים סאה גוזלות\u0004 יונים \u0003בקינוח סעודה. אמרו: כל ימיו של יוחנן בן נרבאי לא נמצא נותר במקדש\u0004 שהוא היה דואג שיאכלוהו. ושואלים: \u0003מאי סלקא ביה\u0004 \u0005[מה עלתה לו]\u0006 בסופו של דבר \u0003ביששכר איש כפר ברקאי? אמרי\u0004 \u0005[אמרו]\u0006 כך היה מעשה: \u0003מלכא ומלכתא הוו יתבי\u0004 \u0005[המלך והמלכה היו יושבים]\u0006 ומשוחחים. \u0003מלכא אמר: גדיא יאי, ומלכתא אמרה: אימרא יאי\u0004 \u0005[המלך אמר: הגדי טוב\u0006 יותר לאכילה, \u0005והמלכה אמרה: הכבש טוב\u0006 יותר\u0005].\u0006 \u0003אמרו: מאן מוכח\u0004 \u0005[מי יוכיח]\u0006 כדברי מי משניהם הצדק\u0005?\u0006 \u0003כהן גדול, דקא מסיק\u0004 \u0005[שהוא מעלה]\u0006 \u0003קרבנות כל יומא\u0004 \u0005[יום]\u0006 וטועם מבשרם, שהכהן הגדול רשאי לקחת לו חלק מכל קרבן שנאכל המובא למקדש, וודאי יודע הוא בטעמם. \u0003אתא איהו\u0004 \u0005[בא הוא]\u0006 יששכר איש כפר ברקאי, וכאשר שאלו אותו שאלה זו"],["\u0003אחוי בידיה\u0004 \u0005[הראה בידו]\u0006 בתנועה של זלזול: \u0003אי גדיא יאי, יסק לתמידא\u0004 \u0005[אם הגדי משובח, יעלה ל\u0006קרבן ה\u0005תמיד]\u0006 וכיון שקרבן התמיד הוא מן הכבשים הרי זו ראיה שהטלה טוב מן הגדי. \u0003אמר מלכא\u0004 \u0005[המלך]:\u0006 \u0003הואיל ולא הוי ליה אימתא דמלכותא\u0004 \u0005[היתה לו אימת המלכות]\u0006 ולא רק שלא אמר כמותי אלא גם דיבר בזלזול, \u0003ניפסקו לימיניה\u0004 \u0005[שיחתכו את\u0006 יד \u0005ימינו],\u0006 \u0003יהב שוחד ופסקיה לשמאליה\u0004 \u0005[נתן שוחד וחתך\u0006 הממונה \u0005את\u0006 יד \u0005שמאלו].\u0006 \u0003שמע מלכא ופסקיה לימיניה\u0004 \u0005[שמע המלך\u0006 שהערים עליו יששכר וציווה \u0005שיחתכו את\u0006 יד \u0005ימינו]\u0006 ונמצא שנקטעו שתי ידיו. \u0003אמר רב יוסף: בריך רחמנא דאשקליה\u0004 \u0005[ברוך ה' שגבה גמולו]\u0006 של \u0003יששכר איש כפר ברקאי למיטרפסיה מיניה בהאי עלמא\u0004 \u0005[ממנו בעולם הזה]\u0006 ולא המתין לו שיענש קשה יותר לעולם הבא. שעונשו היה מידה כנגד מידה: כיון שלא רצה ללכלך ידיו בדם הקודשים ונשמר ממנו שמירה יתירה — נקטעו שתי ידים אלה.","\u0003אמר רב אשי: יששכר איש כפר ברקאי לא תנא מתניתין\u0004 \u0005[שנה\u0006 את \u0005המשנה]\u0006 כלומר, בור היה, שלא ידע ענין פשוט המבואר במפורש במשנה. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר: כבשים קודמים לעזים בכל מקום\u0004 בלשון הכתובים, \u0003יכול מפני שמובחרין במינן\u0004 הם מוקדמים — \u0003תלמוד לומר: \"ואם כבש יביא קרבנו\"\u0004 (ויקרא ד, לב), ופרשה זו המבארת הבאת קרבן חטאת מן הכבשים נאמרה לאחר הפרשה המדברת בקרבן זה הבא מן העזים. משמע שאין חשיבות לסדר, כיון שרואים שלא תמיד הוא נשמר בכתובים \u0003מלמד\u0004 שינוי זה \u0003ששניהן שקולין כאחד. רבינא אמר: אפילו מקרא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קרא\u0004 יששכר כראוי, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואם כבש\"\u0004 (ויקרא ד, לב) \u0003\"ואם עז\"\u0004 (ויקרא ג, יב), שנאמר בלשון ברורה ללמד: \u0003אי בעי\u0004 \u0005[אם ירצה]\u0006 \u0003כבש — לייתיה\u0004 \u0005[יביא],\u0006 \u0003אי בעו\u0004 \u0005[אם ירצה]\u0006 \u0003עז\u0004 — \u0003לייתיה\u0004 \u0005[יביא]\u0006. משמע שאין אחד מהם טוב מן השני.",""],["קרבן ה\u0003תמיד\u0004 של בין הערביים \u0003נשחט בשמונה\u0004 שעות \u0003ומחצה\u0004 שהם שעתיים וחצי לאחר חצות היום, \u0003וקרב\u0004 כלומר, גמר הקרבתו על המזבח \u0003בתשעה ומחצה.\u0004 ו\u0003בערבי פסחים\u0004 שיש צורך להקריב את קרבן הפסח לאחר התמיד מקדימים את הקרבת התמיד; \u0003נשחט בשבע ומחצה וקרב בשמונה ומחצה בין\u0004 שהיה הדבר \u0003בחול בין בשבת.\u0004 אם \u0003חל ערב פסח להיות בערב שבת\u0004 שצריך להקדים עוד יותר בהקרבת הפסח, כדי שאפשר יהיה לצלותו לפני כניסת השבת \u0003נשחט\u0004 התמיד \u0003בשש ומחצה וקרב בשבע ומחצה,\u0004 וקרבן \u0003הפסח\u0004 קרב \u0003אחריו.\u0004","שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 כלומר, מנין יודעים אנו שזמן הקרבת תמיד של בין הערבים הוא בשמונה ומחצה עד תשע ומחצה?","\u0003אמר ר' יהושע בן לוי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בקרבן התמיד \u0003\"את הכבש אחד תעשה בבקר ואת הכבש השני תעשה בין הערבים\"\u0004 (במדבר כח, ד), והוא מבין כך: ששעת בין הערביים היא השעה של אמצע הערב, והערב מתחיל מזמן שנוטה היום לערוב אחרי הצהריים והלאה, \u0003חלקהו\u0004 את הזמן הזה \u0003לבין שני ערבים.\u0004 כיצד? \u0003שתי שעות ומחצה לכאן שתי שעות ומחצה לכאן ושעה אחת\u0004 באמצע \u0003לעשייתו\u0004 של הקרבן, הרי שזמן התמיד צריך להיות בין שעתים ומחצה לאחר חצות היום ושעתים ומחצה לפני השקיעה, והוא הזמן הקבוע לכך במשנה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על הסבר זה \u0003רבא:\u0004 שנינו כי \u0003בערבי פסחים נשחט בשבע ומחצה וקרב בשמונה ומחצה בין בחול בין בשבת! ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי שחיטת התמיד \u0003בשמונה ומחצה דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, \u0003היכי מקדמינן ליה\u0004 \u0005[כיצד מקדימים אנו אותו]\u0006 משום שיקול אחר של נוחיות?","\u0003אלא\u0004 יש לדחות פירוש זה. ו\u0003אמר רבא: מצותו\u0004 של ה\u0003תמיד משינטו צללי ערב,\u0004 משמע מעט אחרי חצות היום, כאשר רואים שנוטה היום לערוב, ומן התורה אין לו קביעות זמן מוגדרת יותר. \u0003מאי טעמא\u0004 \u0005[מה טעמו של דבר]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בין הערבים\"\u0004 ואנו מבינים זאת \u0003מעידנא דמתחיל שמשא למערב\u0004 \u0005[מהזמן שמתחילה השמש לנטות למערב],\u0006","\u0003הלכך\u0004 (על כן) \u0003בשאר ימות השנה דאיכא\u0004 \u0005[שיש]\u0006 \u0003נדרים ונדבות\u0004 להקריבם באותו יום \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 בקרבן התמיד \u0003\"\u0004והאש על המזבח תוקד בו לא תכבה וביער עליה הכהן עצים בבקר בבקר, וערך עליה העלה והקטיר \u0003עליה חלבי השלמים\"\u0004 (ויקרא ו, ה),","\u0003ואמר מר\u0004 \u0005[החכם]\u0006 (להלן פסחים נט, ב) בביאור המקובל על כך \u0003\"עליה חלבי השלמים\"\u0004 יש לדורשו: \u0003עליה\u0004 כלומר, אחרי עולה זו של קרבן תמיד של שחר \u0003השלם כל הקרבנות כולם,\u0004 ללמדנו שכל הקרבנות צריכים להקריבם לאחר תמיד של שחר ולא לאחר תמיד של בין הערביים, וכיון שצריך להקריב קרבנות רבים עד להקרבת התמיד של בין הערביים \u0003מאחרינן ליה\u0004 \u0005[מאחרים אנו אותו]\u0006 \u0003תרתי שעי\u0004 \u0005[שתי שעות],\u0006 ואין מקריבים אותו מיד משמותר להקריבו בשש ומחצה, \u0003ועבדינן ליה\u0004 \u0005[ועושים אנו אותו]\u0006 \u0003בשמונה ומחצה,\u0004","ואילו \u0003בערבי פסחים דאיכא\u0004 \u0005[שיש]\u0006 \u0003פסח אחריו,\u0004 ויש צורך להשאיר זמן לשחיטת הפסחים המרובים \u0003קדמינן ליה\u0004 \u0005[מקדימים אנו אותו]\u0006 \u0003שעה אחת ועבדינן ליה\u0004 \u0005[ועושים אנו אותו]\u0006 \u0003בשבע ומחצה. חל ערב פסח להיות ערב שבת דאיכא נמי\u0004 \u0005[שיש גם כן]\u0006 \u0003צלייתו\u0004 של הפסח \u0003דלא דחי\u0004 \u0005[שאינה דוחה]\u0006 \u0003שבת, מוקמינן ליה אדיניה\u0004 \u0005[מעמידים אנו אותו על דינו]\u0006 היסודי, ומקריבים אותו \u0003בשש ומחצה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כסידורו\u0004 של קרבן התמיד ביום \u0003חול כך סידורו בשבת,\u0004 אלו \u0003דברי ר' ישמעאל, ור' עקיבא אומר: כסידורו בערב פסח.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 כלומר, כיצד יש להבין את הלשון הזו? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר,\u0006 נתכוון\u0005]:\u0006 \u0003כסידורו\u0004 של התמיד \u0003בחול בערב הפסח\u0004 שזמן הקרבתו בשבע וחצי \u0003כך סידורו בשבת\u0004 כשחל \u0003בערב הפסח\u0004 שאף זמן הקרבתו בשבע וחצי ואין משנים בין שבת לחול, אלו \u0003דברי ר' ישמעאל.\u0004 ואילו \u0003ר' עקיבא אומר: כסידורו\u0004 של התמיד \u0003בערב הפסח שחל להיות בערב שבת\u0004 שמקריבים אותו בשעה שש ומחצה \u0003כך סידורו בשבת\u0004 שאף אז מקריבים את התמיד בשש ומחצה. ולפיכך \u0003מתניתין דקתני\u0004 \u0005[משנתינו ששנינו\u0006 בה\u0005]\u0006 שבערב פסח נשחט בשבע ומחצה, וקרב בשמונה ומחצה \u0003בין בחול בין בשבת\u0004 — כשיטת \u0003ר' ישמעאל היא\u0004 שלדעתו אין משנים.","ושואלים: לפי הסבר זה \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: בשאלה אם הקרבת קרבן \u0003מוספין קודמין\u0004 להקרבת \u0003בזיכין קמיפלגי\u0004 \u0005[נחלקו],\u0006 כי בשבת יש נוסף לעבודה הרגילה בכל יום גם הקרבת קרבנות המוספים של שבת, וגם הקרבת הבזיכים שהם הכלים שמכניסים בהם קטורת והם מצויים כל השבוע על גבי לחם הפנים ואותם מקטירים בכל שבת. ובכך נחלקו, \u0003ר' ישמעאל סבר\u0004 כי \u0003מוספין קודמין לבזיכין\u0004 ולכן \u0003עבד להו\u0004 \u0005[עושה אותם]\u0006 את ה\u0003מוספים\u0004 בשעה \u0003שש,\u0004 כי זמן הקרבת המוספים הוא לכל הדעות בשעה שש. \u0003ובזיכין\u0004 עושה \u0003בשבע, ועביד ליה\u0004 \u0005[ועושה אותו]\u0006 את קרבן ה\u0003תמיד בשבע ומחצה.\u0004 ואילו \u0003ר' עקיבא סבר\u0004 כי \u0003בזיכין קודמין למוספין,\u0004 ולכן הקטרת ה\u0003בזיכין\u0004 היא \u0003בחמש, מוספין בשש ועביד ליה\u0004 \u0005[ועושה אותו]\u0006 את ה\u0003תמיד בשש ומחצה.\u0004","שיטת הסבר זו \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא: מידי\u0004 \u0005[וכי]\u0006 \u0003ר' עקיבא \"כסידרו בערב הפסח שחל להיות בערב שבת\" קתני\u0004 \u0005[שנה]?!\u0006 לא בלשון זו שנה, אלא: \u0003כסידרו בערב הפסח סתמא\u0004 \u0005[סתם]\u0006 \u0003קתני\u0004 \u0005[שנה],\u0006 ואם כן אין ההסבר מכוון לדברי ר' עקיבא. \u0003אלא\u0004 יש לדחות פירוש זה, ו\u0003אמר רבא הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך היתה כוונת הדברים: \u0003כסידרו\u0004 של קרבן התמיד \u0003בחול דעלמא\u0004 \u0005[\u0006ביום \u0005חול סתם]\u0006 \u0003כך סידרו בשבת בערב הפסח.\u0004 כלומר, מקריבים את קרבן התמיד בשעה שמונה ומחצה, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: כסידרו בערב הפסח\u0004 ביום חול כך סדרו בערב הפסח שחל להיות בשבת שהוא בשבע ומחצה, ולפיכך \u0003מתניתין דקתני\u0004 \u0005[משנתינו ששנינו\u0006 בה\u0005]\u0006 שזמן ההקרבה \u0003בין בחול\u0004 ו\u0003בין בשבת\u0004 שווה, על פי שיטת \u0003ר' עקיבא היא.\u0004","ושואלים: לפי הסבר זה \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003במכמר בשרא\u0004 \u0005[בחימום\u0006 ובקלקול \u0005הבשר]\u0006 \u0003קמיפלגי\u0004 \u0005[נחלקו],\u0006 כי \u0003ר' ישמעאל סבר: חיישינן למכמר בשרא\u0004 \u0005[חוששים אנו לחימום\u0006 וקלקול \u0005הבשר]\u0006 שאם יקדימו את הקרבת התמיד בשבת יקדימו אף את הקרבת קרבן הפסח, וכיון שאסור לצלותו עד לאחר צאת השבת, בינתיים הקרבן מוטל ושמא יתחמם הבשר ויתקלקל. \u0003ור' עקיבא סבר: לא חיישינן למכמר בשרא\u0004 \u0005[אין אנו חוששים לחימום\u0006 וקלקול \u0005הבשר]\u0006 ולכן אפשר להקדים ולשחוט את הפסח אף כשחל ערב פסח בשבת."],["ומקשים: \u0003אי לא חיישינן\u0004 \u0005[אם איננו חוששים]\u0006 לדעת ר' עקיבא לקלקול הבשר, אם כן \u0003ניעבדיה\u0004 \u0005[שיעשו אותו]\u0006 את קרבן התמיד \u0003בשש ומחצה,\u0004 שהרי הפסחים מרובים ונדרים ונדבות אין, ומדוע יאחרוהו? ומשיבים: \u0003קא סבר\u0004 \u0005[סבר]\u0006 ר' עקיבא: \u0003מוספין קודמין לבזיכין\u0004 ומשום כך \u0003עביד להו\u0004 \u0005[עושה אותם]\u0006 \u0003למוספין בשש, ובזיכין\u0004 עושה \u0003בשבע,\u0004 וממילא \u0003עביד ליה\u0004 \u0005[עושה אותו]\u0006 את ה\u0003תמיד בשבע ומחצה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסברה זו \u0003רבה בר עולא: מידי\u0004 \u0005[וכי]\u0006 \u0003\"כסידרו בחול כך סידרו בשבת בערב הפסח, דברי ר' ישמעאל\" קתני\u0004 \u0005[שנויה]?!\u0006 הלוא בברייתא ההיא \u0003\"כך סידרו בשבת\" סתמא קתני\u0004 \u0005[סתם שנה]?\u0006","ואף הסבר זה אינו ההסבר המדויק על פי סגנון הברייתא \u0003אלא אמר רבה בר עולא, הכי קתני\u0004 \u0005[כך שנויה]\u0006 וכך יש להבין שמחלוקת זו אינה בדבר ערב הפסח, אלא בשאר ימות השנה. ו\u0003כסידרו בחול דעלמא\u0004 \u0005[סתם]\u0006 \u0003כך סידרו בשבת דעלמא\u0004 \u0005[סתם]\u0006 בשמונה וחצי \u0003דברי ר' ישמעאל,\u0004 שלדעתו אין משנים בין שבת לחול כלל.","ו\u0003ר' עקיבא אומר: כסידרו בערב הפסח דעלמא\u0004 \u0005[סתם]\u0006 בשבע ומחצה \u0003כך סידרו בשבת דעלמא,\u0004 שכיון שאין מקריבים קרבנות נדבה בשבת אפשר להקדים את הקרבת התמיד בשבת. \u0003ומתניתין דקתני\u0004 \u0005[ומשנתינו ששנינו]\u0006 ששעת הקרבת התמיד בערב פסח קבועה \u0003בין בחול בין בשבת\u0004 אפשר לומר כי זו כ\u0003דברי הכל היא\u0004 בין לר' עקיבא בין לר' ישמעאל.","ולשיטה זו \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003בגזרת נדבות ונדרים קמיפלגי\u0004 \u0005[נחלקו],\u0006 כי \u0003ר' ישמעאל סבר:\u0004 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 ב\u0003שבת אטו\u0004 \u0005[משום]\u0006 \u0003חול,\u0004 וכיון שביום חול מאחרים את הקרבת התמיד לשמונה וחצי משום הקרבת הנדבות — אף בשבת עושים כן, כדי שלא לשנות. \u0003ור' עקיבא סבר: לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","ומקשים: \u0003אי לא גזרינן\u0004 \u0005[אם אין אנו גוזרים]\u0006 אם כן, מדוע אנו מאחרים את הקרבת התמיד לשעה שבע ומחצה? \u0003ניעבדיה\u0004 \u0005[נעשנו]\u0006 \u0003בשש ומחצה!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 ר' עקיבא: \u0003מוספין קודמין לבזיכין,\u0004 ולכן \u0003מוספין\u0004 עושים אותם בשעה \u0003שש ובזיכין בשבע ועביד ליה\u0004 \u0005[ועושים אותו]\u0006 את ה\u0003תמיד בשבע ומחצה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטות הסבר אלה מתוך ברייתא אחרת ששנינו בה: \u0003תמיד כל השנה כולה קרב כהלכתו\u0004 כלומר, \u0003נשחט בשמונה ומחצה וקרב בתשע ומחצה, ובערב הפסח נשחט בשבע ומחצה וקרב בשמונה ומחצה, חל להיות בשבת כחל להיות בשני בשבת\u0004 כלומר סתם יום חול. משמע שאם ערב פסח חל להיות בשבת, אין משנים בין חול לשבת, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 אם חל להיות בשבת סדרו אז \u0003כסידרו בערב הפסח,\u0004 שמקדימים אותו לשש ומחצה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003אביי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שהרי כך הסביר את הברייתא הקודמת, \u0003אלא לרבא קשיא\u0004 \u0005[קשה].\u0006 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רבא: לא תימא\u0004 \u0005[אל תאמר]\u0006 לשון זו \u0003\"כחל בשני בשבת\" אלא אימא\u0004 \u0005[אמור]\u0006 \u0003כשני בשבת דעלמא\u0004 \u0005[סתם],\u0006 ולפרש: אם חל ערב הפסח בשבת אין משנים ועושים את התמיד כמו ביום חול רגיל בשמונה ומחצה, וכהסברו של רבא.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת: \u0003חל להיות\u0004 ערב פסח \u0003בשבת\u0004 מקריבים את התמיד \u0003כסידרו כל השנה כולה\u0004 בשמונה ומחצה — \u0003דברי ר' ישמעאל. ר' עקיבא אומר: כסידרו בערב הפסח דעלמא\u0004 \u0005[סתם],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רבא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שברייתא זו מפורש בה כדבריו, \u0003אלא\u0004 לשיטת \u0003אביי קשיא\u0004 \u0005[קשה]!\u0006","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003אביי: לא תימא\u0004 \u0005[אל תאמר,\u0006 תגרוס\u0005]\u0006 באותה ברייתא \u0003\"כסידרו כל השנה\"\u0004 לדברי ר' ישמעאל, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כסידרו כל השנים כולן דברי ר' ישמעאל\u0004 כלומר, שאין משנים בין ערב הפסח שחל להיות בשבת לחל בשאר ימי השנה, ומקריבים אף בו בשבע ומחצה, וכשיטת אביי. \u0003ר' עקיבא אומר:\u0004 לשיטה זו לא כן אלא \u0003כסידרו בערב הפסח שחל להיות בערב שבת,\u0004 כך יש להשלים את הדברים לשיטת אביי.","כיון שהוזכרה מקודם קדימת קרבן התמיד, מביאים ברייתא המבארת זאת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שלא יהא דבר\u0004 קרבן \u0003קודם לתמיד של שחר — תלמוד לומר:\u0004 \"והאש על המזבח תוקד בו לא תכבה וביער עליה הכהן עצים בבקר בבקר \u0003וערך עליה העלה\u0004 והקטיר עליה חלבי השלמים\" (ויקרא ו, ה). ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד]?\u0006 כלומר, כיצד למדים מכאן שעולה זו משמעה תמיד של שחר? \u0003אמר רבא: \"העלה\"\u0004 משמעה: \u0003עולה ראשונה\u0004 והיא עולת התמיד, הראשונה בזמן ובחשיבות.","ועוד אמרו: \u0003ומנין שאין דבר קרב אחר תמיד של בין הערבים — תלמוד לומר: \"והקטיר עליה חלבי השלמים\".\u0004 ושוב שואלים: \u0003מאי תלמודא\u0004 \u0005[מה הוא הלימוד]\u0006 שיש בכך? \u0003אמר אביי:\u0004 הכוונה היא \u0003\"עליה\"\u0004 על העולה הראשונה מקריבים את קרבן ה\u0003שלמים\u0004 כלומר, נדרים ונדבות השלמים שמביאים בכל היום כולו, \u0003ולא על חבירתה\u0004 העולה של בין הערבים מקריבים \u0003שלמים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על שיטת הסבר זו \u0003רבא:\u0004 אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003שלמים הוא\u0004 ש\u0003לא נקריב\u0004 אחר תמיד של בין הערבים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עולות נקריב,\u0004 שלפי לימוד זה לא נאמרו דברים אלה אלא בשלמים! \u0003אלא אמר רבא: \"השלמים\"\u0004 יש לדרוש \u0003עליה\u0004 על עולת הבוקר, \u0003השלם כל הקרבנות כולן\u0004 ולא אחר תמיד של בין הערבים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 : קרבן ה\u0003תמיד קודם\u0004 להקרבת ה\u0003פסח, פסח קודם\u0004 להקטרת ה\u0003קטרת\u0004 שמקטירים בין הערביים. הקטרת ה\u0003קטרת קודמת\u0004 להדלקת \u0003נרות\u0004 של מנורת המקדש,"],["\u0003יאוחר דבר\u0004 (קרבן הפסח) \u0003שנאמר בו \"בערב\"\u0004 כאמור \"תזבח את הפסח בערב כבוא השמש מועד צאתך ממצרים\" (דברים טז, ו), וגם נאמר בו \u0003\"בין הערבים\"\u0004 כאמור \"ושחטו אותו כל קהל עדת ישראל בין הערבים\" (שמות יב, ו), \u0003לדבר\u0004 (קרבן התמיד) \u0003שלא נאמר בו אלא \"בין הערבים\" בלבד\u0004 כאמור \"ואת הכבש השני תעשה בין הערבים (במדבר כח, ד).","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמכאן אתה למד דין איחור קרבן הפסח לקרבן התמיד, אם כן \u0003קטרת ונרות נמי נקדמו\u0004 \u0005[גם כן יקדמו]\u0006 \u0003לפסח,\u0004 שכן \u0003יאוחר דבר\u0004 (קרבן הפסח) \u0003שנאמר בו \"בערב\" ו\"בין הערבים\", לדבר שלא נאמר בו אלא \"בין הערבים\" בלבד,\u0004 שבהקטרת קטורת בערב והדלקת הנרות נאמר רק \"ובהעלות אהרן את הנרות בין הערבים יקטירנה קטורת תמיד לפני ה' לדורותיכם\" (שמות ל, ח)!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לענין הנרות ש\u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 במפורש שנאמר שם \u0003\"אתו\",\u0004 שבא להדגיש את איחורו. וביאור הענין: \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בנרות \"באהל מועד מחוץ לפרוכת אשר על העדות יערוך אותו אהרן ובניו מערב עד בוקר לפני ה' חוקת עולם לדורותם מאת בני ישראל\" (שמות כז, כא), אמרו \u0003\"מערב עד בקר\" — תן לה\u0004 למנורה שמן כדי \u0003מדתה שתהא דולקת מערב עד בוקר.\u0004","ועוד אמרו \u0003דבר אחר\u0004 על אותו מקרא: \u0003אין לך עבודה שכשירה מערב עד בוקר אלא זו בלבד\u0004 ושאר עבודות עבודות יום הן. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 למדים שאין עבודה אחרת שדינה כן — ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"\u0003יערוך אותו אהרן ובניו מערב עד בקר\u0004\", להדגיש: \u0003אותו מערב עד בקר ואין דבר אחר מערב עד בוקר.\u0004","\u0003ואיתקש\u0004 \u0005[והוקש,\u0006 הושווה\u0005]\u0006 בכתוב \u0003קטרת לנרות,\u0004 שנאמר במפורש שבזמן העלאת הנרות מקטירים את קטורת הערב (\"ובהעלות אהרן את הנרות בין הערבים יקטירנה\"). ומתוך זה למדנו שאין להתחיל כל עבודה אחרי עבודת הקטורת ועריכת הנרות ובכלל זה אף את הפסח.","הסברנו איפוא את השיטה הקודמת ומקורותיה. אכן יש להעיר כי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 מפורשת \u0003כי קושיין\u0004 \u0005[כמו,\u0006 לפי, \u0005הקושיה שלנו]\u0006 שמצויה בה סברה שונה: קרבן ה\u0003תמיד קודם לקטרת, קטרת קודמת לנרות, ונרות קודמות לפסח,\u0004 וראיה לדבר \u0003יאוחר דבר\u0004 (קרבן הפסח) \u0003שנאמר בו \"בערב\" \"ובין הערבים\" לדבר\u0004 (קטורת ונרות) \u0003שלא נאמר בו אלא \"בין הערבים\" בלבד.\u0004","ושואלים: והלוא כפי שנאמר לעיל \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אתו\",\u0004 ללמדנו שזו עבודה אחרונה! ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"אתו\" מיבעי ליה למעוטי\u0004 \u0005[צריך לו למעט]\u0006 \u0003עבודה\u0004 שעושים \u0003בפנים\u0004 בתוך ההיכל, שלא כפסח שנעשה בחוץ, בעזרה. ושואלים: \u0003ומאי ניהו\u0004 \u0005[ומה היא]\u0006 עבודה זו? ומשיבים: אותה עבודה \u0003קטרת, סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ובהעלת אהרן את הנרת בין הערבים יקטירנה\"\u0004 (שמות ל, ח), \u0003אימא\u0004 \u0005[אמור]:\u0006 שמא \u0003נדליק נרות ברישא\u0004 \u0005[תחילה]\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003נקטיר קטורת,\u0004 שאין הכתוב אומר בדיוק איזו משתי אלה קודמת, לכן \u0003מיעט רחמנא\u0004 \u0005[התורה]\u0006 \u0003\"אתו\"\u0004 שאין כל עבודה אחרת נעשית בהיכל אחר זמן זה.","ושואלים: \u0003אלא,\u0004 אם כך ההלכה, \u0003\"בין הערבים יקטירנה\" למה לי?\u0004 הלוא אין צורך בתוספת זו! ומשיבים: \u0003הכי קאמר רחמנא\u0004 \u0005[כך אמרה התורה]\u0006 לא בא המקרא הזה לקבוע זמן להדלקת הנרות אלא לומר \u0003בעידן דמדלקת\u0004 \u0005[בזמן שאתה מדליק]\u0006 \u0003נרות תהא מקטרא\u0004 \u0005[מוקטרת כבר]\u0006 ה\u0003קטרת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לך דבר שקודם\u0004 להקרבת \u0003תמיד של שחר אלא קטרת בלבד שנאמר בה \"בבקר בבקר\".\u0004 ואנו למדים: \u0003יוקדם קטרת\u0004 שהיא \u0003דבר שנאמר בו \"בבקר בבקר\" דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והקטיר עליו אהרן קטרת סמים בבקר בבקר\u0004 בהטיבו את הנרות יקטירנה\u0003\"\u0004 (שמות ל, ז), \u0003לדבר שלא נאמר בו אלא בקר אחד\u0004 והוא קרבן התמיד שנאמר בו \"את הכבש אחד תעשה בבוקר (במדבר כח, ד).","וכן \u0003אין לך דבר שמתעכב\u0004 שמאחרים אותו ל\u0003אחר תמיד של בין הערבים אלא קטרת ונרות ופסח,\u0004 וכן \u0003מחוסר כפורים בערב הפסח\u0004 מי שהיה טמא כגון מצורע או זב וטבל לטהרתו, שחייב עדיין בהקרבת קרבן ואסור לו לאכול בקדשים עד שיביא את קרבנו, והוא הקרוי מחוסר כיפורים, ושכח ולא הביא את קרבנו לפני הקרבת תמיד של בין הערבים, עשו לו תקנה מיוחדת ומקריבים את קרבנו אפילו לאחר התמיד, ו\u0003טובל שנית\u0004 לאחר הקרבת הקרבן ונעשה ראוי אף לקדשים \u0003ואוכל את פסחו לערב.\u0004","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר: אף מחוסר כפורים בשאר ימות השנה\u0004 מקריב את קרבנו לאחר התמיד של בין הערבים, ו\u0003טובל ואוכל בקדשים\u0004 שהקריב נדבה מבעוד יום \u0003לערב.\u0004","ושואלים: \u0003בשלמא לתנא קמא\u0004 \u0005[נניח\u0006 לשיטת \u0005התנא הראשון]\u0006 שמתירים הקרבה אחרי תמיד של בין הערביים רק למחוסר כיפורים בערב הפסח — יש טעם בדבר: \u0003יבא עשה\u0004 של \u0003פסח שיש בו כרת,\u0004 שהרי הראוי להקריב קרבן פסח ואינו מקריב חייב כרת, \u0003וידחה עשה דהשלמה\u0004 שהרי נאמר בתמיד של בין הערבים כמצוות עשה \"עליה השלם כל הקרבנות כולם\" אבל ודאי \u0003שאין בו כרת,\u0004 ולכן ידחה עשה זה מפני המצוה החמורה יותר של פסח. \u0003אלא\u0004 לשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא: מאי אולמיה דהאי עשה מהאי עשה\u0004 \u0005[מה תוקפו של עשה זה\u0006 של אכילת קדשים \u0005מעשה זה\u0006 של השלמת הקרבנות לפני תמיד של בין הערבים\u0005]?!\u0006","\u0003אמר רבינא אמר רב חסדא: הכא\u0004 \u0005[כאן]\u0006 מדובר במקרה מיוחד \u0003בחטאת העוף עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאותו מחוסר כפרה כגון מצורע עני צריך להביא רק קרבן עוף לחטאת, \u0003שאין למזבח אלא דמה\u0004 אבל אין מעלים את בשרה כלל למזבח (ונאכלת לכהנים). ולא נצטוו להשלים את מעשה הקרבנות על התמיד אלא לגבי הקטרת חלבים על המזבח, אבל הבאת הדם לאחר התמיד מותרת.","\u0003רב פפא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003בחטאת בהמה\u0004 ואף כאן אפשר לעשות זאת בלא לעבור על עשה דהשלמה, כיצד? שאת איברי החטאת הזו לא יקטירו בו ביום, אלא \u0003מעלה ומלינה בראשו של מזבח\u0004 ויקטירם למחרת לאחר הקרבת תמיד של שחר. שוודאי אם ילין את האימורים במקום אחר — יפסלו בלינה, אבל אם מעלה את הקרבן על גבי המזבח, אין הלינה פוסלת בו. ויתכן איפוא שיביא אדם את קרבנו בלא לעבור על מצות עשה של השלמה.","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם קרבן \u0003אשם\u0004 שמחוסר כיפורים, כגון זב ומצורע, מביא לא רק קרבן חטאת אלא גם אשם, ואשם אין מביאים אלא מן הכבשים. \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב פפא — היינו דמלין לה\u0004 \u0005[זהו\u0006 הפתרון גם באשם \u0005שמלין אותו]\u0006 \u0003אלא\u0004 לשיטת \u0003רב חסדא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אינו יכול להסתפק בהזאת דם בלבד! \u0003אמרי\u0004 \u0005[אומרים]:\u0006 לשיטת רב חסדא מדובר כאן במחוסר כיפורים שכבר \u0003קרב\u0004 אשמו, ואין לו אלא להביא קרבן חטאת כדי שיתכפר לגמרי ולזה יכול להביא אף עוף.","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם קרבן \u0003עולה\u0004 בקרבנות הכפרה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 קרבן \u0003עולה לא מעכבא\u0004 \u0005[אינו מעכב]\u0006 את הכפרה, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא\u0004 עצמו \u0003אומר: כשם שחטאתו ואשמו מעכבים אותו\u0004 את המצורע מלהחשב טהור גמור עד שיביא קרבנות אלה, \u0003כך עולתו מעכבתו!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותנסה לתרץ כמו קודם; \u0003בשקרבה עולתו\u0004 כבר, אולם, \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003קרבה עולתו קודם לחטאתו ראשון?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בענין האיש שטימא את המקדש או קדשיו \"והביא אותם אל הכהן \u0003והקריב את אשר לחטאת ראשונה\u0004 ומלק את ראשו ממול ערפו ולא יבדיל\" (ויקרא ה, ח), \"ראשונה\" \u0003מה תלמוד לומר\u0004 בענין הקדמת החטאת? \u0003אם ללמד שתהא\u0004 חטאת זו \u0003קודמת לעולה — הרי כבר נאמר \"ואת השני יעשה עלה כמשפט\"\u0004 (ויקרא ה, י) ואין צורך בשני פסוקים.","\u0003אלא: זה בנה אב\u0004 ויסוד ללמד דין כללי \u0003לכל חטאות\u0004 שמקריבים עם קרבנות אחרים \u0003שיהו קודמות לכל עולות הבאות עמהן,\u0004 שבכל מקרה החטאת היא הראשונה. \u0003וקימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שכלל זה יש לו תוקף עד כדי כך ש\u0003אפילו חטאת העוף קודמת לעולת בהמה!\u0004","\u0003אמר רבא:\u0004 יש לומר \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עולת מצורע\u0004 בדינה משאר החטאות והעולות \u0003דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר\u0004"],["בדיני המצורע: \u0003\"והעלה הכהן את העלה\"\u0004 (ויקרא יד, כ), ודורשים לשון זו: \"את העולה\" — זו \u0003שהעלה כבר.\u0004 ומכאן למדים שמותר בקרבן זה לשנות מן הסדר הרגיל ולהקדים את העולה לפני החטאת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמן בר אבא לרב פפא: לדידך\u0004 \u0005[לשיטתך]\u0006 ש\u0003אמרת: מעלה ומלינה בראשו של מזבח,\u0004 וכי \u0003קיימין ועבדינן מילתא לכהנים דאתו בה\u0004 \u0005[עומדים אנו ועושים דבר לכהנים שיבואו בו]\u0006 \u0003לידי תקלה, דסברי דיומיה הוא ואתו לאקטורי\u0004 \u0005[שסוברים הם\u0006 שחלבים אלה \u0005בני יומם הם\u0006 מקרבנות שנשחטו באותו יום \u0005ויבואו להקטירם\u0006 בו ביום\u0005]\u0006 בעוד שצריך לדחותם עד למחר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כהנים זריזין הן\u0004 ואפשר לסמוך עליהם שלא יכשלו, שזהירים הם ואף יודיעו לחבריהם להיזהר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: והא כמה דלא מתקטרי\u0004 \u0005[והרי כל עוד שאין מוקטרים]\u0006 ה\u0003אמורין\u0004 של החטאת \u0003כהנים לא מצו אכלי\u0004 \u0005[אינם יכולים לאכול מן]\u0006 ה\u0003בשר, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בענין השלמים \u0003יכול יהו כהנים רשאים\u0004 לאכול \u0003בחזה\u0004 וב\u0003שוק\u0004 המופרשים להם מקרבן השלמים עוד \u0003קודם הקטרת אמורין\u0004 של הקרבן? \u0003תלמוד לומר\u0004 כאמור בכתוב \u0003\"והקטיר הכהן את החלב המזבחה\u0004 והיה החזה לאהרן ולבניו\u0003\"\u0004 (ויקרא ז, לא), ומכאן שחייב להקטיר תחילה את החלב \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"והיה החזה לאהרן ולבניו\".\u0004","ויודעים אנו: וכל \u0003כמה דכהנים לא אכלי בשר בעלים לא מתכפרי\u0004 \u0005[כל עוד שהכהנים אינם אוכלים את הבשר בעלי\u0006 הקרבן \u0005אינם מתכפרים],\u0006 שגמר כפרתם תלוי באכילת הכהן. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"ואכלו אתם אשר כפר בהם\u0004 למלא את ידם לקדש אתם וזר לא יאכל כי קודש הם\u0003\"\u0004 (שמות כט, לג) — \u0003מלמד שהכהנים אוכלים ובעלים מתכפרין\u0004 על ידי אכילת הכהנים. ואם כן, כיצד יתכפר מחוסר הכיפורים, כשהכהנים אינם יכולים לאכול מבשר קרבן החטאת עד למחר, כשיוקטרו האימורים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות באופן אחר משום עשה דהשלמה — \u0003עשאום\u0004 (החשיבו) את הקרבנות האלה \u0003כמי שנטמאו או שאבדו\u0004 החלבים, שבמקרה זה מותר לכהנים לאכול. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול נטמאו אמורין או שאבדו לא יהו כהנים זכאים בחזה ושוק,\u0004 כפי שאמרנו שהדבר תלוי בהקטרה למזבח — \u0003תלמוד לומר: \"והיה החזה לאהרן ולבניו\"\u0004 (ויקרא ז, לא), משמעו: \u0003מכל מקום\u0004 כלומר, מתנה מוחלטת היא, גם אם אירע שלא נעשו כל הדברים כמצוותם.","\u0003רב כהנא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 נאמר במקום אחד \u0003\"ולא ילין חלב חגי עד בקר\"\u0004 (שמות כג, יח), משמע: \u0003עד בוקר הוא דלא ילין, הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי \u0003כל הלילה כולה ילין\u0004 שמותר להלין את חלב הקרבן כל הלילה. ואילו במקום אחר \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"והקטיר עליה חלבי השלמים\"\u0004 (ויקרא ו, ה), ודרשנו: \u0003עליה השלם כל הקרבנות כולן,\u0004 משמע שיש להקטיר את החלבים של הקרבנות עוד לפני הקרבת תמיד של בין הערבים!","\u0003הוא מותיב לה והוא מפרק לה\u0004 \u0005[הוא מקשה\u0006 קושיה \u0005זו והוא\u0006 עצמו \u0005מתרץ אותה],\u0006 כאן מדובר \u0003כשנתותרו\u0004 \u0005[שנשארו]\u0006 לאחר שנזרק דמם ביום הקטרתם על תמיד של שחר, ולא הספיקו להקריבם לפני תמיד של בין הערבים, שאף שלכתחילה יש להביאם לפני התמיד, אבל אם נשארו — זמנם עד הבוקר.","וכן \u0003רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003רב ספרא לרב: כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד \u0003\"ולא ילין לבקר זבח חג הפסח\"\u0004 (שמות לד, כה), ומכאן נדייק: \u0003לבקר הוא\u0004 ש\u0003לא ילין הא\u0004 \u0005[הרי]\u0006 משמע כי \u0003כל הלילה ילין,\u0004 ואפילו איברי עולה שנשחטה בערב יום טוב שהוא חול, מותר להקריבם בליל יום טוב. \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במקום אחר \u0003\"עלת שבת בשבתו\u0004 על עלת התמיד ונסכה\u0003\"\u0004 (במדבר כח, י), ולמדו מכאן שאין מקריבים \u0003עולת חול בשבת ולא עולת חול ביום טוב,\u0004 ולפיכך אי אפשר להקריב את חלבי הפסח ביום טוב — שהרי הם עולת חול שאינה קרבה ביום טוב!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כבר רמייה ניהליה\u0004 \u0005[הקשה\u0006 קושיה \u0005זו לפניו]\u0006 \u0003ר' אבא בר חייא לר' אבהו, ושני ליה\u0004 \u0005[ותירץ לו]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בפסוק האומר שלא ילין החלב עד בוקר, אבל כל הלילה מותר בהקטרתו \u0003בארבעה עשר\u0004 בניסן \u0003שחל להיות בשבת עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003חלבי שבת קריבין ביום טוב,\u0004 שבמקרה מיוחד זה מותר להקריבם ביום טוב.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום\u0004 ש\u0003חלבי שבת קריבים ביום טוב, אנן ניקו ונימא ליה דהאי קרא\u0004 \u0005[אנו נקום ונאמר לו לאותו פסוק]\u0006 ש\u0003בארבעה עשר שחל להיות בשבת הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ורק במקרה מיוחד זה ולא כמשמעו? \u0003אמר\u0004 לו: \u0003שבקיה לקרא דהוא דחיק ומוקים אנפשיה\u0004 \u0005[הנח את המקרא\u0006 הזה \u0005שהוא דוחק, ומעמיד את עצמו]\u0006 במקרה מיוחד. שהרי הסתירה קיימת כאן, וחייבים לישבה באיזו שהיא דרך.","\u0003הפסח ששחטו שלא לשמו,\u0004 שבזמן שחיטה אמר שאין כוונתו לשחטו לשם פסח אלא לשם קרבן אחר כגון שלמים או עולה, או \u0003קבל\u0004 את הדם, או \u0003הלך\u0004 עם הדם למזבח, או \u0003זרק\u0004 את הדם על המזבח באמירה שיהא \u0003שלא לשמו, או\u0004 שעשה את \u0003העבודות לשמו ושלא לשמו\u0004 יחד \u0003או שלא לשמו ולשמו,\u0004 בכל אלה אם פסל בעבודה אחת — הפסח \u0003פסול.\u0004","\u0003כיצד\u0004 הוא האופן של \u0003לשמו ושלא לשמו\u0004 — כגון שאמר שכוונתו \u0003לשם פסח ולשם שלמים, שלא לשמו ולשמו\u0004 שאמר — \u0003לשם שלמים ולשם פסח.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 מה שאמרנו \"לשמו ושלא לשמו\", האם הכונה היא שחשב שתי מחשבות אלה \u0003בעבודה אחת תנן\u0004 \u0005[שנינו],\u0006 כגון שבשעת שחיטה אמר את שני הדברים כאחד. \u0003או בשתי עבודות תנן\u0004 \u0005[שנינו],\u0006 שאמר בעבודה אחת לשמו, ובעבודה אחרת מאלו הארבע אמר שלא לשמו?","והוא מבאר את ההבדל: האם נאמר כי \u0003בעבודה אחת תנן\u0004 \u0005[שנינו]\u0006 ולפיכך משנתנו כשיטת \u0003ר' יוסי היא,\u0004 ש\u0003אמר: אף בגמר דבריו אדם נתפס.\u0004 שנחלקו ר' יוסי ור' מאיר במקרה שאומר אדם שתהא בהמה עולה ושלמים שלדעת ר' מאיר דינה כעולה, שכיון שהוציא מפיו בתחילה לשון עולה — חלה קדושת עולה עליה ושוב אין קדושת שלמים יכולה לחול עליה. ור' יוסי אומר שגם דיבור אחרון יש לו חשיבות, ולכן יש בה גם קדושת עולה וגם קדושת שלמים, וממילא אינה ראויה להקרבה, אלא תימכר כשיפול בה מום, ובדמיה יקנו עולה ושלמים. משמע שלשיטת ר' יוסי כשאומר אדם דיבור שיש סתירה בין תחילתו וסופו, אין אומרים שרק ראשית דבריו היא הקובעת, ומבטלת מה שבא אחר כך. אלא גם מה שאמר בסוף יש לו חשיבות, ואפשר לתפוס — לקבל ולהתחשב גם בדבריו האחרונים.","\u0003דאי\u0004 \u0005[שאם]\u0006 משנתנו כשיטת \u0003ר' מאיר הא\u0004 \u0005[הרי]\u0006 \u0003אמר תפוס לשון ראשון\u0004 ודיבור שני שמדבר שוב אינו מועיל,"],["\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003בשתי עבודות תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שבעבודה אחת חשב מחשבה אחת, ובשניה מחשבה אחרת, ונאמר כי \u0003אפילו\u0004 לשיטת \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 בכלל \u0003\"תפוס לשון ראשון\" — הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר, אמורים \u0003בעבודה אחת, אבל בשתי עבודות מודה דמיפסיל\u0004 \u0005[שנפסל],\u0006 שכיון שאמר דיבור שני בזמן עבודה אחרת הרי גם הוא נחשב.","\u0003אמרי\u0004 \u0005[אומרים,\u0006 שואלים\u0005]:\u0006 \u0003אהייא\u0004 \u0005[על איזה]\u0006 קטע מן המשנה בעצם דנים אנו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 על מה שאמרנו \u0003שלא לשמו ולשמו,\u0004 הרי \u0003בין\u0004 שהיה הדבר \u0003בעבודה אחת בין בשתי עבודות, בין\u0004 לשיטת \u0003ר' מאיר בין\u0004 לשיטת \u0003ר' יוסי — איפסיל ליה מקמייתא\u0004 \u0005[נפסל לו מן\u0006 האמירה \u0005הראשונה],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לר' יוסי נמי\u0004 \u0005[גם כן]\u0006 \u0003\"אף בגמר דבריו אדם נתפס\" אית ליה\u0004 \u0005[יש לו],\u0006 אבל אין דעתו שהדיבור האחרון דווקא הוא העיקרי, אלא שמוסיף, שגם דיבור אחרון יש לו ערך מסויים. ולכן כיון שחשב על הפסח בתחילה שלא לשמו — מיד נפסל. \u0003אלא\u0004 הבעיה היתה בענין \u0003לשמו ושלא לשמו מאי\u0004 \u0005[מה\u0006 בדיוק ענינו\u0005]?\u0006","כדי לפתור בעיה זו מביאים מקורות שונים. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו במשנתנו: \u0003הפסח ששחטו שלא לשמו, וקבל והלך וזרק שלא לשמו\u0004 — פסול. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005]?\u0006 \u0003אי נימא כדקתני\u0004 \u0005[אם תאמר שהיה\u0006 בדיוק \u0005כפי ששנינו]\u0006 שכל ארבע עבודות אלו היו שלא לשמו, אם כן \u0003למה לי\u0004 לומר \u0003עד דמחשב לכולהו\u0004 \u0005[שחשב\u0006 בעבודות \u0005כולן]\u0006 בשחיטה, בקבלה, בהולכה ובזריקה? הלוא כבר \u0003מקמייתא איפסיל ליה\u0004 \u0005[מן הראשונה נפסל לו]\u0006 במחשבה ראשונה של פסול, בשעת שחיטה!","\u0003אלא לאו הכי קתני\u0004 \u0005[האם לא כך שנה],\u0006 וכך צריך להבין: \u0003הפסח ששחטו שלא לשמו, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שחטו לשמו וקבל והלך וזרק שלא לשמו. אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שחטו וקבל והלך לשמו, וזרק שלא לשמו\u0004 — נפסל. ואם כן \u0003הויא לה\u0004 \u0005[הרי הוא]\u0006 מחשבה ב\u0003שתי עבודות,\u0004 ונפתרה בעייתנו, שלפי זה המשנה היא אף כשיטת ר' מאיר.","ומקשים: אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה: \u0003לשמו ושלא לשמו,\u0004 ונברר \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשתי עבודות — היינו רישא\u0004 \u0005[הרי זו\u0006 בדיוק \u0005התחלת המשנה]\u0006 ואין טעם לחזור על כך, \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 על כורחנו נאמר שבפיסקה זו הכוונה שחשב \u0003בעבודה אחת,\u0004 ואם כן המשנה כשיטת \u0003ר' יוסי היא\u0004 ש\u0003אמר אף בגמר דבריו אדם נתפס,\u0004 ולא נפתרה איפוא השאלה ששאלנו.","ודוחים: \u0003לא, לעולם\u0004 אפשר להסביר שמדובר גם בסוף המשנה שחשב \u0003בשתי עבודות,\u0004 ומהו ההבדל בין תחילת המשנה לסופה: \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר \u0003דקאי\u0004 \u0005[שעומד]\u0006 בזמן עבודת \u0003שחיטה וקא מחשב\u0004 \u0005[ומחשב]\u0006 בה שתהא \u0003שחיטה\u0004 שלא לשמה, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003קאי\u0004 \u0005[עומד]\u0006 בזמן \u0003זריקה וקא מחשב\u0004 \u0005[ומחשב]\u0006 בזמן עבודת ה\u0003זריקה\u0004 שתהא שלא לשמה.","ואילו ב\u0003סיפא\u0004 \u0005[סופה]\u0006 של המשנה מדובר \u0003דקאי\u0004 \u0005[שעומד]\u0006 בזמן עבודת ה\u0003שחיטה וקחשיב\u0004 \u0005[ומחשב]\u0006 על ה\u0003זריקה\u0004 שתהא שלא לשמה, כגון ש\u0003אמר הריני שוחט את הפסח\u0004 מתוך כוונה שיהיה \u0003לשמו,\u0004 אבל כוונתי \u0003לזרוק\u0004 את \u0003דמו שלא לשמו. וקמשמע לן\u0004 \u0005[והשמיע לנו]\u0006 בכך חידוש בהלכה ש\u0003מחשבין מעבודה לעבודה\u0004 כלומר, שאפשר לפסול קרבן אף על ידי מחשבה כזו, שבשעת עבודה אחת חושב לפסול עבודה אחרת, \u0003והיינו בעיא\u0004 \u0005[וזוהי השאלה]\u0006 ששאל \u0003רב פפא\u0004 בזמנו: האם מחשבים מעבודה לעבודה.","כיון שלא נפתרה השאלה שלנו עדיין, יש צורך להביא ראיה אחרת; \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שנינו במשנתנו: \u0003או שלא לשמו ולשמו — פסול,\u0004 ונדקדק: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005]\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003בשתי עבודות, השתא\u0004 \u0005[\u0006הרי, \u0005עכשיו]\u0006 \u0003לשמו ושלא לשמו אמרת\u0004 כבר ש\u0003פסול\u0004 הוא, \u0003שלא לשמו ולשמו מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שנפסל?! הרי ברור שנפסל מיד במחשבה ראשונה!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שחשב את שתי המחשבות \u0003בעבודה אחת, ומדסיפא\u0004 \u0005[ומ\u0006כיון \u0005שסופה\u0006 של המשנה\u0005]\u0006 מדברת \u0003בעבודה אחת רישא נמי\u0004 \u0005[תחילתה\u0006 של המשנה \u0005גם כן]\u0006 \u0003בעבודה אחת\u0004 ומשנתנו כר' יוסי!","ודוחים: \u0003לא, לעולם\u0004 אפשר לפרש שמדובר \u0003בשתי עבודות, ובדין הוא דלא איצטריך\u0004 \u0005[שלא היה צריך לו]\u0006 לפרש דבר זה, ואפשר היה ללמדו מקל וחומר מן ההתחלה, אולם דבר זה הוא דבר שבסגנון ולא לצורך, ונשנה בגלל גרר הלשון \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 \u0003לשמו ושלא לשמו, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003שלא לשמו ולשמו.\u0004","ושוב מנסים להביא ראיה \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מה ששנינו במשנה אחרת: \u0003שחטו\u0004 את הפסח \u0003שלא לאוכליו\u0004 לצורך אנשים שאינם מסוגלים מבחינה גופנית לאכול אותו, או \u0003שלא למנוייו\u0004 לאלה שלא נמנו מתחילה על קרבן מסוים זה, או \u0003לערלים ולטמאין\u0004 שנאמר בתורה שאסור להם לאכול מקרבן הפסח — \u0003פסול. הכא פשיטא\u0004 \u0005[כאן פשוט]\u0006 שמדובר שחשב מחשבה זו \u0003בעבודה אחת\u0004 והיא עבודת השחיטה כמפורש, \u0003ומדסיפא\u0004 \u0005[ומ\u0006כיון \u0005שהסוף]\u0006 שהיא המשנה הבאה, מדברת \u0003בעבודה אחת — רישא נמי\u0004 \u0005[ההתחלה,\u0006 משנתנו, \u0005גם כן]\u0006 מדברת אפילו \u0003בעבודה אחת\u0004 שלא כר' מאיר!","ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייך]\u0006 וכי בהכרח הדברים צמודים וזהים?! \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כפי שהיא וזו כפי שהיא]\u0006 \u0003סיפא\u0004 \u0005[הסוף]\u0006 המשנה הבאה — מדברת \u0003בעבודה אחת, ורישא\u0004 \u0005[ההתחלה]\u0006 משנתנו \u0003אי\u0004 \u0005[או]\u0006 מדברת \u0003בעבודה אחת\u0004 ושלא כר' מאיר, \u0003אי\u0004 \u0005[או]\u0006 מדברת \u0003בשתי עבודות,\u0004 וכר' מאיר.","ושוב מציעים; \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו באותה משנה: שאם שחט \u0003לאוכליו ושלא לאוכליו — כשר.\u0004 ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 שחישב \u0003בשתי עבודות\u0004 ששחטו לאוכליו על מנת לזרוק שלא לאוכליו, \u0003וטעמא\u0004 \u0005[והטעם]\u0006 שכשר, דווקא מפני \u0003דחשיב\u0004 \u0005[שחשב]\u0006 מחשבת פסול בשעת עבודה אחרת כגון \u0003בזריקה,\u0004 ומדוע — לפי ש\u0003אין מחשבת אוכלין בזריקה\u0004 שהמחשבה להאכיל את הפסח למי שאינו ראוי אינה פוסלת בשעת זריקה אלא בשעת שחיטה בלבד.","\u0003הא\u0004 \u0005[הרי]\u0006 מכאן נסיק כי \u0003בעבודה אחת כגון בשחיטה דמהניא ביה\u0004 \u0005[שמועילה בה]\u0006 \u0003מחשבת אוכלין\u0004 יהא \u0003פסול, והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003מקצת אוכלין לא פסלא,\u0004 שאם רק מקצת מאוכלי הפסח פסולים מלאוכלו כמו במקרה זה אינו נפסל על ידי כך!"],["\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שחישב בזמן \u0003עבודה אחת\u0004 וכשרה, \u0003ומדסיפא\u0004 \u0005[ומכיון שסופה]\u0006 של משנה זו \u0003בעבודה אחת — רישא נמי\u0004 \u0005[תחילתה גם כן]\u0006 בלשמו ושלא לשמו מדובר \u0003בעבודה אחת,\u0004 ופסול משום שאדם נתפס אף בגמר דבריו, וכדברי ר' יוסי!","ודוחים כפי שדחינו כבר: \u0003מידי איריא\u0004 \u0005[וכי שייך]?!\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כפי שהיא וזו כפי שהיא]\u0006 ואין הכרח להשוות ויש לומר ש\u0003סיפא\u0004 \u0005[סופה]\u0006 של המשנה \u0003בעבודה אחת, ורישא\u0004 \u0005[ותחילתה]\u0006 של משנה זו \u0003או בעבודה אחת או בשתי עבודות,\u0004 ולא נמצא איפוא פתרון גמור לשאלה ששאל רב פפא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: קרבן \u0003פסח ששחטו בשאר ימות השנה\u0004 שלא בערב פסח, אם שחיטתו היתה \u0003לשמו ושלא לשמו, מהו?\u0004 וצדדי השאלה: \u0003מי אתי\u0004 \u0005[האם בא]\u0006 האם בכוח המחשבה שחישב עליו \u0003שלא לשמו ומפיק ליה\u0004 \u0005[ומוציא אותו]\u0006 \u0003מידי לשמו\u0004 ועל ידי כך \u0003מכשיר ליה\u0004 \u0005[אותו]\u0006 \u0003או לא?\u0004 שהלכה קבועה היא שקרבן פסח שנשחט שלא לשם פסח שלא בזמנו — דינו כשלמים, וכשר. והשאלה היא האם במחשבה חלקית שלא לשמו אלא לשם שלמים אפשר להכשירו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי שמועה,\u0006 שאלה זו, \u0005בפני]\u0006 \u0003ר' ירמיה\u0004 וכך נימקתי דעתי: \u0003הואיל\u0004 ומחשבה \u0003לשמו מכשירו\u0004 בזמנו בערב הפסח, ומחשבה \u0003שלא לשמו\u0004 היא \u0003מכשירו שלא בזמנו,\u0004 ויש מקום להשוות ולומר: \u0003מה\u0004 מחשבת \u0003לשמו המכשירו בזמנו — אין מוציאו מידי שלא לשמו,\u0004 שאם חשב לשמו ושלא לשמו אומרים אנו שהוא פסול, \u0003אף\u0004 לענין מחשבה שלא לשמו \u0003המכשירו שלא בזמנו\u0004 נאמר כי \u0003אין מוציאו מידי לשמו — ופסול,\u0004 ונסכם כאן שכל מחשבה על קרבן שמעורבת בה מחשבה הפוסלת ומחשבה המכשירה — הקרבן פסול. \u0003ואמר\u0004","\u0003לי\u0004 ר' ירמיה: \u0003לא,\u0004 אין לסמוך על נימוק זה, \u0003אם אמרת בשלא לשמו שכן נוהג בכל הזבחים,\u0004 שכן הפסול בקרבן ששוחטים אותו שלא לשמו קיים בכל הזבחים שכולם נפסלים במידה מסויימת אם חושבים עליהם שלא לשמם, \u0003תאמר\u0004 בפסול של \u0003לשמו\u0004 שכאשר שוחטים את הפסח לשמו בשאר ימות השנה \u0003שכן אינו נוהג בכל הזבחים אלא בפסח בלבד,\u0004 שהרי שאר הקרבנות אם חושבים עליהם לשמם שלא בזמנם אינם נפסלים, ורק בפסח בלבד פוסלת מחשבה זו.","כיון שנדחתה סברתו של רב דימי שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו שלא ניתן לה עדיין פתרון? \u0003אמר רבא: פסח ששחטו בשאר ימות השנה\u0004 וחשב עליו \u0003לשמו ושלא לשמו — כשר.\u0004 וטעמו של דבר \u0003דהא סתמו לשמו קאי\u0004 \u0005[שהרי סתם\u0006 קרבן פסח זה \u0005לשמו הוא עומד]\u0006 שהרי לא הפקיע אותו בדבריו או במחשבה מהיות קרבן פסח, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003כי שחיט ליה\u0004 \u0005[כאשר שוחט אותו]\u0006 \u0003שלא לשמו — כשר,\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 נסיק: \u0003אתי\u0004 \u0005[בא]\u0006 \u0003שלא לשמו ומפיק ליה\u0004 \u0005[ומוציא אותו]\u0006 \u0003מידי לשמו\u0004 שבכוחה של אמירה שאומר שמקריב את הקרבן שלא לשמו אלא לשם שלמים — להפקיע אותו מסתמו שעשוי לקרבן פסח. ואם כן נאמר \u0003כי שחיט נמי\u0004 \u0005[כאשר שוחט גם כן]\u0006 \u0003לשמו ושלא לשמו\u0004 אפשר לומר כי \u0003אתי\u0004 \u0005[בא]\u0006 כוח \u0003שלא לשמו ומפיק ליה\u0004 \u0005[ומוציא אותו]\u0006 \u0003מידי לשמו,\u0004 שגדול כוח הפקעה של האמירה שלא לשמו משלא בזמנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: דילמא שאני היכא דאמר מהיכא דלא אמר\u0004 \u0005[שמא שונה מקום שאמר למקום שלא אמר]\u0006 ויש להבדיל בין המקרה בו אמר במפורש שהוא שוחט את הקרבן לשמו ושלא לשמו, ובין המקרה של קרבן שלא נתפרש עניינו. וראיה לדבר \u0003דהא\u0004 \u0005[שהרי]\u0006 שהמחשב בקרבן בפסח ושוחטו \u0003לאוכליו ושלא לאוכליו — כשר, וכל היכא דשחיט ליה שלא לאוכליו לחודיה\u0004 \u0005[וכל מקום ששוחט אותו\u0006 את הפסח \u0005שלא לאוכליו בלבד]\u0006 — \u0003פסול, ואמאי\u0004 \u0005[ומדוע]?\u0006 הרי אפשר לומר \u0003הא סתמא לאוכליו קאי\u0004 \u0005[הרי סתמו לאוכליו עומד הוא].\u0006 משמע: שאין אומרים שכל סתם הרי הוא כאילו אמר, \u0003אלא שאני היכא דאמר מהיכא דלא אמר\u0004 \u0005[שונה מקום שאמר ממקום שלא אמר].\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לענין פסח שלא בזמנו, \u0003שאני היכא דאמר מהיכא דלא אמר\u0004 \u0005[שונה מקום שאמר ממקום שלא אמר]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003מידי איריא\u0004 \u0005[וכי שייך]\u0006 להשוות? \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 לענין פסח וקדושתו לשמו \u0003כמה דלא עקר ליה בשחיטה סתמיה ודאי לשמו קאי\u0004 \u0005[כל זמן שלא עקר\u0006 את שם הפסח בשעת \u0005שחיטה סתמו ודאי לשמו עומד]\u0006 שאינו יכול להיעקר מקדושת הפסח אלא על ידי שינוי שם במפורש. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 לענין פסח שלא לאוכליו וכו' \u0003סתמיה לאוכליו קאי\u0004 \u0005[וכי סתמו לאוכליו עומד]\u0006 ואין דרך אחרת להפקיעו?!","והלוא אין הדבר כן, כי כל קרבן פסח \u0003דילמא מימשכי הני ואתי אחריני ומימני עלויה\u0004 \u0005[שמא משכו אלה\u0006 המנויים עליו את ידיהם ממנו \u0005ויבואו אחרים וימנו עליו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נמנין\u0004 על הפסח \u0003ומושכין את ידיהם ממנו\u0004 כלומר, מוותרים על מינוי זה \u0003עד שישחט.\u0004 ולפיכך יתכן שקרבן פסח זה לא יהיה ראוי למנוייו ולאוכלים בשעת שחיטתו, ומשום כך יש להבדיל לענין זה בין המפרש לבין מי שאינו מפרש, כיון שסתמו יכול להיות מופקע מדין הקרבן. מה שאין כן בפסח שלא בזמנו, שסתמו עומד לשם פסח ואינו יוצא מקדושת פסח עד שישונה שמו במפורש.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003פסח ששחטו בשאר ימות השנה בשינוי בעלים\u0004 כלומר, שלא לשם בעליו הראשונים \u0003מהו?\u0004 האם נאמר כי \u0003שינוי בעלים כשינוי קודש דמי\u0004 \u0005[נחשב]\u0006 וכשם שקרבן פסח ששינה אותו במין הקדושה משם פסח לשם שלמים דינו אז כקרבן שלמים, האם גם כששינה וחשב עליו שלא לשם בעליו (שפסח בזמנו שלא לשם בעליו — נפסל) הופקע מקדושת פסח ודינו כדין שלמים \u0003ומכשיר ליה\u0004 \u0005[אותו]\u0006 כשלמים שלא בזמנו \u0003או לא\u0004 — ועדיין דינו כקרבן פסח, והריהו כפסח פסול?","\u0003אמר רב פפא, אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי שמועה,\u0006 הלכה זו, \u0005לפני]\u0006 \u0003רבא\u0004 וכן נימקתי את דברי: \u0003הואיל ושינוי קודש פוסלו\u0004 לקרבן \u0003בזמנו\u0004 שאם חשב עליו בזמנו לשם שלמים — נפסל, ואף \u0003שינוי בעלים\u0004 אם חשב עליו שלא לשם בעליו — \u0003פוסלו בזמנו.\u0004 נוכל לעשות השוואה זו: \u0003מה שינוי קודש\u0004 שהוא \u0003פוסלו בזמנו — מכשירו\u0004 לקרבן \u0003לאחר זמנו, אף שינוי בעלים שפוסלו בזמנו\u0004 — \u0003מכשירו\u0004 לקרבן \u0003לאחר זמנו.\u0004","\u0003ואמר לי\u0004 רבא: \u0003לא,\u0004 אין לקבל השוואה זו; \u0003אם אמרת בשינוי קודש שכן פסולו\u0004 נעשה \u0003בגופו\u0004 של הקרבן שהרי הפסול הוא בעצם קדושת הקרבן \u0003וישנו בארבע עבודות\u0004 שהפסול שעל ידי שינוי קודש יכול להיעשות לא רק בזמן שחיטה אלא בכל אחת מארבע עבודות ההקרבה,"],["\u0003וישנו לאחר מיתה\u0004 שאם הקדיש אדם קרבן ומת, מביא בנו את הקרבן במקומו, וקרבן זה יכול להיפסל על ידי מחשבה בשינוי קודש וצריך להביא קרבן אחר, וישנו פסול זה של שינוי קודש בקרבן \u0003צבור\u0004 כמו בקרבן \u0003יחיד. תאמר בשינוי בעלים\u0004 שאינו כן, ש\u0003אין פסולו בגופו ואינו בארבע עבודות\u0004 אלא בשחיטה בלבד \u0003ואינו לאחר מיתה\u0004 שהרי אין בעלים ממש לקרבן זה שהרי הוא מת ואם שינה שמו כשר, \u0003ואינו בצבור כביחיד\u0004 שהרי לא שייך לשנות את שם בעליו שהוא הציבור לשם אחר.","\u0003ואף על גב דתרתי לאו דוקא\u0004 \u0005[ואף על פי ששנים\u0006 מן ההבדלים \u0005אינם מדויקים]\u0006 ואפשר לערער עליהם כאשר יבואר, \u0003תרתי מיהא דוקא\u0004 \u0005[שנים מכל מקום מדויקים].\u0006 ומסבירים את חוסר הדיוק: \u0003דמאי שנא\u0004 \u0005[שמה שונה]\u0006 \u0003שינוי בעלים\u0004 שאמרנו \u0003דלא הוי?\u0004 \u0005[שאין]\u0006 \u0003פסולו בגופו\u0004 משום ש\u0003פסולו מחשבה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003היא\u0004 ואין הפסול בגופו של הקרבן, ואם כן אפשר לומר כי \u0003שינוי קודש נמי\u0004 \u0005[גם כן]\u0006 \u0003פסולו מחשבה בעלמא\u0004 \u0005[בלבד]\u0006 היא ואין גופו של הקרבן נפסל, ואם כן אין זה הבדל אמיתי.","\u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר\u0004 ש\u0003שינוי בעלים אינו לאחר מיתה\u0004 אולם לשיטת \u0003רב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי\u0004 ש\u0003אמר\u0004 (זבחים ד,ב. וזבחים ז,ב): \u0003יש שינוי בעלים לאחר מיתה\u0004 ואם נשתנה שמו של הבעלים צריך בנו להביא קרבן אחר לשמו, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ולשיטה זו אין הבדל אף בנקודה זו. אולם \u0003תרתי מיהת דוקא נינהו\u0004 \u0005[שנים\u0006 מן ההבדלים \u0005בכל אופן מדוייקים הם].\u0006","\u0003אלא\u0004 יש לדחות את הצעת רב פפא, \u0003אמר רבא: פסח ששחטו בשאר ימות השנה בשינוי בעלים — נעשה כמי שאין לו בעלים\u0004 כלומר, ששחטו שלא לשם בעליו \u0003בזמנו\u0004 ואף הוא \u0003פסול.\u0004","שחטו את הפסח, \u0003שלא לאוכליו\u0004 כלומר לשם אנשים שאינם מסוגלים לאוכלו, או \u0003שלא למנויו\u0004 לשם אלה שלא נמנו מקודם לאכול ממנו, או שחטו \u0003לערלים ולטמאים\u0004 שנאמר בתורה שאסור להם לאכול מן הפסח — הרי זה \u0003פסול.\u0004 אולם אם שחטו \u0003לאוכליו ושלא לאוכליו למנויו ושלא למנויו, למולים ולערלים, לטמאים ולטהורים\u0004 — הרי זה \u0003כשר,\u0004 שאין מחשבה חלקית של פסול פוסלת.","\u0003שחטו\u0004 את הפסח \u0003קודם חצות\u0004 היום — \u0003פסול, משום שנאמר \"\u0004ושחטו אותו כל קהל עדת ישראל \u0003בין הערבים\"\u0004 (שמות יב, ו). \u0003שחטו קודם לתמיד\u0004 של בין הערבים — \u0003כשר, ובלבד שיהא אחד ממרס\u0004 (בוחש) \u0003בדמו\u0004 למניעת קרישתו \u0003עד שיזרק\u0004 דם קרבן \u0003התמיד\u0004 ואחר כך יזרקו את דם הפסח. \u0003ואם נזרק\u0004 דם הפסח לפני דם התמיד — בכל זאת \u0003כשר,\u0004 שאין שינוי זה פוסל את הקרבן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד שלא לאוכליו?\u0004 שחטו \u0003לשום חולה או לשום זקן\u0004 שאינם מסוגלים לאכול ממנו אפילו כזית. \u0003כיצד שלא למנויו?\u0004 אם \u0003נמנו עליו חבורה זו\u0004 של אוכלים, \u0003ושחטו לשם חבורה אחרת.\u0004","ושואלים: הלכה זו שאינה כתובה במפורש בתורה \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 ומביאים ממה \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב \"ואם ימעט הבית מהיות משה ולקח הוא ושכנו הקרוב אל ביתו, במכסת נפשות איש לפי אכלו תכוסו על השה\" (שמות יב, ד), ואמרו: \u0003\"במכסת\" — מלמד שאין הפסח נשחט אלא למנויו\u0004 שהכל נעשה לפי מכסת = מנין הנפשות שנמנו עליו לפני שחיטה,","\u0003יכול\u0004 שאם \u0003שחטו שלא למנויו יהא כעובר על המצוה\u0004 ובכל זאת יהא \u0003כשר\u0004 בדיעבד — \u0003תלמוד לומר\u0004 מן ההכפלה בלשון שנאמר שם פעמיים גם \u0003\"במכסת\"\u0004 וגם \u0003\"תכסו\", הכתוב\u0004 חזר ו\u0003שנה עליו\u0004 כדי \u0003לעכב.\u0004","\u0003רבי אומר:\u0004 \"תכוסו\" זה \u0003לשון סורסי\u0004 (ארמי) \u0003הוא, כאדם שאומר לחבירו כוס לי\u0004 משמע: שחוט לי \u0003טלה זה,\u0004 ללמד שמכסת הנפשות וקביעת המנויים צריכה להיות בזמן שחיטה.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ולמדנו מכאן שאם שחטו את הפסח \u0003שלא למנויו\u0004 הרי הוא פסול, אבל שחטו \u0003שלא לאוכליו מנא לן\u0004 \u0005[מנין לנו]\u0006 שהוא פסול? ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"איש לפי אכלו תכסו\",\u0004 הרי ש\u0003איתקש\u0004 \u0005[הושוו]\u0006 \u0003אוכלין למנויין,\u0004 כשם שפסול כששחטו שלא למנויו כך פסול כששחטו שלא לאוכליו."],["\u0003שחטו\u0004 את הפסח \u0003למולין\u0004 לשם אנשים נימולים, אבל חשב \u0003על מנת שיתכפרו בו ערלים בזריק\u0004ת הדם, שאף שאסורים לאכול ממנו שיתכפרו בזריקת דם הקרבן. \u0003רב חסדא אמר:\u0004 קרבן כזה \u0003פסול. רבה אמר: כשר.\u0004 ומבארים: \u0003רב חסדא אמר: פסול,\u0004 שלדעתו \u0003יש\u0004 תוקף ל\u0003מחשבת ערלים\u0004 להיות פוסלת בשעת \u0003זריקה. רבה אמר: כשר,\u0004 שלדעתו \u0003אין מחשבת ערלים\u0004 פוסלת \u0003בזריקה\u0004 אלא בשעת שחיטה בלבד.","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את הדעה הזו? \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יפסול\u0004 הערל את \u0003בני חבורה\u0004 הכשרים \u0003הבאין עמו ודין הוא,\u0004 הרי זה דבר שאפשר ללמוד בדרך ההגיון: \u0003הואיל וערלה\u0004 (היותו ערל) \u0003פוסלת\u0004 את קרבן הפסח שנשחט עבורו ואף \u0003טומאה פוסלת, מה טומאה — לא עשה בה מקצת טומאה ככל טומאה\u0004 שאם נשחט הפסח לצורך חבורה שהיה אחד ממנוייה טמא — אינו פוסל את הקרבן על כל החבורה כולה, \u0003אף ערלה לא עשה בה מקצת ערלה\u0004 שהיה אחד מן החבורה ערל, \u0003ככל ערלה\u0004 לפסול את הקרבן כאילו היו כל מנויים ערלים.","\u0003או\u0004 שמא \u0003כלך\u0004 (לך) ודון בענין זה \u0003לדרך זו: הואיל וערלה פוסלת\u0004 בקרבן ושינוי \u0003זמן פוסל, מה זמן\u0004 אם אמר בשעת שחיטה שרצונו לאכול את מקצת הקרבן מחוץ לזמן הקבוע לו \u0003עשה בה מקצת זמן ככל זמן\u0004 ופסל את הכל, \u0003אף ערלה, עשה בה מקצת ערלה ככל ערלה\u0004 ופסל הכל.","ודנים: \u0003נראה למי דומה\u0004 איזו השוואה נראית יותר, ונאמר: \u0003דנים דבר\u0004 (דין ערלה) \u0003שאינו נוהג בכל הזבחים מדבר\u0004 (מדין טומאה) \u0003שאינו נוהג בכל הזבחים,\u0004 שבשאר קרבנות יכול הטמא לשלוח את קרבנו ולהתכפר בו \u0003ואל יוכיח זמן שנוהג בכל הזבחים.\u0004","\u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך זו: דנין דבר\u0004 (דין ערלה) \u0003שלא הותר מכללו\u0004 ולא נמצא לו כל היתר \u0003מדבר\u0004 (שינוי זמן) \u0003שלא הותר מכללו\u0004 שלערלה בכל קרבן שהוא וכן לשינוי זמן אין כל היתר. \u0003ואל תוכיח טומאה — שהותרה מכללה\u0004 שהרי יש מקרים שבהם מותר להקריב את הפסח בטומאה, כגון כאשר כל ישראל כולם טמאים,","\u0003תלמוד לומר \"זאת\",\u0004 כאמור \"ויאמר ה' אל משה ואהרן: זאת חוקת הפסח כל בן נכר לא יאכל בו וכל עבד איש מקנת כסף ומלתה אותו אז יאכל בו\" (שמות יב, מג-מד). ויש לבאר: \u0003מאי\u0004 \u0005[מה]\u0006 משמע הלימוד מן ההדגשה \u0003\"זאת\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שבא ללמדנו ש\u0003כולה ערלה\u0004 — \u0003פסלה,\u0004 שאם כל החבורה היא של ערלים הריהי פסולה, אבל \u0003מקצתה\u0004 — \u0003לא פסלה, האי\u0004 \u0005[דבר זה]\u0006 \u0003מ\"וכל ערל\" נפקא\u0004 \u0005[יוצא]\u0006 שנאמר \"וכל ערל לא יאכל בו\" (שמות יב, מח), ולמדים מן הריבוי \"כל\" שאסור שיהו כולם ערלים","\u0003אלא לאו הכי קתני\u0004 \u0005[האם לא כך שנינו],\u0006 כלומר כך יש להבין: \u0003תלמוד לומר \"וכל ערל\"\u0004 — רק אם כל החבורה \u0003כולה ערלה — פסלה,\u0004 אבל אם רק \u0003מקצתה\u0004 ערלה — \u0003לא פסלה. וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הוא הדין\u0004 אף \u0003לזריקה\u0004 ש\u0003כולה ערלה מיהא\u0004 \u0005[בכל אופן]\u0006 \u0003פסלה,\u0004 שאם חושב בזמן זריקה שהוא זורק לשם ערלים בלבד יפסל הקרבן — \u0003תלמוד לומר \"זאת\"\u0004 לצמצם ולמעט ולומר \u0003בשחיטה הוא\u0004 הדין ש\u0003כולה ערלה מיהא\u0004 \u0005[בכל אופן]\u0006 \u0003פסלה, אבל זריקה אפילו כולה ערלה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פסלה.\u0004","\u0003וכי תימא מאי קולא\u0004 \u0005[ואם תאמר מהי ההקלה הזו]\u0006 שב\u0003זריקה\u0004 מבשחיטה, שאנו אומרים שדבר הפוסל בשעת שחיטה אינו פוסל בזריקה? טעמו של רבה הוא ש\u0003אין מחשבת אוכלין בזריקה\u0004 שפסול קרבן בפסח על ידי מחשבה שיאכלו פסולים — אינו נלמד אלא בשעת שחיטה ולא בעבודת הזריקה.","\u0003ורב חסדא\u0004 סבור \u0003אדרבה\u0004 \u0005[להיפך]\u0006 \u0003לאידך גיסא\u0004 \u0005[לצד אחר]\u0006 יש להבין: \u0003תלמוד לומר \"וכל ערל\"\u0004 משמע — \u0003כולה ערלה פסלה,\u0004 אבל \u0003מקצתה לא פסלה,\u0004 ואימתי — בשעת שחיטה, \u0003אבל\u0004 בשעת \u0003זריקה — אפילו מקצתה נמי פסלה\u0004 \u0005[\u0006חשב \u0005על מקצת\u0006 ערלים \u0005גם כן פסל].\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הוא הדין לזריקה\u0004 כבשחיטה ש\u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כולה ערלה לא פסלה, תלמוד לומר \"זאת\"\u0004 להגביל וללמד: \u0003שחיטה הוא\u0004 ש\u0003מקצתה לא פסלה, אבל זריקה אפילו מקצתה פסלה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003ומאי חומריה\u0004 \u0005[ומהי חומרתה]\u0006 של \u0003זריקה\u0004 מבשחיטה, שאנו אומרים שדבר שאינו פוסל בשחיטה פוסל בזריקה? יש לומר: ש\u0003לא מקבע פיגול אלא בזריקה\u0004 כי עד עבודת הזריקה שהיא אחרונה אם מצרפים מחשבת פסול אחר וכגון אכילה חוץ למקומו, בעבודה אין הקרבן נעשה פיגול אלא רק פסול בלבד, ואינו נחשב כפיגול להתחייב על אכילתו כרת אלא אם כל העבודות האחרות נעשו מתוך מחשבה כשרה או מתוך מחשבת פיגול (חוץ לזמנו), ודבר זה אינו מתברר אלא בעבודה האחרונה שהיא הזריקה, הרי שזריקה היא עבודה העלולה יותר לפסול במחשבה.","שיטת ביאור זו \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב אשי: ממאי דהאי\u0004 \u0005[ממה\u0006 מסיק אתה \u0005שזה]\u0006 \u0003\"וכל ערל\" כולה\u0004 \u0005[כל\u0006 החבורה\u0005]\u0006 \u0003משמע?\u0004 ומכאן ממשיך אתה לדון. \u0003דילמא האי\u0004 \u0005[שמא זה\u0006 הביטוי\u0005]\u0006 \u0003\"וכל ערל\" משמע כל דהו\u0004 \u0005[כלשהו]\u0006 \u0003ערלה\u0004 אפילו מקצת, ולכן \u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"זאת\",\u0004 ללמדנו ש\u0003עד דאיכא\u0004 \u0005[שיש]\u0006 חבורה ש\u0003כולה ערלה\u0004 (ערלים) \u0003לא פסלה, לא שנא\u0004 \u0005[אינו שונה]\u0006 בשעת \u0003שחיטה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 בשעת \u0003זריקה.\u0004 ומכאן שההוכחות והמחלוקת לא בתחום זה היו. \u0003אלא אמר רב אשי רב חסדא ורבה:\u0004"]]};
